B.bq2=new A.a("gen_iv_start_4","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac\uac00 \uac1c\uc2dc\ub41c \uc774\ud6c4 \uc2e0\uace0\uc778\uc758 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b7J,0,"\uc2e0\uace0\uc778\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc870\uc0ac\uc758 \ub2e8\ucd08\ub97c \uc81c\uacf5\ud558\ub294 \uc9c0\uc704\uc5d0 \uc788\uc73c\ub098, \uc870\uc0ac\uc640 \ucc98\ubd84\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ub3c5\uc790\uc801\uc73c\ub85c \uc218\ud589\ud558\ub294 \uac83\uc774\uba70 \uc2e0\uace0\uc778\uc774 \uc774\ub97c \uc9c1\uc811 \uc9c0\ud718\ud558\uac70\ub098 \ucc98\ubd84 \ub0b4\uc6a9\uc744 \uacb0\uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc808\ucc28 \uc9c4\ud589\uc0c1\ud669\uc5d0 \uad00\ud55c \ud1b5\uc9c0 \ub4f1 \uc77c\uc815\ud55c \uc808\ucc28\uc801 \uc9c0\uc704\ub294 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.apI,B.aEI,null)
B.b3A=s([u.yw,"\uc624\uc9c1 \ub300\ud1b5\ub839\uc758 \uac1c\ubcc4 \uc9c0\uc2dc\uac00 \uc788\uc744 \ub54c\ub9cc \uc9c1\uad8c\uc870\uc0ac\uac00 \uac00\ub2a5\ud558\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \ubc95\ub960\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \uac1c\ub150\uc774\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \uc2e0\uace0\uac00 \uc804\ud600 \uc5c6\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc808\ub300 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \ub9e4\ub144 \uc815\ud574\uc9c4 \ud2b9\uc815 \ub0a0\uc9dc\uc5d0\ub9cc \uac1c\uc2dc\ub420 \uc218 \uc788\ub2e4"],t.s)
B.b4B=s([u.yw],t.s)
B.a0d=s(["\uc9c1\uad8c\uc778\uc9c0\uc758 \uacc4\uae30"],t.s)
B.bz4=new A.a("gen_iv_start_5","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc9c1\uad8c\uc73c\ub85c \uc778\uc9c0\ud558\uc5ec \uc870\uc0ac\ub97c \uac1c\uc2dc\ud558\ub294 \ub300\ud45c\uc801\uc778 \uacc4\uae30\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b3A,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc5b8\ub860\ubcf4\ub3c4, \ub2e4\ub978 \uc0ac\uac74\uc744 \uc870\uc0ac\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ubc1c\uacac\ub41c \ub2e8\uc11c, \uc2dc\uc7a5\ub3d9\ud5a5 \ubaa8\ub2c8\ud130\ub9c1 \uacb0\uacfc \ub4f1 \ub2e4\uc591\ud55c \uacbd\ub85c\ub85c \ubc95 \uc704\ubc18 \ud610\uc758\ub97c \uc778\uc9c0\ud558\uc5ec \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc2e0\uace0\uac00 \uc5c6\ub354\ub77c\ub3c4 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \ubc95 \uc9d1\ud589\uc5d0 \ub098\uc124 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uae30\ub2a5\uc744 \ud55c\ub2e4.",B.b4B,B.a0d,null)
B.a2R=s([u.wB,"\uc5b4\ub5a0\ud55c \uc2e0\uace0\ub4e0 \uc811\uc218\ub418\uba74 \uc608\uc678 \uc5c6\uc774 \uc989\uc2dc \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c4\ub2e4","\ubb34\uae30\uba85 \uc2e0\uace0\ub294 \ubc95\ub960\uc0c1 \uc804\ud600 \uc811\uc218\ub420 \uc218 \uc5c6\ub2e4","\ud5c8\uc704\uc2e0\uace0\ub85c \ubc1d\ud600\uc9c0\uba74 \ud53c\uc2e0\uace0\uc778\uc5d0\uac8c \uc790\ub3d9\uc73c\ub85c \uc2b9\uc18c \ud310\uacb0\uc774 \ub0b4\ub824\uc9c4\ub2e4","\uc2e0\uace0\uc758 \uc9c4\uc704\uc640 \ubb34\uad00\ud558\uac8c \uc2e0\uace0\uc790\uc5d0\uac8c \ud56d\uc0c1 \ubcf4\uc0c1\uae08\uc774 \uc9c0\uae09\ub41c\ub2e4"],t.s)
