B.bwg=new A.a("gen_iv_obstruct_1","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud604\uc7a5\uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\xb7\uae30\ud53c\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.WR,0,"\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\xb7\uae30\ud53c\ud558\ub294 \ud589\uc704\ub294 \uc870\uc0ac\ubc29\ud574\ud589\uc704\ub85c\uc11c \ubcc4\ub3c4\uc758 \uacfc\ud0dc\ub8cc \ub4f1 \uc81c\uc7ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4. \uc774\ub294 \uc784\uc758\uc870\uc0ac \uc6d0\uce59 \ud558\uc5d0\uc11c\ub3c4 \uc2e4\ud6a8\uc801\uc778 \uc870\uc0ac\uac00 \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc720\uc778 \uc7a5\uce58\ub85c \uae30\ub2a5\ud55c\ub2e4.",B.WP,B.aPM,null)
B.aCS=s(["\uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \ud1b5\uc0c1\uc758 \ud611\uc870 \uc704\ubc18\ubcf4\ub2e4 \ub354 \uc911\ud558\uac8c \ucde8\uae09\ub420 \uc218 \uc788\ub2e4","\uc790\ub8cc \uc704\uc870\xb7\ubcc0\uc870\ub294 \uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc790\ub8cc\ub97c \uc704\uc870\ud574\ub3c4 \uc81c\ucd9c\ub9cc \ud558\uba74 \ud56d\uc0c1 \ubb38\uc81c\uc5c6\ub2e4","\uc704\uc870\ub41c \uc790\ub8cc \uc81c\ucd9c\uc740 \uc624\ud788\ub824 \uac10\uacbd\uc0ac\uc720\ub85c \uc778\uc815\ub41c\ub2e4","\uc790\ub8cc \uc704\uc870\xb7\ubcc0\uc870\ub294 \uc870\uc0ac\uc808\ucc28\uc640 \ubb34\uad00\ud55c \ubb38\uc81c\uc774\ub2e4"],t.s)
