B.buU=new A.a("gen_predatory_exam_4","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\ubd80\ub2f9\uc5fc\ub9e4 \uad00\ub828 \ubb38\uc81c\uc5d0\uc11c \uc790\uc8fc \ucd9c\uc81c\ub418\ub294 \ud568\uc815 \uc720\ud615\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.TF,0,'\ubd80\ub2f9\uc5fc\ub9e4 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc77c\uc2dc\uc801\uc778 \uac00\uaca9 \ud560\uc778\uc774\ub098 \uc7ac\uace0 \ucc98\ubd84\uc744 \uc704\ud55c \ud1b5\uc0c1\uc801\uc778 \ud310\ub9e4\ud589\uc704\ub97c \ubd80\ub2f9\uc5fc\ub9e4\uc640 \ub3d9\uc77c\uc2dc\ud558\ub294 \uc120\ud0dd\uc9c0\uac00 \ud568\uc815\uc73c\ub85c \uc790\uc8fc \ucd9c\uc81c\ub418\ubbc0\ub85c, \ube44\uc6a9 \uc774\ud558 \uac00\uaca9\uc758 "\uacc4\uc18d\uc131"\uacfc \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c\uc758 "\uc6b0\ub824"\ub77c\ub294 \uc694\uac74\uc744 \uc815\ud655\ud788 \uad6c\ubcc4\ud574 \ub450\uc5b4\uc57c \ud55c\ub2e4.',B.RA,B.cq,null)
