B.bFq=new A.a("gen_refuse_def_6","economic_law","\uac70\ub798\uac70\uc808","\uac70\ub798\uac70\uc808\uc758 \uc758\ubbf8\xb7\uc720\ud615",'\uac70\ub798\uac70\uc808 \uaddc\uc81c\uac00 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704(\ub2f4\ud569)\uc758 \uc77c\uc885\uc778 "\uac70\ub798\uac70\uc808 \ub2f4\ud569"\uacfc \uad6c\ubcc4\ub418\ub294 \uc9c0\uc810\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aP0,0,"\ubcf5\uc218\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc73c\ub85c \uac70\ub798\ub97c \uac70\uc808\ud558\ub294 \ud589\uc704\ub294 \uc0ac\uc548\uc5d0 \ub530\ub77c \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704(\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808)\ub85c \uaddc\uc728\ub420 \uc218\ub3c4 \uc788\uace0, \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704(\ub2f4\ud569)\ub85c \uaddc\uc728\ub420 \uc218\ub3c4 \uc788\ub294\ub370, \uc804\uc790\ub294 \ud2b9\uc815 \uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub824\ub294 \ubaa9\uc801\xb7\ud6a8\uacfc\uc5d0, \ud6c4\uc790\ub294 \uad00\ub828\uc2dc\uc7a5 \uc804\uccb4\uc758 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4\ub294 \uc810\uc5d0\uc11c \uaddc\uc728\uc758 \uad00\uc810\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4.",B.adI,B.aOn,null)
B.a8U=s([u.kV,"\uac70\ub798\ub97c \uac70\uc808\ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ub9cc\uc73c\ub85c \ud56d\uc0c1 \ubd80\ub2f9\uc131\uc774 \uc778\uc815\ub41c\ub2e4","\uac70\ub798\uc0c1\ub300\ubc29\uc774 \uac1c\uc778\uc801\uc73c\ub85c \uc11c\uc6b4\ud568\uc744 \ub290\ub07c\uba74 \ud56d\uc0c1 \ubd80\ub2f9\uc131\uc774 \uc778\uc815\ub41c\ub2e4","\uac70\ub798\uac70\uc808\uc758 \ubd80\ub2f9\uc131\uc740 \ud310\ub2e8\ud560 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub294 \uac1c\ub150\uc774\ub2e4","\uac70\ub798\uac70\uc808\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c \uc5ec\ubd80\ub9cc\uc744 \uacb0\uc815\ud558\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
B.aH1=s([u.kV],t.s)
B.aQ1=s(["\ub2e8\ub3c5 \uac70\ub798\uac70\uc808\uc758 \ubd80\ub2f9\uc131 \ud310\ub2e8\uae30\uc900"],t.s)
B.bBY=new A.a("gen_refuse_judge_1","economic_law","\uac70\ub798\uac70\uc808","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc815\ub2f9\ud654 \uc0ac\uc720","\ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\uc774 \ubd80\ub2f9\ud558\ub2e4\uace0 \uc778\uc815\ub418\uae30 \uc704\ud55c \ud310\ub2e8\uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a8U,0,"\ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\uc774 \ubd80\ub2f9\ud558\ub2e4\uace0 \uc778\uc815\ub418\ub824\uba74, \ub2e8\uc21c\ud788 \uac70\ub798\ub97c \uac70\uc808\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uadf8 \uac70\uc808\uc774 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub824\ub294 \ubaa9\uc801\uc774\ub098 \ud6a8\uacfc\ub97c \uac00\uc9c0\ub294\uc9c0, \uac70\ub798\uac70\uc808\ub85c \uc778\ud574 \uc0c1\ub300\ubc29\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc774 \uc2ec\ud788 \uace4\ub780\ud574\uc9c0\ub294\uc9c0 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aH1,B.aQ1,null)
B.VG=s([u.oh,"\uc774\uc720\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \ubd80\ub2f9\ud55c \uac70\ub798\uac70\uc808\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc2e0\uc6a9\ubd88\ub7c9\uc774\ub098 \uacc4\uc57d \uc704\ubc18\uc740 \uac70\ub798\uac70\uc808\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uc0ac\uc720\uc774\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\uac70\uc808\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub41c\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\uac70\uc808\uc740 \ubc18\ub4dc\uc2dc \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub97c \ud1b5\ud574\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4"],t.s)
B.aou=s([u.oh],t.s)
B.OG=s(["\uc815\ub2f9\ud55c \uc0ac\uc720\uc5d0 \uc758\ud55c \uac70\ub798\uac70\uc808"],t.s)
B.bFD=new A.a("gen_refuse_judge_2","economic_law","\uac70\ub798\uac70\uc808","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc815\ub2f9\ud654 \uc0ac\uc720","\uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc2e0\uc6a9\ubd88\ub7c9\uc774\ub098 \uacc4\uc57d \uc704\ubc18\uc744 \uc774\uc720\ub85c \ud55c \uac70\ub798\uac70\uc808\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.VG,0,"\uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc2e0\uc6a9\ubd88\ub7c9, \ub300\uae08 \ubbf8\uc9c0\uae09, \uacc4\uc57d \uc704\ubc18 \ub4f1 \ud569\ub9ac\uc801\uc774\uace0 \uc815\ub2f9\ud55c \uc0ac\uc720\uc5d0 \uae30\ucd08\ud55c \uac70\ub798\uac70\uc808\uc740, \uc0ac\uc5c5\uc790\uac00 \uc790\uc2e0\uc758 \uc815\ub2f9\ud55c \uc774\uc775\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \ud589\uc704\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \ubd80\ub2f9\ud55c \uac70\ub798\uac70\uc808\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aou,B.OG,null)
