B.bdm=new A.a("gen_ca_permit_relation_5","economic_law","\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc81c\ub3c4","\uc778\uac00\uc81c\ub3c4\uc640 \ub2e4\ub978 \uc81c\ub3c4\uc758 \uad00\uacc4","\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc81c\ub3c4\uc640 \ud6a8\uc728\uc131 \uc99d\ub300 \ud56d\ubcc0\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a9e,0,"\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc81c\ub3c4\ub294 \uc0ac\uc5c5\uc790\uac00 \uc0ac\uc804\uc5d0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub85c\ubd80\ud130 \uacf5\uc2dd\uc801\uc73c\ub85c \uc2b9\uc778\uc744 \ubc1b\ub294 \uc808\ucc28\uc778 \ubc18\uba74, \ud6a8\uc728\uc131 \uc99d\ub300 \ud6a8\uacfc\uc5d0 \ub530\ub978 \ud56d\ubcc0\uc740 \uc778\uac00\ub97c \ubc1b\uc9c0 \uc54a\uc740 \uacf5\ub3d9\ud589\uc704\uc5d0 \ub300\ud574 \uc0ac\ud6c4\uc801\uc73c\ub85c \uc704\ubc95\uc131\uc744 \ub2e4\ud22c\ub294 \uacfc\uc815\uc5d0\uc11c \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uc640 \ube44\uad50\ud615\ub7c9\ub418\ub294 \ud56d\ubcc0\uc0ac\uc720\ub77c\ub294 \uc810\uc5d0\uc11c \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ubc95\ub9ac\uc774\ub2e4.",B.ahv,B.adm,null)
B.b4N=s([u.nk,"\uc0ac\uc5c5\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc790\uc2e0\uc758 \ud310\ub9e4\uac00\uaca9\uc744 \uc778\uc0c1\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5 \uc0c1\ud669\uc744 \ubc18\uc601\ud574 \ub3c5\uc790\uc801\uc73c\ub85c \uac00\uaca9\uc744 \uc778\ud558\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \uacf5\uacf5\uc694\uae08\uc744 \uacb0\uc815\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc6d0\uac00 \uc0c1\uc2b9\uc744 \uc774\uc720\ub85c \uac1c\ubcc4\uc801\uc73c\ub85c \uac00\uaca9\uc744 \uc870\uc815\ud558\ub294 \ud589\uc704"],t.s)
