B.bn4=new A.a("gen_collusion_type_price_2","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uac00\uaca9\xb7\uac70\ub798\uc870\uac74 \uad00\ub828 \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uac70\ub798\uc870\uac74\uc774\ub098 \ub300\uae08\xb7\ub300\uac00\uc758 \uc9c0\uae09\uc870\uac74\uc744 \uc815\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a4A,0,'"\uac70\ub798\uc870\uac74\uc774\ub098 \ub300\uae08\xb7\ub300\uac00\uc758 \uc9c0\uae09\uc870\uac74\uc744 \uc815\ud558\ub294 \ud589\uc704"\ub294 \uac00\uaca9 \uc790\uccb4\ub294 \uc544\ub2c8\ub354\ub77c\ub3c4, \uacb0\uc81c \ubc29\uc2dd\xb7\ud560\ubd80\uc870\uac74\xb7\ub300\uae08 \uc9c0\uae09\uc2dc\uae30 \ub4f1 \uac70\ub798\uc870\uac74\uc5d0 \uad00\ud574 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud569\uc758\ud558\uc5ec \uc815\ud568\uc73c\ub85c\uc368 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.b5d,B.Tm,null)
B.a5R=s([u.X,"\uac00\uaca9 \ub2f4\ud569\uc740 \uc18c\ube44\uc790\uc5d0\uac8c \ud56d\uc0c1 \uc720\ub9ac\ud55c \uacb0\uacfc\ub9cc \uac00\uc838\uc624\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9 \ub2f4\ud569\uc740 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uac00 \uc804\ud600 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9 \ub2f4\ud569\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9 \ub2f4\ud569\uc740 \uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
