B.buN=new A.a("gen_collusion_type_price_3","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uac00\uaca9\xb7\uac70\ub798\uc870\uac74 \uad00\ub828 \uc720\ud615","\uac00\uaca9 \ub2f4\ud569\uc774 \ub2e4\ub978 \uc720\ud615\uc758 \ub2f4\ud569\ubcf4\ub2e4 \ud2b9\ud788 \uc5c4\uaca9\ud558\uac8c \uaddc\uc81c\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a5R,0,"\uac00\uaca9\uc740 \uc2dc\uc7a5\uc5d0\uc11c \uc0ac\uc5c5\uc790 \uac04 \uacbd\uc7c1\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac00\uc7a5 \ud575\uc2ec\uc801\uc778 \ubcc0\uc218\uc774\ubbc0\ub85c, \uac00\uaca9\uc5d0 \uad00\ud55c \ub2f4\ud569\uc740 \uadf8 \uc131\uc9c8\uc0c1 \uacbd\uc7c1\uc744 \uac00\uc7a5 \uc9c1\uc811\uc801\uc774\uace0 \uba85\ubc31\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud6a8\uacfc\ub97c \uac00\uc9c0\uba70, \uc774 \ub54c\ubb38\uc5d0 \uacbd\uc131 \uacf5\ub3d9\ud589\uc704\uc758 \ub300\ud45c\uc801 \uc720\ud615\uc73c\ub85c\uc11c \ub2e4\ub978 \uc720\ud615\ubcf4\ub2e4 \uc5c4\uaca9\ud558\uac8c \uaddc\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.Od,B.b7m,null)
B.J0=s([u.xp,"\ud560\uc778\uc728\xb7\ub9ac\ubca0\uc774\ud2b8\ub294 \uac00\uaca9\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ubbc0\ub85c \ub2f4\ud569 \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ud560\uc778\uc728\uc5d0 \uad00\ud55c \ud569\uc758\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub9ac\ubca0\uc774\ud2b8 \uc9c0\uae09\uc870\uac74 \ud569\uc758\ub294 \uc624\uc9c1 \uc18c\ube44\uc790 \ubcf4\ud638\uc640\ub9cc \uad00\ub828\uc774 \uc788\ub2e4","\ud560\uc778\uc728\xb7\ub9ac\ubca0\uc774\ud2b8 \ud569\uc758\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
