B.bqY=new A.a("gen_collusion_type_price_4","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uac00\uaca9\xb7\uac70\ub798\uc870\uac74 \uad00\ub828 \uc720\ud615","\ud560\uc778\uc728\uc774\ub098 \ub9ac\ubca0\uc774\ud2b8 \uc9c0\uae09\uc870\uac74\uc5d0 \uad00\ud55c \uacf5\ub3d9 \ud569\uc758\uac00 \uac00\uaca9 \ub2f4\ud569\uc73c\ub85c \ucde8\uae09\ub420 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.J0,0,"\ud560\uc778\uc728\uc774\ub098 \ub9ac\ubca0\uc774\ud2b8 \uc9c0\uae09\uc870\uac74\uc740 \uba85\ubaa9\uc0c1\uc758 \uac00\uaca9\ud45c\uc640\ub294 \ubcc4\uac1c\uc77c \uc218 \uc788\uc9c0\ub9cc, \uc2e4\uc9c8\uc801\uc73c\ub85c \ucd5c\uc885 \uc18c\ube44\uc790\uac00 \uc9c0\ubd88\ud558\ub294 \uac00\uaca9\uc774\ub098 \uc0ac\uc5c5\uc790\uc758 \uc2e4\uc9c8 \uc218\uc775\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc18c\uc774\ubbc0\ub85c, \uc774\uc5d0 \uad00\ud55c \uc0ac\uc5c5\uc790 \uac04 \uacf5\ub3d9 \ud569\uc758\ub294 \uac00\uaca9 \ub2f4\ud569\uacfc \ub3d9\uc77c\ud558\uac70\ub098 \uc720\uc0ac\ud558\uac8c \ucde8\uae09\ub418\uc5b4 \uaddc\uc81c\ub420 \uc218 \uc788\ub2e4.",B.aa3,B.a8s,null)
B.b3H=s([u.uJ,"\uac00\uaca9\uc744 \uc720\uc9c0\ud558\ub294 \ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uac00 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9\uc758 \uc720\uc9c0\ub294 \uac00\uaca9 \uc778\uc0c1\uacfc \uc804\ud600 \ub2e4\ub978 \ubcc4\uac1c\uc758 \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9\uc744 \uc720\uc9c0\ud558\uae30\ub85c \ud569\uc758\ud558\uba74 \uc624\ud788\ub824 \uc18c\ube44\uc790\uc5d0\uac8c \ud56d\uc0c1 \uc720\ub9ac\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uac00\uaca9\uc758 \uc720\uc9c0\ub294 \ub2f4\ud569\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \uc808\ub300\uc801 \uc6d0\uce59\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
