B.bgg=new A.a("gen_collusion_type_price_6","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uac00\uaca9\xb7\uac70\ub798\uc870\uac74 \uad00\ub828 \uc720\ud615","\ud504\ub79c\ucc28\uc774\uc988 \ud611\uc758\uccb4 \uc18c\uc18d \uac00\ub9f9\ubcf8\ubd80\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud68c\uc6d0\uc0ac \ud45c\uc900 \ub85c\uc5f4\ud2f0\uc728\uc744 \ud569\uc758\ud558\uc5ec \uc815\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ay9,0,"\ud504\ub79c\ucc28\uc774\uc988 \ud611\uc758\uccb4 \uc18c\uc18d \uac00\ub9f9\ubcf8\ubd80\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud45c\uc900 \ub85c\uc5f4\ud2f0\uc728(\uac00\ub9f9\uc810\uc73c\ub85c\ubd80\ud130 \ubc1b\ub294 \ub300\uac00)\uc744 \ud569\uc758\ud558\uc5ec \uc815\ud558\ub294 \ud589\uc704\ub294, \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9\xb7\uac70\ub798\uc870\uac74\uc5d0 \uad00\ud55c \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc18c\uc9c0\uac00 \uc788\uc5b4 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\uc73c\uba70, \uc774\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub97c \ud1b5\ud55c \ub2f4\ud569\uc73c\ub85c\uc11c \ubcc4\ub3c4\ub85c \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc640\ub3c4 \uacbd\ud569\uc801\uc73c\ub85c \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.avt,B.a4g,null)
B.a6q=s([u.wy,"\uc0ac\uc5c5\uc790\uac00 \uc790\uccb4\uc801\uc778 \uacbd\uc601\ud310\ub2e8\uc5d0 \ub530\ub77c \uc0dd\uc0b0\uc124\ube44\ub97c \uc99d\uc124\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc218\uc694 \uac10\uc18c\uc5d0 \ub530\ub77c \ub3c5\uc790\uc801\uc73c\ub85c \uc0dd\uc0b0\ub7c9\uc744 \uc904\uc774\ub294 \ud589\uc704","\uc815\ubd80\uac00 \ud2b9\uc815 \uc0b0\uc5c5\uc758 \uc0dd\uc0b0\ub7c9\uc744 \uaddc\uc81c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \ud488\uc9c8 \ud5a5\uc0c1\uc744 \uc704\ud574 \uc0dd\uc0b0\uacf5\uc815\uc744 \uac1c\uc120\ud558\ub294 \ud589\uc704"],t.s)
