B.bdn=new A.a("gen_gn_def_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc0ac\uc5c5\uc790\ub2e8\uccb4"\uc758 \uc815\uc758\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aQp,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc870\ud569\xb7\ud611\ud68c \ub4f1 \uba85\uce6d\uc774\ub098 \ubc95\uc801 \ud615\ud0dc\uc640 \uad00\uacc4\uc5c6\uc774, 2 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc758 \uc774\uc775\uc744 \uc99d\uc9c4\ud560 \ubaa9\uc801\uc73c\ub85c \uc870\uc9c1\ud55c \uacb0\ud569\uccb4 \ub610\ub294 \uc5f0\ud569\uccb4\ub97c \uc758\ubbf8\ud55c\ub2e4. \ub2e8\uc21c \uce5c\ubaa9 \ubaa8\uc784\uc774\ub77c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc0ac\uc5c5\uc790 \uacf5\ub3d9\uc758 \uc774\uc775 \uc99d\uc9c4\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub85c \uc778\uc815\ub420 \uc218 \uc788\uc73c\uba70, \ubc18\ub4dc\uc2dc \ubc95\uc815\ub2e8\uccb4\uc774\uac70\ub098 \uc815\ubd80\uac00 \uc124\ub9bd\uc744 \uac15\uc81c\ud55c \ub2e8\uccb4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4.",B.ard,B.aWS,null)
B.a8T=s(["2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uc11c\ub85c\ub97c \uacc4\uc5f4\ud68c\uc0ac\ub77c \ud55c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \ubc18\ub4dc\uc2dc \ub3d9\uc77c \uc5c5\uc885\uc744 \uc601\uc704\ud558\ub294 \ud68c\uc0ac\ub9cc\uc744 \uac00\ub9ac\ud0a8\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \uc678\uad6d\uc5d0 \ubcf8\uc0ac\ub97c \ub454 \ud68c\uc0ac\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc774\ub2e4","\uacc4\uc5f4\ud68c\uc0ac \uc5ec\ubd80\ub294 \ub9e4\ucd9c\uc561 \uaddc\ubaa8\ub85c\ub9cc \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc5f4\ud68c\uc0ac\ub294 \uc0c1\uc7a5 \uc5ec\ubd80\uc5d0 \ub530\ub77c \uacb0\uc815\ub41c\ub2e4"],t.s)
B.avA=s(["2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uc11c\ub85c\ub97c \uacc4\uc5f4\ud68c\uc0ac\ub77c \ud55c\ub2e4"],t.s)
B.aYB=s(["\uacc4\uc5f4\ud68c\uc0ac\uc758 \uc815\uc758"],t.s)
B.bfL=new A.a("gen_gn_def_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uacc4\uc5f4\ud68c\uc0ac"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a8T,0,"\uacc4\uc5f4\ud68c\uc0ac\ub294 2 \uc774\uc0c1\uc758 \ud68c\uc0ac\uac00 \ub3d9\uc77c\ud55c \uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacbd\uc6b0 \uadf8 \uc0c1\ud638\uac04\uc758 \uad00\uacc4\ub97c \uac00\ub9ac\ud0a4\ub294 \uac1c\ub150\uc774\ub2e4. \ub3d9\uc77c \uc5c5\uc885 \uc5ec\ubd80, \uc0c1\uc7a5 \uc5ec\ubd80, \ub9e4\ucd9c\uc561 \uaddc\ubaa8\uc640\ub294 \ubb34\uad00\ud558\uba70, \ub3d9\uc77c\ud55c \uc9c0\ubc30\ub825 \uc544\ub798 \uc788\ub294 \uae30\uc5c5\uc9d1\ub2e8 \uc18c\uc18d \uc5ec\ubd80\uac00 \ud575\uc2ec \ud310\ub2e8\uae30\uc900\uc774\ub2e4. \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 \ud310\ub2e8\uc774\ub098 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \ub4f1 \uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacc4\uc5f4\ud68c\uc0ac \uad00\uacc4\uac00 \uc911\uc694\ud55c \uace0\ub824\uc694\uc18c\ub85c \uc791\uc6a9\ud55c\ub2e4.",B.avA,B.aYB,null)
B.acz=s(["\uc8fc\uc2dd(\uc9c0\ubd84)\uc758 \uc18c\uc720\ub97c \ud1b5\ud558\uc5ec \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac\ub97c \ub9d0\ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \ubc18\ub4dc\uc2dc \uc81c\uc870\uc5c5\uc744 \uc9c1\uc811 \uc601\uc704\ud574\uc57c \ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \uc804\ud600 \ubcf4\uc720\ud558\uc9c0 \uc54a\ub294 \ud68c\uc0ac\ub97c \uc758\ubbf8\ud55c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac \uc81c\ub3c4\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc804\uba74\uc801\uc73c\ub85c \uae08\uc9c0\ub41c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ud55c \uc720\ud615\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4"],t.s)
B.aG3=s(["\uc8fc\uc2dd(\uc9c0\ubd84)\uc758 \uc18c\uc720\ub97c \ud1b5\ud558\uc5ec \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac"],t.s)
B.Kk=s(["\uc9c0\uc8fc\ud68c\uc0ac\uc758 \uc815\uc758"],t.s)
B.bi2=new A.a("gen_gn_def_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 "\uc9c0\uc8fc\ud68c\uc0ac"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.acz,0,"\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc8fc\uc2dd(\uc9c0\ubd84) \uc18c\uc720\ub97c \ud1b5\ud574 \ub2e4\ub978 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc9c0\ubc30\ud558\ub294 \uac83\uc744 \uc8fc\ub41c \uc0ac\uc5c5\uc73c\ub85c \ud558\ub294 \ud68c\uc0ac\ub97c \ub9d0\ud55c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uc740 \uc9c0\uc8fc\ud68c\uc0ac \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\uc9c0 \uc54a\uace0, \ubd80\ucc44\ube44\uc728 \uc81c\ud55c\uc774\ub098 \uc790\ud68c\uc0ac \uc9c0\ubd84\uc728 \uc694\uac74 \ub4f1 \uc77c\uc815\ud55c \ud589\uc704\uaddc\uc81c\ub97c \ud1b5\ud574 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \ucde8\ud55c\ub2e4. \uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc544\ub2c8\ub77c \ud68c\uc0ac(\uc0ac\uc5c5\uc790)\uc758 \ud55c \ud615\ud0dc\uc774\ub2e4.",B.aG3,B.Kk,null)
B.aY9=s(['\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uacbd\uc7c1\uc81c\ud55c\uc801 \ud589\uc704\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uc640 \ubcc4\ub3c4\ub85c "\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc815\uc73c\ub85c \uaddc\uc728\ub41c\ub2e4',"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub294 \ubc95\ub960\uc0c1 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub418\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub294 \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08\uc774 \ubd80\uacfc\ub420 \uc218 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc \ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.aRV=s(['\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc815\uc73c\ub85c \uaddc\uc728\ub41c\ub2e4'],t.s)
B.b0T=s(["\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uaddc\uc728\uc758 \ub3c5\uc790\uc131"],t.s)
B.bib=new A.a("gen_gn_def_5","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub97c \uad6c\ubcc4\ud558\ub294 \uc2e4\uc775\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aY9,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc81c\ud55c\ud558\uac70\ub098 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704 \ub4f1\uc744 "\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704"\ub77c\ub294 \ubcc4\ub3c4\uc758 \uc7a5(\u7ae0)\uc5d0\uc11c \uaddc\uc728\ud558\uace0 \uc788\uc5b4, \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\xb7\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub4f1\uacfc\ub294 \uad6c\ubd84\ub418\ub294 \ub3c5\uc790\uc801\uc778 \uaddc\uc81c \uccb4\uacc4\ub97c \uac16\ub294\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub3c4 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \uc81c\uc7ac\uac00 \ubd80\uacfc\ub420 \uc218 \uc788\ub2e4.',B.aRV,B.b0T,null)
B.a1R=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9, \uae30\uc5c5\uacb0\ud569, \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \ub4f1 \uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \ud615\uc0ac\ucc98\ubc8c \uaddc\uc815\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \ubc95 \uc2dc\ud589 \uc774\ud6c4 \uc0ad\uc81c\ub420 \uc608\uc815\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ud574\ub2f9 \uc815\uc758\ub294 \uc678\uad6d\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aHp=s(["\uc5ec\ub7ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.Zl=s(["\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c \uc815\uc758\uc758 \uc704\uce58"],t.s)
B.bBQ=new A.a("gen_gn_def_6","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc8fc\uc694 \uc6a9\uc5b4\uc758 \uc815\uc758",'"\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c"(\uad00\ub828\uc2dc\uc7a5) \uc815\uc758\uaddc\uc815\uc774 \ubc95\ub960 \ucd1d\uce59\uc5d0 \uc704\uce58\ud558\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a1R,0,'"\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c"(\uad00\ub828\uc2dc\uc7a5)\ub294 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9 \uc5ec\ubd80, \uae30\uc5c5\uacb0\ud569\uc758 \uacbd\uc7c1\uc81c\ud55c\uc131, \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd \ub4f1 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uc5ec\ub7ec \ud575\uc2ec \uaddc\uc815\uc5d0\uc11c \uacf5\ud1b5\uc801\uc73c\ub85c \uc804\uc81c\ub418\ub294 \uae30\ucd08 \uac1c\ub150\uc774\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uac1c\ubcc4 \uc7a5(\u7ae0)\uc774 \uc544\ub2c8\ub77c \ubc95\ub960 \ucd1d\uce59(\uc815\uc758\uaddc\uc815)\uc5d0\uc11c \ud1b5\uc77c\uc801\uc73c\ub85c \uaddc\uc815\ud558\uc5ec \uc5ec\ub7ec \uaddc\uc815\uc5d0 \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub420 \uc218 \uc788\ub3c4\ub85d \ud558\uace0 \uc788\ub2e4.',B.aHp,B.Zl,null)
B.aaQ=s(["\ud2b9\ud5c8\uad8c\xb7\uc2e4\uc6a9\uc2e0\uc548\uad8c\xb7\ub514\uc790\uc778\uad8c\xb7\uc0c1\ud45c\uad8c\xb7\uc800\uc791\uad8c\uc758 \uc815\ub2f9\ud55c \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c\uc740 \uc774 \ubc95\uc758 \uc801\uc6a9\ub300\uc0c1\uc5d0\uc11c \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc644\uc804\ud788 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \ud589\uc0ac\ub294 \uadf8 \ubaa9\uc801\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc801\uc6a9\uc81c\uc678\ub41c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\ub294 \uc0c1\ud45c\uad8c\uc5d0\ub9cc \ud55c\uc815\ub41c\ub2e4","\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678\ub294 \uc678\uad6d\uc5d0 \ub4f1\ub85d\ub41c \uad8c\ub9ac\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.akG=s(["\uc815\ub2f9\ud55c \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.aOt=s(["\ubb34\uccb4\uc7ac\uc0b0\uad8c \uc801\uc6a9\uc81c\uc678"],t.s)
B.bmV=new A.a("gen_gn_scope_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ubb34\uccb4\uc7ac\uc0b0\uad8c\uc758 \ud589\uc0ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aaQ,0,'\uacf5\uc815\uac70\ub798\ubc95\uc740 \ud2b9\ud5c8\uad8c\xb7\uc2e4\uc6a9\uc2e0\uc548\uad8c\xb7\ub514\uc790\uc778\uad8c\xb7\uc0c1\ud45c\uad8c\xb7\uc800\uc791\uad8c \ub4f1 \ubb34\uccb4\uc7ac\uc0b0\uad8c\uc758 "\uc815\ub2f9\ud55c" \ud589\uc0ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \ud589\uc704\uc5d0\ub294 \uc774 \ubc95\uc744 \uc801\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc774\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\ud589\uc0ac\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub294 \uc81c\ud55c\uc801 \uc801\uc6a9\uc81c\uc678\uc774\uba70, \uad8c\ub9ac\ub97c \ube59\uc790\ud558\uc5ec \ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704\uae4c\uc9c0 \ubcf4\ud638\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.',B.akG,B.aOt,null)
B.am5=s([u.E7,"\ud2b9\ud5c8\uad8c \ud589\uc0ac\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc801\uc6a9\uc81c\uc678\uac00 \uc778\uc815\ub41c\ub2e4","\uc774 \uacbd\uc6b0\ub294 \ubc18\ub4dc\uc2dc \ud615\uc0ac\ucc98\ubc8c\ub9cc \uac00\ub2a5\ud558\uace0 \ud589\uc815\uc81c\uc7ac\ub294 \ubd88\uac00\ub2a5\ud558\ub2e4","\ud2b9\ud5c8\uad8c\uc744 \uc774\uc720\ub85c \ud55c \ud589\uc704\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uc2ec\uc0ac \ub300\uc0c1 \uc790\uccb4\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c\ub9cc \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
