B.bn5=new A.a("gen_gn_extra_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uc5ed\uc678\uc801\uc6a9 \ubc95\ub9ac\uac00 \ubb38\uc81c\ub418\ub294 \ub300\ud45c\uc801\uc778 \uc0c1\ud669\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.arV,0,"\uc5ed\uc678\uc801\uc6a9 \ubc95\ub9ac\ub294 \ub300\ud45c\uc801\uc73c\ub85c \uc5ec\ub7ec \uad6d\uac00\uc758 \uc0ac\uc5c5\uc790\ub4e4\uc774 \ud574\uc678\uc5d0\uc11c \uac00\uaca9\uc774\ub098 \ubb3c\ub7c9 \ub4f1\uc5d0 \uad00\ud574 \uad6d\uc81c\uce74\ub974\ud154\uc744 \ud615\uc131\ud558\uace0, \uadf8 \ud6a8\uacfc\uac00 \uad6d\ub0b4\ub85c \uc218\uc785\ub418\ub294 \uc0c1\ud488\uc758 \uac00\uaca9\uc774\ub098 \uad6d\ub0b4\uc2dc\uc7a5\uc758 \uacbd\uc7c1\uc0c1\ud669\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uacbd\uc6b0\uc5d0 \ubb38\uc81c\ub41c\ub2e4. \uc21c\uc218\ud55c \uad6d\ub0b4 \uac70\ub798\ub098 \uacf5\uc815\uac70\ub798\ubc95\uacfc \ubb34\uad00\ud55c \uc0ac\uc548\uc5d0\ub294 \uc5ed\uc678\uc801\uc6a9 \ubc95\ub9ac\uac00 \uc801\uc6a9\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4.",B.aDS,B.b09,null)
B.b4V=s([u.mx,"\uc5ed\uc678\uc801\uc6a9\uc740 \uc5b4\ub5a0\ud55c \uad6d\uc81c\ubc95\uc801 \uace0\ub824\ub3c4 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4","\uc5ed\uc678\uc801\uc6a9\uc740 \uc624\uc9c1 \uad6d\ub0b4 \uc0ac\uc5c5\uc790\uc758 \uc774\uc775\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc5ed\uc678\uc801\uc6a9 \uc778\uc815 \uc5ec\ubd80\ub294 \uc678\uad6d\uc0ac\uc5c5\uc790\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc5ed\uc678\uc801\uc6a9\uc740 \uad6d\uc81c\ud611\uc57d\uacfc \ubb34\uad00\ud558\uac8c \uc77c\ubc29\uc801\uc73c\ub85c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
