B.bji=new A.a("gen_ca_3","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74",null,"\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ahy,3,'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub294 \uc0ac\uc5c5\uc790 \uac04 "\ud569\uc758" \uc790\uccb4\ub85c \uc131\ub9bd\ud558\uba70, \uadf8 \ud569\uc758\ub97c \uc2e4\uc81c\ub85c \uc2e4\ud589\uc5d0 \uc62e\uacbc\ub294\uc9c0 \uc5ec\ubd80\ub294 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc77c\uad00\ub41c \uc785\uc7a5\uc774\ub2e4. \uc989 \ud569\uc758\ub9cc \uc788\uc73c\uba74 \uc2e4\ud589\ud589\uc704\uac00 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \uc774\ubbf8 \uacbd\uc7c1\uc81c\ud55c\uc758 \uc704\ud5d8\uc774 \ubc1c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf4\uc544 \uacf5\ub3d9\ud589\uc704\uac00 \uc131\ub9bd\ud558\uace0, \uc2e4\ud589 \uc5ec\ubd80\ub294 \uacfc\uc9d5\uae08 \uc0b0\uc815 \ub4f1 \uc81c\uc7ac \uc218\uc704\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \ubfd0\uc774\ub2e4. \ub530\ub77c\uc11c "\uc2e4\ud589\ud589\uc704\ub85c \ub098\uc544\uac00\uc9c0 \uc54a\uc558\ub2e4\uba74 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ud569\uc758\uc5d0\ub294 \ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\ub3c4 \ud3ec\ud568\ub418\uace0, \uadf8 \uc99d\uba85\ucc45\uc784\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc788\uc73c\uba70, \uacbd\uc7c1\uc81c\ud55c\uc131 \uc694\uac74\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub098\uba38\uc9c0 \uc120\ud0dd\uc9c0\ub294 \ubaa8\ub450 \uc633\uc740 \uc124\uba85\uc774\ub2e4.',B.b3P,B.aKD,null)
B.b8F=s([u.Fa,"\uc624\uc9c1 \uc11c\uba74 \uacc4\uc57d\uc11c\uac00 \uc791\uc131\ub41c \uacbd\uc6b0\ub9cc \ud569\uc758\ub85c \uc778\uc815\ub41c\ub2e4","\ud569\uc758\ub294 \ubc18\ub4dc\uc2dc \uacf5\uc99d\uc744 \ubc1b\uc544\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ud569\uc758\ub294 \uc0ac\uc5c5\uc790 1\uc778\uc758 \ub2e8\ub3c5 \uc758\uc0ac\uacb0\uc815\ub9cc\uc73c\ub85c \uc131\ub9bd\ud55c\ub2e4","\ud569\uc758\ub294 \ubc95\uc6d0\uc758 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.a2I=s([u.Fa],t.s)
B.axu=s(["\ud569\uc758\uc758 \uac1c\ub150"],t.s)
B.blj=new A.a("gen_collusion_agree_1","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758\uc758 \uac1c\ub150\xb7\uc778\uc815\ubc29\ubc95",'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc778 "\ud569\uc758"\uc758 \uac1c\ub150\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.b8F,0,'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc778 "\ud569\uc758"\ub294 \ub458 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uc758\uc0ac\uc5f0\ub77d\uc744 \ud1b5\ud574 \uacf5\ub3d9\uc73c\ub85c \ud2b9\uc815 \ud589\uc704\ub97c \ud558\uae30\ub85c \ud558\ub294 \ub0b4\uc6a9\uc758 \uc0c1\ud638 \uc758\uc0ac\uc758 \ud569\uce58\ub97c \uc758\ubbf8\ud55c\ub2e4. \ubc18\ub4dc\uc2dc \uc11c\uba74 \uacc4\uc57d\uc11c\ub098 \uacf5\uc99d\uc774 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\uba70, \uc0ac\uc5c5\uc790 1\uc778\uc758 \ub2e8\ub3c5 \uc758\uc0ac\uacb0\uc815\ub9cc\uc73c\ub85c\ub294 \ud569\uc758\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.',B.a2I,B.axu,null)
B.aLw=s([u.xP,"\uc624\uc9c1 \uba85\uc2dc\uc801 \ud569\uc758\ub9cc \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\ub85c \uc778\uc815\ub41c\ub2e4","\ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud569\uc758\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uba85\uc2dc\uc801 \ud569\uc758\uc640 \ubb35\uc2dc\uc801 \ud569\uc758\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub2e4\ub974\ub2e4","\ubb35\uc2dc\uc801 \ud569\uc758\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.aCR=s([u.xP],t.s)
B.aFF=s(["\uba85\uc2dc\uc801\xb7\ubb35\uc2dc\uc801 \ud569\uc758"],t.s)
B.bpA=new A.a("gen_collusion_agree_2","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758\uc758 \uac1c\ub150\xb7\uc778\uc815\ubc29\ubc95","\uba85\uc2dc\uc801 \ud569\uc758\uc640 \ubb35\uc2dc\uc801 \ud569\uc758(\uc758\uc0ac\uc5f0\ub77d)\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aLw,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\ub294 \uba85\uc2dc\uc801\uc778 \ud569\uc758\ubfd0\ub9cc \uc544\ub2c8\ub77c, \uc0ac\uc5c5\uc790\ub4e4 \uc0ac\uc774\uc758 \uc815\ud669\uc99d\uac70(\uac00\uaca9 \uc778\uc0c1 \uc2dc\uc810\uc758 \uc77c\uce58, \ud68c\ud569 \uc815\ud669 \ub4f1)\ub97c \ud1b5\ud574 \uc778\uc815\ub418\ub294 \ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\uc73c\ub85c\ub3c4 \uc778\uc815\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud655\ub9bd\ub41c \ubc95\ub9ac\uc774\ub2e4.",B.aCR,B.aFF,null)
B.aV6=s([u.sV,"\ubcd1\ud589\ud589\uc704\uac00 \uc788\uc73c\uba74 \uadf8 \uc790\uccb4\ub85c \ud56d\uc0c1 \ud569\uc758\uac00 \uc778\uc815\ub41c\ub2e4","\ubcd1\ud589\ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud569\uc758\uc758 \uadfc\uac70 \uc790\ub8cc\ub85c \uc4f0\uc77c \uc218 \uc5c6\ub2e4","\ubcd1\ud589\ud589\uc704\ub294 \uc624\uc9c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ubcd1\ud589\ud589\uc704\uc640 \ud569\uc758\ub294 \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.aGH=s([u.sV],t.s)
B.aZR=s(["\ubcd1\ud589\ud589\uc704\uc640 \ud569\uc758\uc758 \uad6c\ubcc4"],t.s)
B.bz1=new A.a("gen_collusion_agree_3","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758\uc758 \uac1c\ub150\xb7\uc778\uc815\ubc29\ubc95","\ubcd1\ud589\ud589\uc704(\ub3d9\uc870\uc801 \ud589\uc704, parallel conduct)\ub9cc\uc73c\ub85c \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\uac00 \uc778\uc815\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aV6,0,"\uacbd\uc7c1\uc0ac\uc5c5\uc790\ub4e4\uc774 \uc720\uc0ac\ud55c \uc2dc\uae30\uc5d0 \uc720\uc0ac\ud55c \uac00\uaca9 \ubcc0\ub3d9 \ub4f1\uc744 \ubcf4\uc774\ub294 \ubcd1\ud589\ud589\uc704 \uc790\uccb4\ub9cc\uc73c\ub85c\ub294 \ud569\uc758\uac00 \uace7\ubc14\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\uc73c\uba70, \uc774\ub97c \ub4b7\ubc1b\uce68\ud558\ub294 \uc758\uc0ac\uc5f0\ub77d \ub4f1 \ucd94\uac00\uc801\uc778 \uc0ac\uc815\uc774 \uc788\uc5b4\uc57c \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \ubc95\ub9ac\uc774\ub2e4.",B.aGH,B.aZR,null)
B.afN=s([u.yn,"\ubc18\ub4dc\uc2dc \uc14b \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \ucc38\uc5ec\ud574\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\uc624\uc9c1 \ub3d9\uc77c \uc5c5\uc885\uc758 \uc0ac\uc5c5\uc790 \uc0ac\uc774\uc5d0\uc11c\ub9cc \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\uc0ac\uc5c5\uc790\uc640 \uc18c\ube44\uc790 \uc0ac\uc774\uc758 \ud569\uc758\ub85c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uad6d\uac00\uae30\uad00 \uc0ac\uc774\uc758 \ud569\uc758\ub85c\ub9cc \uc131\ub9bd\ud55c\ub2e4"],t.s)
