B.akw=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub97c \uc8fc\uc7a5\ud558\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc99d\uba85\ucc45\uc784\uc744 \ubd80\ub2f4\ud55c\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc18c\ube44\uc790\ub2e8\uccb4\uc5d0\uac8c \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec \ubd80\ub2f4\ud55c\ub2e4","\uc99d\uba85\ucc45\uc784 \uac1c\ub150\uc740 \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
