B.bte=new A.a("gen_collusion_presume_2","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758 \ucd94\uc815\xb7\uc99d\uba85\ucc45\uc784","\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758 \ucd94\uc815 \uaddc\uc815\uc774 \uac16\ub294 \uae30\ub2a5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Ob,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub294 \uc740\ubc00\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544 \uc9c1\uc811 \uc99d\uac70\uc758 \ud655\ubcf4\uac00 \uc5b4\ub824\uc6b4 \ud2b9\uc131\uc774 \uc788\uc73c\ubbc0\ub85c, \uc77c\uc815\ud55c \uc815\ud669(\uac00\uaca9 \ub4f1 \uc77c\uce58, \uc815\ubcf4\uad50\ud658 \ub4f1)\uc774 \uc778\uc815\ub418\uba74 \ud569\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ucd94\uc815\ud558\ub294 \uaddc\uc815\uc744 \ub450\uc5b4 \ub2f4\ud569 \uc785\uc99d\uc758 \uc5b4\ub824\uc6c0\uc744 \uc644\ud654\ud558\ub294 \uae30\ub2a5\uc744 \ud55c\ub2e4.",B.aFx,B.b7_,null)
B.PF=s([u.nM,"\ucd94\uc815\uc774 \ub418\uba74 \uc0ac\uc5c5\uc790\ub294 \uc5b4\ub5a0\ud55c \ubc18\ubc15\ub3c4 \ud560 \uc218 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790\ub294 \uc624\uc9c1 \uce68\ubb35\uc73c\ub85c\ub9cc \ub300\uc751\ud560 \uc218 \uc788\ub2e4","\ucd94\uc815\uc744 \ub2e4\ud22c\ub824\uba74 \ubc18\ub4dc\uc2dc \ud615\uc0ac\uc18c\uc1a1\uc744 \ubcc4\ub3c4\ub85c \uc81c\uae30\ud574\uc57c \ud55c\ub2e4","\ucd94\uc815\uc744 \ub2e4\ud22c\ub294 \uac83\uc740 \ubc95\ub960\uc0c1 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
