B.bFJ=new A.a("gen_collusion_presume_6","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758 \ucd94\uc815\xb7\uc99d\uba85\ucc45\uc784","\ud569\uc758\uc758 \uc99d\uba85\uacfc \uad00\ub828\ud558\uc5ec \uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uc774 \uac16\ub294 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ZQ,0,"\uc0ac\uc5c5\uc790\ub4e4\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9 \uc591\uc0c1\uc740 \uadf8 \uc790\uccb4\ub85c \ud569\uc758\ub97c \ud655\uc815\ud558\ub294 \uc808\ub300\uc801 \uc99d\uac70\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ub2e4\ub978 \uc815\ud669\uc99d\uac70\ub4e4\uacfc \ud568\uaed8 \ud569\uc758 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \ub370 \ucc38\uace0\ud560 \uc218 \uc788\ub294 \uc5ec\ub7ec \uc694\uc18c \uc911 \ud558\ub098\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4.",B.arn,B.aGK,null)
B.Kb=s([u.a7,"\ud569\uc758\uac00 \uc788\uc5c8\ub358 \ucd5c\ucd08 \uc2dc\uc810\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud558\uace0 \uc774\ud6c4 \uc0ac\uc815\uc740 \uc804\ud600 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \ud56d\uc0c1 \uc815\ubd80\uc758 \uc870\uc0ac \uac1c\uc2dc\uc77c\ub85c \uace0\uc815\ub41c\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \ud310\ub2e8\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uac1c\ub150\uc774\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \uc5b8\ub860\ubcf4\ub3c4\uc77c\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4"],t.s)
