B.buV=new A.a("gen_sup_remedy_3","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc5d0 \ub300\ud574 \uc9c0\uc6d0\uac1d\uccb4(\uc218\ud61c\uc790)\ub3c4 \ud568\uaed8 \uc81c\uc7ac\ub420 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHu,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uc81c\uacf5\ud55c \uc9c0\uc6d0\uc8fc\uccb4\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uc774\uc775\uc744 \uc81c\uacf5\ubc1b\uc740 \ud2b9\uc218\uad00\uacc4\uc778\xb7\ud68c\uc0ac(\uc9c0\uc6d0\uac1d\uccb4)\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc77c\uc815\ud55c \uc694\uac74 \ud558\uc5d0 \ud568\uaed8 \uc81c\uc7ac\ud560 \uc218 \uc788\ub294 \uadfc\uac70\ub97c \ub450\uc5b4, \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uadfc\uc808\uc758 \uc2e4\ud6a8\uc131\uc744 \ub192\uc774\uace0 \uc788\ub2e4.",B.V9,B.abo,null)
B.aOG=s(["\uc77c\uc815\ud55c \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \uace0\ubc1c\uc744 \ud1b5\ud55c \ud615\uc0ac\ucc98\ubc8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc624\uc9c1 \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \ud589\uc815\uc9c8\uc11c\ubc8c\uc778 \uacfc\ud0dc\ub8cc\ub9cc \ubd80\uacfc\ub420 \uc218 \uc788\ub2e4","\ud615\uc0ac\ucc98\ubc8c \uc5ec\ubd80\ub294 \uc9c0\uc6d0\uac1d\uccb4\uac00 \uc784\uc758\ub85c \uacb0\uc815\ud55c\ub2e4"],t.s)
B.a1I=s(["\uc77c\uc815\ud55c \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \uace0\ubc1c\uc744 \ud1b5\ud55c \ud615\uc0ac\ucc98\ubc8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
