B.bi1=new A.a("gen_sup_remedy_4","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc5d0 \ub300\ud55c \ud615\uc0ac\ucc98\ubc8c \uac00\ub2a5\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aOG,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub3c4 \uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\ud589\uc704\uc758 \ud558\ub098\ub85c\uc11c, \uadf8 \uc704\ubc95\uc131\uc758 \uc815\ub3c4\uac00 \uc911\ub300\ud55c \uacbd\uc6b0\uc5d0\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uace0\ubc1c \ub4f1\uc744 \ud1b5\ud574 \ud615\uc0ac\ucc98\ubc8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \ud615\uc0ac\ucc98\ubc8c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc0ac\ub840\ub294 \uc0ac\uc548\uc758 \uc911\ub300\uc131\uc5d0 \ub530\ub77c \uc81c\ud55c\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4.",B.a1I,B.aaG,null)
B.aph=s([u.iR,"\uc704\ubc18\uc0ac\uc2e4 \uacf5\ud45c\ub294 \uc808\ub300\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacf5\ud45c\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \uc790\ubc1c\uc801 \uc2e0\uccad\uc774 \uc788\uc744 \ub54c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uacf5\ud45c \uba85\ub839\uc740 \ud615\uc0ac\ucc98\ubc8c\uacfc \ub3d9\uc77c\ud55c \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4","\uacf5\ud45c \uba85\ub839\uc740 \uc9c0\uc6d0\uac1d\uccb4\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4"],t.s)
B.azW=s([u.iR],t.s)
