B.bo3=new A.a("gen_sup_remedy_5","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub85c \uc778\ud55c \uc704\ubc18\uc0ac\uc2e4\uc758 \uacf5\ud45c \uc81c\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aph,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \ub4f1 \ubc95 \uc704\ubc18\uc774 \uc778\uc815\ub418\ub294 \uacbd\uc6b0 \uc704\ubc18\uc0ac\uc2e4\uc758 \uacf5\ud45c\ub97c \uba85\ud560 \uc218 \uc788\uc73c\uba70, \uc774\ub97c \ud1b5\ud574 \uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc5d0\uac8c \uad00\ub828 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uace0 \uc720\uc0ac\ud55c \uc704\ubc18\ud589\uc704\uc758 \uc7ac\ubc1c\uc744 \uc5b5\uc9c0\ud558\ub294 \ud6a8\uacfc\ub97c \uae30\ub300\ud560 \uc218 \uc788\ub2e4.",B.azW,B.agC,null)
B.arm=s([u.r1,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc0ac\uc775\ud3b8\ucde8 \uaddc\uc81c\uac00 \ub3c4\uc785\ub418\uba74\uc11c \uc644\uc804\ud788 \ubb34\uc758\ubbf8\ud574\uc84c\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uc81c\ub3c4\ub294 \uc2e4\ubb34\uc0c1 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294 \uc0ac\ubb38\ud654\ub41c \uaddc\uc815\uc774\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc9c0\uc6d0\uac1d\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uace0 \uc9c0\uc6d0\uc8fc\uccb4\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
