B.bpC=new A.a("gen_conc_5","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,"\uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c\uac00 \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc5d0\uc11c \uac16\ub294 \uc704\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aHl,0,"\uc9c0\uc8fc\ud68c\uc0ac \uc81c\ub3c4\ub294 \uadf8 \uc790\uccb4\ub97c \uae08\uc9c0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc124\ub9bd\xb7\uc804\ud658\uc744 \ud5c8\uc6a9\ud558\ub418, \ubd80\ucc44\ube44\uc728 \uc81c\ud55c, \uc790\ud68c\uc0ac \uc9c0\ubd84\uc728 \uc694\uac74 \ub4f1 \uc77c\uc815\ud55c \ud589\uc704 \uaddc\uc81c\ub97c \ubd80\uacfc\ud568\uc73c\ub85c\uc368 \uc9c0\uc8fc\ud68c\uc0ac \uad6c\uc870\ub97c \uc774\uc6a9\ud55c \uacfc\ub3c4\ud55c \uc9c0\ubc30\ub825 \ud655\uc7a5\uacfc \uacbd\uc81c\ub825\uc9d1\uc911\uc744 \ubc29\uc9c0\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc6b4\uc601\ub418\uba70, \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc758 \ud55c \ucd95\uc744 \uc774\ub8ec\ub2e4.",B.a0z,B.b8G,null)
B.a_Y=s([u.vu,"\ub450 \uc81c\ub3c4\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub8e8\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc774 \ub3c4\uc785\ub418\uba74\uc11c \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \ud3d0\uc9c0\ub418\uc5c8\ub2e4","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\ub450 \uc81c\ub3c4\ub294 \uc11c\ub85c \ubaa8\uc21c\ub418\uc5b4 \ub3d9\uc2dc\uc5d0 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
