B.UW=s(["\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c\uc640 \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \uad00\uacc4"],t.s)
B.bw1=new A.a("gen_conc_6","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uacfc \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a_Y,0,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc774 \uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0, \uc21c\ud658\ucd9c\uc790 \uc81c\ud55c, \ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c, \uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c \ub4f1\uc744 \ud1b5\ud574 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uc9c0\ubc30\uad6c\uc870 \uc790\uccb4\ub97c \uad6c\uc870\uc801\uc73c\ub85c \uaddc\uc81c\ud558\ub294 \uac83\uc774\ub77c\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \uadf8\ub7ec\ud55c \uad6c\uc870 \ud558\uc5d0\uc11c \ucd1d\uc218 \uc77c\uac00 \ub4f1 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc774 \uac1c\ubcc4\uc801\uc73c\ub85c \uadc0\uc18d\ub418\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c, \ub450 \uc81c\ub3c4\ub294 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uacbd\uc81c\ub825\uc9d1\uc911\uc774\ub77c\ub294 \uacf5\ud1b5\ub41c \ubb38\uc81c\ub97c \uc11c\ub85c \ub2e4\ub978 \uce35\uc704\uc5d0\uc11c \ub2e4\ub8e8\ub294 \ubcf4\uc644\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.aDc,B.UW,null)
B.aYr=s(["\ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \ub9cc\ub4e4\uc5b4 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\uc600\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud574 \uc138\ud615 \ub3d9\uac80\uc744 \uc81c\uc791\ud558\uc600\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\ub85c \uc774\uc0ad\uc744 \uc798\ub77c \ubcbc\ub18d\uc0ac\ub97c \uc9c0\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc744 \ub9cc\ub4e4\uc5b4 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \ub098\ud0c0\ub0b4\uc5c8\ub2e4"],t.s)
B.b3v=s(["\ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4"],t.s)
B.aha=s(["\uad6c\uc11d\uae30\uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5"],t.s)
B.biy=new A.a("gen_kh_prehist_1","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc774 \uc0ac\uc6a9\ub41c \uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\uc5f0\ucc9c \uc804\uace1\ub9ac \uc720\uc801\uc5d0\uc11c\ub294 \uc544\uc290\ub9ac\uc548\ud615 \uc8fc\uba39\ub3c4\ub07c\ub97c \ube44\ub86f\ud55c \ub5c0\uc11d\uae30\uac00 \ub2e4\uc218 \ucd9c\ud1a0\ub418\uc5c8\ub2e4."',B.aYr,0,"\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\ub97c \uc0ac\uc6a9\ud55c \uc2dc\ub300\ub294 \uad6c\uc11d\uae30\uc2dc\ub300\uc774\ub2e4. \uad6c\uc11d\uae30\uc778\ub4e4\uc740 \ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \uc0ac\ub0e5\uacfc \ucc44\uc9d1\uc744 \uc704\ud574 \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4. \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\xb7\uac04\uc11d\uae30\ub294 \uc2e0\uc11d\uae30, \uac70\ud478\uc9d1\xb7\uc138\ud615\ub3d9\uac80\uc740 \ucca0\uae30, \ubc18\ub2ec\ub3cc\uce7c\xb7\uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.b3v,B.aha,null)
B.b5V=s(["\uac00\ub77d\ubc14\ud034\ub85c \uc2e4\uc744 \ubf51\uace0 \ubf08\ubc14\ub298\ub85c \uc637\uc744 \uc9c0\uc5b4 \uc785\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\ub97c \ucc98\uc74c\uc73c\ub85c \uc81c\uc791\ud558\uc600\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc0dd\uc0b0\ub825\uc744 \ud06c\uac8c \ub192\uc600\ub2e4","\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uc744 \uc758\ub840 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uad70\uc7a5\uc774 \ub4f1\uc7a5\ud558\uc5ec \uacc4\uae09 \uc0ac\ud68c\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4"],t.s)
B.abr=s(["\uac00\ub77d\ubc14\ud034\ub85c \uc2e4\uc744 \ubf51\uace0 \ubf08\ubc14\ub298\ub85c \uc637\uc744 \uc9c0\uc5b4 \uc785\uc5c8\ub2e4"],t.s)
B.YF=s(["\uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5"],t.s)
B.bFI=new A.a("gen_kh_prehist_2","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'(\uac00) \uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\uc11c\uc6b8 \uc554\uc0ac\ub3d9 \uc720\uc801\uc5d0\uc11c\ub294 (\uac00) \uc2dc\ub300\ub97c \ub300\ud45c\ud558\ub294 \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\uc640 \uac08\ub3cc\xb7\uac08\ud310\uc774 \ucd9c\ud1a0\ub418\uc5c8\ub2e4."',B.b5V,0,"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub294 \uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \ub300\ud45c \uc720\ubb3c\uc774\ub2e4. \uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uacbd\uacfc \ubaa9\ucd95\uc774 \uc2dc\uc791\ub418\uc5b4 \uc815\ucc29 \uc0dd\ud65c\uc744 \ud558\uc600\uace0, \uac00\ub77d\ubc14\ud034\uc640 \ubf08\ubc14\ub298\uc744 \uc774\uc6a9\ud574 \uc637\uc774\ub098 \uadf8\ubb3c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub5c0\uc11d\uae30 \ucd5c\ucd08 \uc81c\uc791\uc740 \uad6c\uc11d\uae30, \ucca0\uc81c \ub18d\uae30\uad6c\xb7\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\xb7\uad70\uc7a5\uc758 \ub4f1\uc7a5\uc740 \uccad\ub3d9\uae30~\ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.abr,B.YF,null)
B.ana=s(["\ub18d\uacbd\uacfc \uc815\ucc29 \uc0dd\ud65c\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc528\uc871 \uc911\uc2ec\uc758 \ud3c9\ub4f1 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4","\uccad\ub3d9\uc81c \ubb34\uae30\ub97c \ub3c5\uc810\ud55c \uad70\uc7a5\uc774 \uc8fc\ubcc0 \ubd80\uc871\uc744 \uc815\ubcf5\ud558\uc600\ub2e4","\ud55c\uc790\uc640 \uc720\ud559\uc774 \uc804\ub798\ub418\uc5b4 \uc9c0\ubc30 \uc774\ub150\uc73c\ub85c \uc790\ub9ac \uc7a1\uc558\ub2e4","\uc911\uad6d \ud654\ud3d0\uc778 \uba85\ub3c4\uc804\uc774 \ub110\ub9ac \uc720\ud1b5\ub418\uc5c8\ub2e4","\uc655\uc704\uac00 \ubd80\uc790 \uc0c1\uc18d\uc73c\ub85c \uc138\uc2b5\ub418\ub294 \uc655\uad8c \uad6d\uac00\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4"],t.s)
B.b0k=s(["\ub18d\uacbd\uacfc \uc815\ucc29 \uc0dd\ud65c\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc528\uc871 \uc911\uc2ec\uc758 \ud3c9\ub4f1 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4"],t.s)
