B.boP=new A.a("gen_kh_prehist_3","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0 \ucc98\uc74c \ub098\ud0c0\ub09c \uc0ac\ud68c \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ana,0,"\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uacbd\uacfc \ubaa9\ucd95\uc774 \uc2dc\uc791\ub418\uba74\uc11c \uc815\ucc29 \uc0dd\ud65c\uc774 \uac00\ub2a5\ud574\uc84c\uace0, \uc528\uc871\uc744 \ub2e8\uc704\ub85c \ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9\uccb4 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4. \uacc4\uae09 \ubd84\ud654\uc640 \uc815\ubcf5 \uc804\uc7c1, \uc655\uad8c \uad6d\uac00\uc758 \uc131\ub9bd\uc740 \uccad\ub3d9\uae30\uc2dc\ub300 \uc774\ud6c4\uc5d0 \ub098\ud0c0\ub09c\ub2e4.",B.b0k,B.b4C,null)
B.b1Y=s(["\uc2b4\ubca0\ucc0c\ub974\uac1c\ub294 \ucc3d\uc758 \uc790\ub8e8\uc5d0 \uaf42\uc544 \uc0ac\ub0e5 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub294 \uc0ac\ub0e5\uacfc \uc870\ub9ac \ub4f1 \uc5ec\ub7ec \uc6a9\ub3c4\ub85c \uc4f0\uc778 \ub5c0\uc11d\uae30\uc774\ub2e4","\ucc0d\uac1c\ub294 \ub3cc\uc758 \ud55c\ucabd \uba74\uc744 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30\uc774\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4","\ub5c0\uc11d\uae30\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub3c4\uad6c\uc774\ub2e4"],t.s)
B.a1h=s(["\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4"],t.s)
B.aPD=s(["\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc758 \ud2b9\uc9d5"],t.s)
B.bi9=new A.a("gen_kh_prehist_4","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b1Y,3,"\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud55c \ub3c4\uad6c \uc8fc\uc870\ub294 \uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300\uc758 \uae08\uc18d \uac00\uacf5 \ubc29\uc2dd\uc774\ub2e4. \uad6c\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30(\uc8fc\uba39\ub3c4\ub07c\xb7\ucc0d\uac1c\xb7\uc2b4\ubca0\ucc0c\ub974\uac1c \ub4f1)\ub97c \uc0ac\uc6a9\ud558\uc600\ub2e4.",B.a1h,B.aPD,null)
B.aJo=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4","\uc774\ub3d9 \uc0dd\ud65c\uc5d0 \uc720\ub9ac\ud558\ub3c4\ub85d \uac00\ubcbc\uc6b4 \ucc9c\ub9c9 \ud615\ud0dc\uc758 \uc9d1\uc744 \uc8fc\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ud06c\uac8c \ud5a5\uc0c1\ub418\uc5c8\ub2e4","\ubcbc\ub18d\uc0ac\uac00 \uc804\uad6d\uc801\uc73c\ub85c \ud655\ub300\ub418\uc5b4 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ucd95\uc801\ub418\uc5c8\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uac1c\uac04\uc774 \ud65c\ubc1c\ud574\uc838 \uacbd\uc9c0\uac00 \ud655\ub300\ub418\uc5c8\ub2e4"],t.s)
B.a1z=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4"],t.s)
