B.bvF=new A.a("gen_kh_prehist_11","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\uc11c \ucca0\uae30\uc2dc\ub300\ub85c \ub118\uc5b4\uac00\uba70 \ub098\ud0c0\ub09c \ubcc0\ud654\ub85c \uc633\uc740 \uac83\uc740?",B.awu,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \uc138\ud615 \ub3d9\uac80\uacfc \uac70\ud478\uc9d1(\uc794\ubb34\ub2ac \uac70\uc6b8 \ub4f1)\uc744 \ud1b5\ud574 \ub3c5\uc790\uc801\uc778 \uccad\ub3d9\uae30 \ubb38\ud654\uac00 \ub354\uc6b1 \ubc1c\uc804\ud558\ub294 \ud55c\ud3b8, \ucca0\uc81c \ubb34\uae30\xb7\ub18d\uae30\uad6c\uac00 \ubcf4\uae09\ub418\uc5c8\ub2e4. \ub5c0\uc11d\uae30\u2192\uac04\uc11d\uae30 \uc804\ud658\uc740 \uad6c\uc11d\uae30\u2192\uc2e0\uc11d\uae30, \uc815\ucc29 \uc0dd\ud65c \uc2dc\uc791\uc740 \uc2e0\uc11d\uae30, \uad70\uc7a5 \uad6d\uac00 \ub4f1\uc7a5\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ubcc0\ud654\uc774\ub2e4.",B.b1p,B.a3f,null)
B.aHj=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc774 \ucc98\uc74c\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \uc0c1\uc9d5\ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \uc774\uc6a9\ud574 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\ub294 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub97c \uc774\uc6a9\ud55c \uc0ac\ub0e5\uacfc \ucc44\uc9d1\uc774 \uacbd\uc81c\uc0dd\ud65c\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac\uac00 \ucc98\uc74c \uc2dc\uc791\ub418\uc5c8\ub2e4"],t.s)
B.aTp=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4"],t.s)
