B.bsN=new A.a("gen_kh_prehist_12","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300",'\ub2e4\uc74c \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud55c \uc2dc\ub300\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\uacfc \ub3c5\ubb34\ub364\uc774 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4."',B.aHj,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\xb7\ub3c5\ubb34\ub364 \ub4f1 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud558\ub294 \ud55c\ud3b8, \uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba74\uc11c \ud55c\uc790\uc640 \uba85\ub3c4\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5c8\ub2e4. \uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30, \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub294 \uc2e0\uc11d\uae30, \uc8fc\uba39\ub3c4\ub07c\ub294 \uad6c\uc11d\uae30, \ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac \uc2dc\uc791\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aTp,B.a9A,null)
B.a_q=s([u.bP,"\ubaa8\ub4e0 \ubc94\uc8c4\uc790\ub97c \uc2e0\ubd84\uc5d0 \uad00\uacc4\uc5c6\uc774 \ub3d9\uc77c\ud558\uac8c \ucc98\ubc8c\ud558\ub294 \ud3c9\ub4f1 \uc0ac\ud68c\uc758 \uc6d0\ub9ac\ub97c \ub2f4\uace0 \uc788\ub2e4","\ubd88\uad50\uc758 \uacc4\uc728\uc5d0 \ub530\ub77c \uc0b4\uc0dd\uacfc \ub3c4\ub451\uc9c8\uc744 \uc5c4\uaca9\ud788 \uae08\uc9c0\ud55c \uc885\uad50\uc801 \uaddc\ubc94\uc774\ub2e4","\uc911\uad6d \ud55c\ub098\ub77c\uc758 \uc728\ub839\uc744 \uadf8\ub300\ub85c \uc218\uc6a9\ud558\uc5ec \uc81c\uc815\ud55c \uc131\ubb38 \ubc95\uc804\uc774\ub2e4","\ud654\ubc31 \ud68c\uc758\uc758 \ub9cc\uc7a5\uc77c\uce58\uc81c\ub97c \uba85\ubb38\ud654\ud55c \ud569\uc758 \uaddc\ubc94\uc774\ub2e4"],t.s)
