B.bp_=new A.a("gen_kh_prehist_18","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uace0\uc870\uc120","\uace0\uc870\uc120\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.anA,0,"\ud654\ubc31 \ud68c\uc758\ub294 \uc2e0\ub77c\uc758 \uadc0\uc871 \ud569\uc758 \uae30\uad6c\ub85c, \uace0\uc870\uc120\uacfc\ub294 \uad00\ub828\uc774 \uc5c6\ub2e4. \uace0\uc870\uc120\uc740 \ub2e8\uad70\uc655\uac80\uc758 \uac74\uad6d \uc124\ud654\uac00 \u300c\uc0bc\uad6d\uc720\uc0ac\u300d\uc5d0 \uc804\ud558\uba70, \uc704\ub9cc \uc9d1\uad8c \uc774\ud6c4 \ucca0\uae30 \ubb38\ud654\ub97c \ubcf8\uaca9 \uc218\uc6a9\ud558\uace0 \uc911\uacc4 \ubb34\uc5ed\uc73c\ub85c \uc131\uc7a5\ud558\ub2e4\uac00 \ud55c \ubb34\uc81c\uc758 \uce68\uacf5\uc73c\ub85c \uba78\ub9dd\ud558\uc600\ub2e4.",B.aNd,B.p2,null)
B.aQV=s(["\uc655\uc774 \uc8fd\uc73c\uba74 \ub9ce\uc740 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc744 \ud568\uaed8 \ubb3b\ub294 \uc21c\uc7a5\uc758 \ud48d\uc2b5\uc774 \uc788\uc5c8\ub2e4","\uc74d\ub77d \uac04\uc758 \uacbd\uacc4\ub97c \uc911\uc2dc\ud558\uc5ec \uc774\ub97c \uce68\ubc94\ud558\uba74 \ucc45\ud654\ub85c \ubc30\uc0c1\ud558\uc600\ub2e4","\ubbfc\uba70\ub290\ub9ac\uc81c\ub77c\ub294 \ud63c\uc778 \ud48d\uc2b5\uc744 \ud1b5\ud574 \ub178\ub3d9\ub825\uc744 \ud655\ubcf4\ud558\uc600\ub2e4","\uc81c\uc0ac\uc7a5\uc778 \ucc9c\uad70\uc774 \uc18c\ub3c4\ub77c\ub294 \uc2e0\uc131 \uc9c0\uc5ed\uc744 \ub2e4\uc2a4\ub838\ub2e4","\uc11c\uc625\uc81c\ub77c\ub294 \ub370\ub9b4\uc0ac\uc704\uc81c \ud48d\uc2b5\uc774 \uc788\uc5c8\ub2e4"],t.s)
