B.bgX=new A.a("gen_kh_goryeo_1","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44",'(\uac00) \uc655\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"(\uac00)\uc740/\ub294 \u300c\uc815\uacc4\u300d\uc640 \u300c\uacc4\ubc31\ub8cc\uc11c\u300d\ub97c \uc9c0\uc5b4 \uad00\ub9ac\uac00 \uc9c0\ucf1c\uc57c \ud560 \uaddc\ubc94\uc744 \uc81c\uc2dc\ud558\uace0, \uc5b5\uc6b8\ud558\uac8c \ub178\ube44\uac00 \ub41c \uc790\ub97c \uc591\uc778\uc73c\ub85c \ud574\ubc29\ud558\ub294 \ub178\ube44\uc548\uac80\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4."',B.ZB,0,"\u300c\uc815\uacc4\u300d\xb7\u300c\uacc4\ubc31\ub8cc\uc11c\u300d \uc800\uc220\uacfc \ub178\ube44\uc548\uac80\ubc95\uc740 \uace0\ub824 \uad11\uc885\uc758 \uc815\ucc45\uc774\ub2e4. \uad11\uc885\uc740 \ub178\ube44\uc548\uac80\ubc95\uc73c\ub85c \ud638\uc871\uc758 \uacbd\uc81c\uc801\xb7\uad70\uc0ac\uc801 \uae30\ubc18\uc744 \uc57d\ud654\uc2dc\ud0a4\uace0 \uc655\uad8c\uc744 \uac15\ud654\ud558\uc600\ub2e4. 12\ubaa9 \uc124\uce58\ub294 \uc131\uc885, \uacfc\uac70\uc81c \uc2e4\uc2dc\ub294 \uad11\uc885(\uc30d\uae30 \uac74\uc758) \uc774\ud6c4 \uc131\uc885 \ub300\uc5d0 \uccb4\uc81c\ub85c \uc815\ucc29, \uc804\uc2dc\uacfc\ub294 \uacbd\uc885, \uad6d\uc790\uac10\xb7\uc591\ud604\uace0 \uc815\ube44\ub294 \uc608\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.ape,B.aN4,null)
B.aWi=s(["\uc804\uad6d\uc5d0 12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ud30c\uacac\ud558\uc600\ub2e4","\ub178\ube44\uc548\uac80\ubc95\uc744 \uc2dc\ud589\ud558\uc5ec \ud638\uc871\uc758 \uc138\ub825\uc744 \uc57d\ud654\uc2dc\ucf30\ub2e4","\ub3c5\uc790\uc801 \uc5f0\ud638\uc778 \uad11\ub355\xb7\uc900\ud48d\uc744 \uc0ac\uc6a9\ud558\uc600\ub2e4","\uac15\ub3d9 6\uc8fc\ub97c \ud68d\ub4dd\ud558\uc5ec \uc601\ud1a0\ub97c \ud655\uc7a5\ud558\uc600\ub2e4","\ucc9c\ub9ac\uc7a5\uc131\uc744 \ucd95\uc870\ud558\uc5ec \uad6d\uacbd \ubc29\ube44\ub97c \uac15\ud654\ud558\uc600\ub2e4"],t.s)
