B.bfn=new A.a("gen_kh_goryeo_2","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44",'\ub2e4\uc74c \uac74\uc758\ub97c \ubc1b\uc544\ub4e4\uc778 \uc655\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ucd5c\uc2b9\ub85c\uac00 \uc2dc\ubb34 28\uc870\ub97c \uc62c\ub824, \ubd88\uad50 \ud589\uc0ac\ub97c \uc904\uc774\uace0 \uc720\uad50 \uc815\uce58 \uc774\ub150\uc5d0 \ub530\ub77c \ud1b5\uce58 \uccb4\uc81c\ub97c \uc815\ube44\ud560 \uac83\uc744 \uac74\uc758\ud558\uc600\ub2e4."',B.aWi,0,"\ucd5c\uc2b9\ub85c\uc758 \uc2dc\ubb34 28\uc870\ub97c \ubc1b\uc544\ub4e4\uc778 \uc655\uc740 \uc131\uc885\uc774\ub2e4. \uc131\uc885\uc740 \uc720\uad50 \uc815\uce58 \uc774\ub150\uc5d0 \ub530\ub77c \uc804\uad6d\uc5d0 12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ucc98\uc74c \ud30c\uacac\ud558\ub294 \ub4f1 \uc911\uc559 \uc9d1\uad8c \uccb4\uc81c\ub97c \uc815\ube44\ud558\uc600\ub2e4. \ub178\ube44\uc548\uac80\ubc95\xb7\ub3c5\uc790 \uc5f0\ud638 \uc0ac\uc6a9\uc740 \uad11\uc885, \uac15\ub3d9 6\uc8fc \ud68d\ub4dd\uc740 \uc11c\ud76c\uc758 \uc678\uad50 \ub2f4\ud310(\uc131\uc885 \ub300\uc774\ub098 \ubcc4\ub3c4 \ub300\uc678\uad00\uacc4 \uc0ac\uac74), \ucc9c\ub9ac\uc7a5\uc131 \ucd95\uc870\ub294 \uc815\uc885~\ub355\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.aKG,B.No,null)
B.a7x=s([u.W,"\uc758\uc815\ubd80\uc640 6\uc870\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \ud1b5\uce58 \uccb4\uc81c\ub97c \uac16\ucd94\uc5c8\ub2e4","3\uc131 6\ubd80 \uccb4\uc81c\ub97c \uac16\ucd94\uc5b4 \uc0c1\uc11c\uc131\uc774 \uc2e4\uc9c8\uc801 \uc815\ucc45\uc744 \uacb0\uc815\ud558\uc600\ub2e4","\ube44\ubcc0\uc0ac\uac00 \uad6d\uc815 \uc804\ubc18\uc744 \ucd1d\uad04\ud558\ub294 \ucd5c\uace0 \uae30\uad6c\uc600\ub2e4","\ub3c5\uc11c\uc0bc\ud488\uacfc\ub97c \uc2e4\uc2dc\ud558\uc5ec \uad00\ub9ac\ub97c \uc120\ubc1c\ud558\uc600\ub2e4"],t.s)
