B.O_=s([u.B,"8\ub3c4 \uc544\ub798 \ubd80\xb7\ubaa9\xb7\uad70\xb7\ud604\uc744 \ub450\uace0 \ubaa8\ub4e0 \uad70\ud604\uc5d0 \uc218\ub839\uc744 \ud30c\uacac\ud558\uc600\ub2e4","\uc804\uad6d\uc744 9\uc8fc 5\uc18c\uacbd \uccb4\uc81c\ub85c \ud3b8\uc131\ud558\uc600\ub2e4","5\uacbd 15\ubd80 62\uc8fc\ub85c \uc9c0\ubc29\uc744 \ud3b8\uc131\ud558\uc600\ub2e4","23\ubd80\ub97c \uc124\uce58\ud558\uc5ec \uc9c0\ubc29\uad00\uc744 \ud30c\uacac\ud558\uc600\ub2e4"],t.s)
