B.bBO=new A.a("gen_kh_goryeo_4","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44","\uace0\ub824\uc758 \uc9c0\ubc29 \ud589\uc815 \uc81c\ub3c4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.O_,0,"\uace0\ub824\ub294 \uc77c\ubc18 \ud589\uc815 \uad6c\uc5ed\uc778 5\ub3c4\uc640 \uad70\uc0ac \ud589\uc815 \uad6c\uc5ed\uc778 \uc591\uacc4\ub85c \uc9c0\ubc29\uc744 \ub098\ub204\uc5c8\uc73c\uba70, \uc9c0\ubc29\uad00\uc774 \ud30c\uacac\ub41c \uc8fc\ud604\ubcf4\ub2e4 \ud30c\uacac\ub418\uc9c0 \uc54a\uc740 \uc18d\ud604\uc774 \ub354 \ub9ce\uc544 \ud5a5\ub9ac\uac00 \uc2e4\uc9c8\uc801\uc778 \ud589\uc815 \uc2e4\ubb34\ub97c \ub2f4\ub2f9\ud558\uc600\ub2e4. 8\ub3c4 \uccb4\uc81c\ub294 \uc870\uc120, 9\uc8fc 5\uc18c\uacbd\uc740 \ud1b5\uc77c\uc2e0\ub77c, 5\uacbd 15\ubd80 62\uc8fc\ub294 \ubc1c\ud574, 23\ubd80\ub294 \ubc31\uc81c\uc758 \uc9c0\ubc29 \uc81c\ub3c4\uc774\ub2e4.",B.aca,B.aQc,null)
B.aVK=s(["\u300c\ud6c8\uc694 10\uc870\u300d\ub97c \ub0a8\uaca8 \ud6c4\ub300 \uc655\ub4e4\uc774 \uc9c0\ucf1c\uc57c \ud560 \uc815\ucc45 \ubc29\ud5a5\uc744 \uc81c\uc2dc\ud558\uc600\ub2e4","\ub178\ube44\uc548\uac80\ubc95\uc744 \uc2e4\uc2dc\ud558\uc5ec \ud638\uc871\uc758 \uacbd\uc81c\uc801 \uae30\ubc18\uc744 \uc57d\ud654\uc2dc\ucf30\ub2e4","12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ucc98\uc74c\uc73c\ub85c \ud30c\uacac\ud558\uc600\ub2e4","\uc804\uc2dc\uacfc \uc81c\ub3c4\ub97c \ub9c8\ub828\ud558\uc5ec \uad00\ub9ac\uc5d0\uac8c \ud1a0\uc9c0\ub97c \uc9c0\uae09\ud558\uc600\ub2e4","\uacfc\uac70\uc81c\ub97c \ucc98\uc74c \uc2e4\uc2dc\ud558\uc5ec \uc720\uad50\uc801 \uc9c0\uc2dd\uc778\uc744 \ub4f1\uc6a9\ud558\uc600\ub2e4"],t.s)
B.aWy=s(["\u300c\ud6c8\uc694 10\uc870\u300d\ub97c \ub0a8\uaca8 \ud6c4\ub300 \uc655\ub4e4\uc774 \uc9c0\ucf1c\uc57c \ud560 \uc815\ucc45 \ubc29\ud5a5\uc744 \uc81c\uc2dc\ud558\uc600\ub2e4"],t.s)
