B.bgf=new A.a("gen_kh_goryeo_5","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44","\ud0dc\uc870 \uc655\uac74\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aVK,0,"\ud0dc\uc870 \uc655\uac74\uc740 \u300c\ud6c8\uc694 10\uc870\u300d\ub97c \ub0a8\uaca8 \ubd88\uad50 \uc22d\uc0c1, \uc11c\uacbd \uc911\uc2dc, \uac70\ub780 \ubc30\ucc99 \ub4f1 \ud6c4\ub300 \uc655\ub4e4\uc774 \uc9c0\ucf1c\uc57c \ud560 \uc815\ucc45 \ubc29\ud5a5\uc744 \uc81c\uc2dc\ud558\uc600\ub2e4. \ub178\ube44\uc548\uac80\ubc95\uc740 \uad11\uc885, 12\ubaa9 \uc124\uce58\ub294 \uc131\uc885, \uc804\uc2dc\uacfc\ub294 \uacbd\uc885, \uacfc\uac70\uc81c\ub294 \uad11\uc885 \ub300\uc758 \uc815\ucc45\uc774\ub2e4.",B.aWy,B.ac2,null)
B.aAK=s(["\ubb38\uacfc\xb7\uc7a1\uacfc\xb7\uc2b9\uacfc \ub4f1\uc758 \uacfc\uac70\ub97c \uc2e4\uc2dc\ud558\uc600\uace0, \ubb34\uacfc\ub294 \uac70\uc758 \uc2e4\uc2dc\ub418\uc9c0 \uc54a\uc558\ub2e4","\uc74c\uc11c\ub294 \uc655\uc871\uacfc \uacf5\uc2e0\uc758 \ud6c4\uc190\uc5d0\uac8c\ub9cc \uc81c\ud55c\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc5b4 \uac70\uc758 \uc2dc\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4","\uad6d\uc790\uac10\uc740 \ubb34\uc2e0\uc5d0\uac8c\ub9cc \uc785\ud559\uc774 \ud5c8\uc6a9\ub41c \uad50\uc721 \uae30\uad00\uc774\uc5c8\ub2e4","\uacfc\uac70 \uae09\uc81c \uc5c6\uc774\ub294 \uc5b4\ub5a0\ud55c \uad00\uc9c1\uc5d0\ub3c4 \uc624\ub97c \uc218 \uc5c6\uc5c8\ub2e4","\uc7a1\uacfc\uc5d0\uc11c\ub294 \uc720\uad50 \uacbd\uc804\ub9cc\uc744 \uc2dc\ud5d8 \uacfc\ubaa9\uc73c\ub85c \ub2e4\ub8e8\uc5c8\ub2e4"],t.s)
