B.ob=s(["\uace0\ub824\uc758 \uacfc\uac70 \uc81c\ub3c4"],t.s)
B.bek=new A.a("gen_kh_goryeo_6","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44","\uace0\ub824\uc758 \uad00\ub9ac \uc120\ubc1c\xb7\uad50\uc721 \uc81c\ub3c4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aAK,0,"\uace0\ub824\uc758 \uacfc\uac70\uc5d0\ub294 \ubb38\uc2e0\uc744 \ubf51\ub294 \uc81c\uc220\uacfc\xb7\uba85\uacbd\uacfc, \uae30\uc220\uad00\uc744 \ubf51\ub294 \uc7a1\uacfc, \uc2b9\ub824\ub97c \ub300\uc0c1\uc73c\ub85c \ud55c \uc2b9\uacfc \ub4f1\uc774 \uc788\uc5c8\uc73c\ub098 \ubb34\uacfc\ub294 \uac70\uc758 \uc2e4\uc2dc\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc74c\uc11c\ub294 \uc655\uc871\xb7\uacf5\uc2e0\xb75\ud488 \uc774\uc0c1 \uace0\uc704 \uad00\ub8cc\uc758 \uc790\uc190\uc5d0\uac8c \ud3ed\ub113\uac8c \ud5c8\uc6a9\ub418\uc5b4 \ubb38\ubc8c \uc0ac\ud68c\uc758 \ud2b9\uc9d5\uc744 \uc774\ub8e8\uc5c8\ub2e4.",B.aTe,B.ob,null)
B.a8b=s([u.yA,"\ubb34\uc2e0\uc5d0 \ub300\ud55c \ucc28\ubcc4\uc5d0 \ubc18\ubc1c\ud558\uc5ec \uc77c\uc5b4\ub09c \ubb34\uc2e0\ub4e4\uc758 \uc815\ubcc0\uc774\uc5c8\ub2e4","\uc11c\uacbd \ucc9c\ub3c4\ub97c \uc8fc\uc7a5\ud558\uba70 \uc77c\uc5b4\ub09c \ubc18\ub780\uc774\uc5c8\ub2e4","\ubabd\uace8\uc758 \uce68\uc785\uc5d0 \uc800\ud56d\ud558\uc5ec \uc77c\uc5b4\ub09c \ud56d\uc7c1\uc774\uc5c8\ub2e4","\uc0bc\ubcc4\ucd08\uac00 \uac1c\uacbd \ud658\ub3c4\uc5d0 \ubc18\ubc1c\ud558\uc5ec \uc77c\uc73c\ud0a8 \ud56d\uc7c1\uc774\uc5c8\ub2e4"],t.s)
