B.bfJ=new A.a("gen_kh_goryeo_10","korean_history","\uace0\ub824","\ubb38\ubc8c\uadc0\uc871\uc0ac\ud68c\uc640 \ubb34\uc2e0\uc815\uad8c","\ucd5c\uc528 \ubb34\uc2e0 \uc815\uad8c\uc758 \ud1b5\uce58 \uae30\uad6c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Wp,0,"\ucd5c\uc528 \ubb34\uc2e0 \uc815\uad8c\uc758 \uc131\ub9bd\uc790 \ucd5c\ucda9\ud5cc\uc740 \uad50\uc815\ub3c4\uac10\uc744 \uc124\uce58\ud558\uc5ec \uc778\uc0ac\xb7\uc7ac\uc815 \ub4f1 \uad6d\uc815 \uc804\ubc18\uc744 \ucd1d\uad04\ud558\ub294 \ucd5c\uace0 \uad8c\ub825 \uae30\uad6c\ub85c \uc0bc\uc558\ub2e4. \uc774\ud6c4 \ucd5c\uc6b0\ub294 \uc815\ubc29(\uc778\uc0ac)\uacfc \uc11c\ubc29(\ubb38\uc2e0 \uc790\ubb38)\uc744 \uc124\uce58\ud574 \uc815\uad8c\uc744 \ub4b7\ubc1b\uce68\ud558\uc600\ub2e4. \uc815\ubc29 \ud3d0\uc9c0\xb7\uc804\ubbfc\ubcc0\uc815\ub3c4\uac10 \uc124\uce58\ub294 \uacf5\ubbfc\uc655 \ub300\uc758 \uac1c\ud601 \uc815\ucc45\uc774\ub2e4.",B.aiC,B.aMe,null)
B.LC=s(["\ub9cc\uc801\uc774 \uac1c\uacbd\uc5d0\uc11c \uc2e0\ubd84 \ud574\ubc29\uc744 \ubaa9\ud45c\ub85c \ub178\ube44\ub4e4\uc744 \ubaa8\uc544 \ubc18\ub780\uc744 \ubaa8\uc758\ud558\uc600\ub2e4","\uc774\uc790\uacb8\uc774 \ucc99\uc900\uacbd\uacfc \ud568\uaed8 \ubc18\ub780\uc744 \uc77c\uc73c\ucf30\ub2e4","\ubb18\uccad\uc774 \uc11c\uacbd\uc5d0\uc11c \ubc18\ub780\uc744 \uc77c\uc73c\ucf30\ub2e4","\uc0bc\ubcc4\ucd08\uac00 \uac1c\uacbd \ud658\ub3c4\uc5d0 \ubc18\ub300\ud558\uc5ec \ud56d\uc7c1\ud558\uc600\ub2e4","\ud64d\uacbd\ub798\uac00 \ud3c9\uc548\ub3c4\uc5d0\uc11c \ubd09\uae30\ud558\uc600\ub2e4"],t.s)
B.Ub=s(["\ub9cc\uc801\uc774 \uac1c\uacbd\uc5d0\uc11c \uc2e0\ubd84 \ud574\ubc29\uc744 \ubaa9\ud45c\ub85c \ub178\ube44\ub4e4\uc744 \ubaa8\uc544 \ubc18\ub780\uc744 \ubaa8\uc758\ud558\uc600\ub2e4"],t.s)
