B.brP=new A.a("gen_kh_goryeo_18","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)","\uacf5\ubbfc\uc655\uc758 \ubc18\uc6d0 \uc790\uc8fc \uac1c\ud601 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_9,0,"\uacf5\ubbfc\uc655\uc740 \ubc18\uc6d0 \uc790\uc8fc \uc815\ucc45\uc744 \ucd94\uc9c4\ud558\uba70 \uc720\uc778\uc6b0\xb7\uc774\uc790\ucd98(\uc774\uc131\uacc4\uc758 \uc544\ubc84\uc9c0) \ub4f1\uc744 \ubcf4\ub0b4 \uc30d\uc131\ucd1d\uad00\ubd80\ub97c \ubb34\ub825\uc73c\ub85c \uc218\ubcf5\ud558\uc5ec \ucca0\ub839 \uc774\ubd81\uc758 \ub545\uc744 \ub418\ucc3e\uc558\ub2e4. \ub610\ud55c \uae30\ucca0 \ub4f1 \uce5c\uc6d0 \uc138\ub825\uc744 \uc219\uccad\ud558\uace0 \uc815\ub3d9\ud589\uc131 \uc774\ubb38\uc18c\ub97c \ud3d0\uc9c0\ud558\uc600\ub2e4. \uac15\ud654 \ucc9c\ub3c4\xb7\uc0bc\ubcc4\ucd08\xb7\ubcc4\ubb34\ubc18\uc740 \uacf5\ubbfc\uc655 \uc774\uc804 \uc2dc\uae30\uc758 \ub300\ubabd\xb7\ub300\uc5ec\uc9c4 \uad00\uacc4 \uc0ac\uac74\uc774\ub2e4.",B.akU,B.nF,null)
B.ag1=s([u.tt,"\uc804 \uad6d\ubbfc\uc5d0\uac8c \ud1a0\uc9c0\ub97c \uace8\uace0\ub8e8 \ub098\ub204\uc5b4 \uc900 \uade0\uc804\uc81c\uc600\ub2e4","\uc218\uc870\uad8c\uc774 \uc544\ub2cc \ud1a0\uc9c0\uc758 \uc18c\uc720\uad8c \uc790\uccb4\ub97c \uad00\ub9ac\uc5d0\uac8c \uc9c0\uae09\ud558\uc600\ub2e4","\uc591\ubc18 \uad00\ub8cc\uc5d0\uac8c\ub9cc \uc9c0\uae09\ub418\uace0 \ud5a5\ub9ac\xb7\uad70\uc778\uc5d0\uac8c\ub294 \uc9c0\uae09\ub418\uc9c0 \uc54a\uc558\ub2e4","\uc804\uc138\ub97c \ud48d\ud749\uc5d0 \uad00\uacc4\uc5c6\uc774 always \uc77c\uc815\ud558\uac8c \uace0\uc815\ud55c \uc81c\ub3c4\uc600\ub2e4"],t.s)
