B.brt=new A.a("gen_kh_modern_1","korean_history","\uadfc\ub300(\uac1c\ud56d\uae30)","\ud765\uc120 \ub300\uc6d0\uad70\uc758 \uc815\ucc45\uacfc \ud1b5\uc0c1 \uc218\uad50 \uac70\ubd80","\ud765\uc120 \ub300\uc6d0\uad70\uc758 \uc655\uad8c \uac15\ud654 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aol,0,"\ud765\uc120 \ub300\uc6d0\uad70\uc740 \uc138\ub3c4 \uc815\uce58\uc758 \ud3d0\ub2e8\uc744 \uac1c\ud601\ud558\uace0 \uc655\uad8c\uc744 \uac15\ud654\ud558\uae30 \uc704\ud574 \ube44\ubcc0\uc0ac\uc758 \uae30\ub2a5\uc744 \ucd95\uc18c\ud558\uace0 \uc758\uc815\ubd80\uc640 \uc0bc\uad70\ubd80\uc758 \uae30\ub2a5\uc744 \ud68c\ubcf5\uc2dc\ucf30\uc73c\uba70, \uc655\uc2e4\uc758 \uad8c\uc704\ub97c \uc138\uc6b0\uae30 \uc704\ud574 \uacbd\ubcf5\uad81\uc744 \uc911\uac74\ud558\uace0, \ubd95\ub2f9\uc758 \uadfc\uac70\uc9c0\uac00 \ub41c \uc11c\uc6d0\uc744 \ub300\ud3ed \uc815\ub9ac(\uc804\uad6d 47\uac1c\uc18c\ub9cc \ub0a8\uae40)\ud558\uc600\ub2e4. \ud0d5\ud3c9\ube44\xb7\uade0\uc5ed\ubc95\uc740 \uc601\uc870, \uaddc\uc7a5\uac01\xb7\uc7a5\uc6a9\uc601\uc740 \uc815\uc870, \u300c\uacbd\uad6d\ub300\uc804\u300d\uc740 \uc131\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.ai5,B.To,null)
B.aOa=s([u.CM,"\ubbf8\uad6d\uc774 \uc81c\ub108\ub7f4\uc154\uba3c\ud638 \uc0ac\uac74\uc744 \uad6c\uc2e4\ub85c \uac15\ud654\ub3c4\ub97c \uce68\uc785\ud558\uc600\ub2e4","\uc77c\ubcf8\uc774 \uc6b4\uc694\ud638 \uc0ac\uac74\uc744 \uc77c\uc73c\ucf1c \uac15\ud654\ub3c4 \uc870\uc57d \uccb4\uacb0\uc744 \uac15\uc694\ud558\uc600\ub2e4","\uc601\uad6d\uc774 \uac70\ubb38\ub3c4\ub97c \ubd88\ubc95\uc73c\ub85c \uc810\ub839\ud55c \uc0ac\uac74\uc774\ub2e4","\uccad\uc774 \uc784\uc624\uad70\ub780\uc744 \uc9c4\uc555\ud55c\ub2e4\ub294 \uba85\ubd84\uc73c\ub85c \uc870\uc120\uc5d0 \uad70\ub300\ub97c \ud30c\uacac\ud558\uc600\ub2e4"],t.s)
