B.bFG=new A.a("gen_kh_modern_2","korean_history","\uadfc\ub300(\uac1c\ud56d\uae30)","\ud765\uc120 \ub300\uc6d0\uad70\uc758 \uc815\ucc45\uacfc \ud1b5\uc0c1 \uc218\uad50 \uac70\ubd80","\ubcd1\uc778\uc591\uc694\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aOa,0,"\ubcd1\uc778\uc591\uc694(1866)\ub294 \ud504\ub791\uc2a4\uac00 \ubcd1\uc778\ubc15\ud574(\ucc9c\uc8fc\uad50 \ud0c4\uc555)\ub97c \uad6c\uc2e4\ub85c \uac15\ud654\ub3c4\ub97c \uce68\uc785\ud55c \uc0ac\uac74\uc73c\ub85c, \uc591\ud5cc\uc218 \ubd80\ub300\uc758 \uc815\uc871\uc0b0\uc131 \ud56d\uc804 \ub4f1\uc73c\ub85c \ud504\ub791\uc2a4\uad70\uc744 \ubb3c\ub9ac\ucce4\uc73c\ub098 \uc774 \uacfc\uc815\uc5d0\uc11c \ud504\ub791\uc2a4\uad70\uc774 \uc678\uaddc\uc7a5\uac01 \ub3c4\uc11c \ub4f1 \ubb38\ud654\uc7ac\ub97c \uc57d\ud0c8\ud574 \uac14\ub2e4. \uc2e0\ubbf8\uc591\uc694\ub294 \ubbf8\uad6d, \uac15\ud654\ub3c4 \uc870\uc57d\uc740 \uc6b4\uc694\ud638 \uc0ac\uac74, \uac70\ubb38\ub3c4 \uc0ac\uac74\uc740 \uc601\uad6d, \uc784\uc624\uad70\ub780 \ud30c\ubcd1\uc740 \uccad\uacfc \uad00\ub828\ub41c \uc0ac\uac74\uc774\ub2e4.",B.a8j,B.alU,null)
B.anS=s([u.lH,"\ud504\ub791\uc2a4\uac00 \ubcd1\uc778\ubc15\ud574\ub97c \uad6c\uc2e4\ub85c \uac15\ud654\ub3c4\ub97c \uce68\uc785\ud558\uc600\ub2e4","\uc77c\ubcf8\uc774 \uc6b4\uc694\ud638\ub97c \ubcf4\ub0b4 \uac15\ud654\ub3c4 \ucd08\uc9c0\uc9c4\uc744 \uacf5\uaca9\ud558\uc600\ub2e4","\uccad\uad70\uc774 \ud765\uc120 \ub300\uc6d0\uad70\uc744 \ub0a9\uce58\ud558\uc5ec \ud188\uc9c4\uc73c\ub85c \uc555\uc1a1\ud558\uc600\ub2e4","\ub7ec\uc2dc\uc544\uac00 \uc808\uc601\ub3c4 \uc870\ucc28\ub97c \uc694\uad6c\ud558\uc600\ub2e4"],t.s)
