B.bDb=new A.a("gen_cl_juridicalact_1","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.MG,0,"\ubc95\ub960\ud589\uc704\ub294 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\uc18c\ub85c \ud558\ub294 \ubc95\ub960\uc694\uac74\uc73c\ub85c, \uadf8 \uc758\uc0ac\ud45c\uc2dc\uc758 \ub0b4\uc6a9\uc5d0 \ub530\ub77c \uc77c\uc815\ud55c \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud55c\ub2e4. \uacc4\uc57d\ucc98\ub7fc \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc \ud569\uce58\ub97c \uc694\ud558\ub294 \uac83\ub3c4 \uc788\uc9c0\ub9cc, \uc720\uc5b8\xb7\ud574\uc81c\uc640 \uac19\uc740 \ub2e8\ub3c5\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774\ub3c4 \uc77c\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc131\ub9bd\ud55c\ub2e4. \uc131\ub9bd\uc694\uac74\uacfc \ud6a8\ub825\uc694\uac74\uc740 \uad6c\ubd84\ub418\ub294 \uac1c\ub150\uc774\ub2e4.",B.axC,B.anC,null)
