B.bgk=new A.a("gen_cl_juridicalact_3","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\uc694\uc2dd\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aLm,0,"\uc694\uc2dd\ud589\uc704\ub294 \ubc95\ub960\uc774 \uc77c\uc815\ud55c \ubc29\uc2dd(\uc11c\uba74, \uc2e0\uace0 \ub4f1)\uc744 \uac16\ucd9c \uac83\uc744 \uc694\uad6c\ud558\ub294 \ubc95\ub960\ud589\uc704\ub85c, \ud63c\uc778\xb7\uc720\uc5b8\xb7\ubc95\uc778 \uc124\ub9bd\ud589\uc704 \ub4f1\uc774 \ub300\ud45c\uc801\uc774\ub2e4. \ubbfc\ubc95\uc0c1 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\ubcc4\ud55c \ubc29\uc2dd\uc744 \uc694\ud558\uc9c0 \uc54a\ub294 \ubd88\uc694\uc2dd\ud589\uc704\uac00 \uc6d0\uce59\uc774\ub2e4.",B.at6,B.ar5,null)
