B.bds=new A.a("gen_cl_juridicalact_5","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubc18\uc0ac\ud68c\uc9c8\uc11c\uc758 \ubc95\ub960\ud589\uc704(\ubbfc\ubc95 \uc81c103\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.auB,0,'\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ubbc0\ub85c \uc774\ud589 \uc804\uc774\ub4e0 \ud6c4\ub4e0 \uadf8 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4. "\uc774\ud589 \uc804\uc774\ub77c\uba74 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ubc18\uba74 \ucc38\uace0\uc778 \ud5c8\uc704 \uc9c4\uc220 \ub300\uac00 \uc57d\uc815, \ub3c4\ubc15\uc790\uae08 \uc18c\ube44\ub300\ucc28 \ub4f1\uc740 \ud310\ub840\uc0c1 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\ub77c\uace0 \ubcf8 \ub300\ud45c\uc801 \uc0ac\ub840\uc774\uba70, \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \ub530\ub77c \uc774\ubbf8 \uae09\ubd80\ud55c \uac83\uc740 \ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \ubc18\ud658\uccad\uad6c\uac00 \ubd80\uc815\ub41c\ub2e4.',B.aL8,B.aNx,null)
B.RK=s(["\uac1d\uad00\uc801\uc73c\ub85c \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\uc5b4\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ud53c\ud574\uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc758 \uc0c1\ud0dc\uc5d0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc774 \ud53c\ud574\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc54c\uba74\uc11c \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\uc758\uc0ac)\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uad81\ubc15\uc740 \ubc18\ub4dc\uc2dc \uacbd\uc81c\uc801 \uad81\ubc15\uc5d0 \ud55c\uc815\ub418\uc9c0 \uc54a\uace0 \uc815\uc2e0\uc801\xb7\uc2ec\ub9ac\uc801 \uad81\ubc15\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4"],t.s)
B.TR=s(["\uac1d\uad00\uc801\uc73c\ub85c \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\uc5b4\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a9h=s(["\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74"],t.s)
B.bGk=new A.a("gen_cl_juridicalact_6","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\ubbfc\ubc95 \uc81c104\uc870)\uc758 \uc131\ub9bd\uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.RK,0,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615(\uac1d\uad00\uc801 \uc694\uac74)\uacfc \ud53c\ud574\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ubc0f \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\uc758\uc0ac(\uc8fc\uad00\uc801 \uc694\uac74)\uac00 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc838\uc57c \ud55c\ub2e4. \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\ub2e4\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.TR,B.a9h,null)
B.avZ=s([u.qo,"\ud45c\uc758\uc790\uac00 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub3c4 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc720\ud6a8\ud558\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aH0=s([u.qo],t.s)
B.Pm=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \uc6d0\uce59\uc801 \uc720\ud6a8"],t.s)
B.bnS=new A.a("gen_cl_juridicalact_7","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc(\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.avZ,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc2dc\ub41c \ub300\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aH0,B.Pm,null)
B.ST=s([u.xW,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0 \uc758\ud55c \ucc44\ubb34\ub97c \ubcf4\uc99d\ud55c \uc790\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc640 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.aO1=s([u.xW],t.s)
B.av1=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc131\ub9bd\uacfc \ud6a8\uacfc"],t.s)
B.bjr=new A.a("gen_cl_juridicalact_8","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\ubbfc\ubc95 \uc81c108\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ST,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \uc9c4\uc758\uc640 \ub2e4\ub978 \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc73c\ub85c, \uadf8 \uc790\uccb4\ub85c \ubb34\ud6a8\uc774\ub2e4. \ub2e4\ub9cc \uc774 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \uc591\ud574(\ud1b5\uc815)\ub97c \uc804\uc81c\ub85c \ud558\ubbc0\ub85c \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub294 \uc131\ub9bd\ud560 \uc218 \uc5c6\uace0, \ucc29\uc624\uc640\ub294 \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4.",B.aO1,B.av1,null)
B.ada=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790","\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778","\uac00\uc7a5\ucc44\uad8c\uc744 \uac00\uc555\ub958\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\uac00\uc7a5\uc591\uc218\uc778\uc73c\ub85c\ubd80\ud130 \ubaa9\uc801\ubb3c\uc744 \ub2e4\uc2dc \ub9e4\uc218\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ub97c \uc804\ud600 \ub2e4\ud22c\uc9c0 \uc54a\ub294 \ub2f9\uc0ac\uc790 \ubcf8\uc778"],t.s)
B.b15=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790"],t.s)
B.aUJ=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.bit=new A.a("gen_cl_juridicalact_9","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub294 \uc790\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ada,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub85c\ubd80\ud130 \ubcf4\ud638\ub418\ub294 \uc120\uc758\uc758 \uc81c3\uc790\ub780 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub85c\uc11c \uadf8 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc790\ub97c \ub9d0\ud55c\ub2e4. \uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ucc44\uad8c\uc744 \uc555\ub958\ud558\uba74\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790\ub294 \uc774\ub7ec\ud55c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub098, \ub2f9\uc0ac\uc790\xb7\ud3ec\uad04\uc2b9\uacc4\uc778\uc774\ub098 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790(\uc545\uc758)\ub294 \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uac00 \uc544\ub2c8\ub2e4.",B.b15,B.aUJ,null)
B.N7=s([u.hc,"\uc740\ub2c9\ud589\uc704\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\ub85c\uc11c \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\uac00 \uc788\ub294 \uacbd\uc6b0 \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704\uc640 \uc740\ub2c9\ub41c \ubc95\ub960\ud589\uc704\ub294 \ubaa8\ub450 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc791\uc131\ub418\uc5b4\uc57c \uc720\ud6a8\ud558\ub2e4","\uc740\ub2c9\ud589\uc704 \uc774\ub860\uc740 \ubb3c\uad8c\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aj_=s([u.hc],t.s)
B.b74=s(["\uc740\ub2c9\ud589\uc704\uc758 \ubc95\ub9ac"],t.s)
B.bAt=new A.a("gen_cl_juridicalact_10","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\uc740\ub2c9\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.N7,0,"\ub2f9\uc0ac\uc790\uac00 \uc9c4\uc815\uc73c\ub85c \uc758\uc695\ud55c \ubc95\ub960\ud589\uc704(\uc608: \uc99d\uc5ec)\ub97c \ub2e4\ub978 \ubc95\ub960\ud589\uc704(\uc608: \ub9e4\ub9e4)\ub85c \uac00\uc7a5\ud558\uc5ec \ud45c\uc2dc\ud55c \uacbd\uc6b0, \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704(\ub9e4\ub9e4)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubc30\ud6c4\uc5d0 \uc228\uaca8\uc9c4 \uc9c4\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc99d\uc5ec, \uc740\ub2c9\ud589\uc704)\ub294 \uadf8 \uc790\uccb4\uc758 \uc131\ub9bd\xb7\ud6a8\ub825 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4.",B.aj_,B.b74,null)
B.abE=s([u.pt,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\uc9c0\ub9cc, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ud56d\uc0c1 \uc720\ud6a8\uc774\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc694\uac74\uacfc \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aBh=s([u.pt],t.s)
B.b08=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uad6c\ubcc4"],t.s)
B.bmu=new A.a("gen_cl_juridicalact_11","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.abE,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc758\uc790 \ud63c\uc790\ub9cc \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \uc788\uc73c\uba74 \ub418\uace0 \uc0c1\ub300\ubc29\uacfc\uc758 \ud569\uc758(\ud1b5\uc815)\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ubc18\uba74, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \ud5c8\uc704\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4. \ub2e4\ub9cc \ub450 \uc81c\ub3c4 \ubaa8\ub450 \uc6d0\uce59\uc801 \ud6a8\ub825\uacfc \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uc5d0 \uc788\uc5b4 \uc720\uc0ac\ud55c \uad6c\uc870\ub97c \ucde8\ud55c\ub2e4.",B.aBh,B.b08,null)
B.a_K=s([u.k,"\u4e19\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \u7532\uc740 \uc5b8\uc81c\ub098 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\u4e19\uc774 \uc545\uc758\uc600\ub354\ub77c\ub3c4 \u7532\uc740 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\u4e19\uc740 \ub4f1\uae30\ub97c \ub9c8\ucce4\ub354\ub77c\ub3c4 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud560 \uc218 \uc5c6\ub2e4","\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ud5c8\uc704\ud45c\uc2dc\ub294 \uc560\ucd08\uc5d0 \uc720\ud6a8\ud558\ubbc0\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.akQ=s([u.k],t.s)
B.a7n=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \uc804\ub4dd\uc790(\uc81c3\uc790) \ubcf4\ud638"],t.s)
B.bzB=new A.a("gen_cl_juridicalact_12","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\u7532\uacfc \u4e59\uc774 \ud1b5\uc815\ud558\uc5ec \u7532 \uc18c\uc720 \ubd80\ub3d9\uc0b0\uc744 \u4e59\uc5d0\uac8c \ud5c8\uc704\ub85c \ub9e4\ub3c4\ud55c \uac83\ucc98\ub7fc \ub4f1\uae30\ub97c \ub9c8\ucce4\ub294\ub370, \u4e59\uc774 \uc774\ub97c \u4e19\uc5d0\uac8c \ub9e4\ub3c4\ud558\uace0 \u4e19 \uba85\uc758\ub85c \ub4f1\uae30\ub97c \uc774\uc804\ud55c \uc0ac\uc548\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984, \u4e19\uc740 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubab0\ub790\uc74c)",B.a_K,0,"\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ub9e4\ub9e4\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \u4e19\uc774 \ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubaa8\ub978 \uc120\uc758\uc758 \uc81c3\uc790\ub77c\uba74 \u7532\uc740 \u4e19\uc5d0 \ub300\ud558\uc5ec \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\uc5ec \uc18c\uc720\uad8c\uc744 \ub418\ucc3e\uc744 \uc218 \uc5c6\ub2e4.",B.akQ,B.a7n,null)
B.aSa=s([u.vC,"\ucc29\uc624\uac00 \ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc778\ud55c \uac83\uc774\ub354\ub77c\ub3c4 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\ub960\ud589\uc704 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.avm=s([u.vC],t.s)
B.aaS=s(["\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c"],t.s)
B.bu5=new A.a("gen_cl_juridicalact_13","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\ubbfc\ubc95 \uc81c109\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aSa,0,"\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud45c\uc758\uc790\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0, \ucde8\uc18c\uc758 \ud6a8\uacfc\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \ub3d9\uae30\uc758 \ucc29\uc624\ub3c4 \uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \ub41c \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc788\ub2e4.",B.avm,B.aaS,null)
B.QV=s([u.m_,"\ud1a0\uc9c0\ub9e4\ub9e4\uc5d0\uc11c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud56d\uc0c1 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub3d9\uae30\uc5d0 \uad00\ud55c \ucc29\uc624\ub97c \uc81c\uc678\ud558\uace0\ub294 \uc778\uc815\ub420 \uc218 \uc5c6\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ub3d9\uc77c\ud558\uac8c \ud310\ub2e8\ub41c\ub2e4"],t.s)
B.a5w=s([u.m_],t.s)
B.awH=s(["\uc911\uc694\ubd80\ubd84 \ucc29\uc624\uc758 \ud310\ub2e8\uae30\uc900"],t.s)
B.bh2=new A.a("gen_cl_juridicalact_14","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.QV,0,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uac00 \ucc29\uc624\ub85c \uc778\ud558\uc5ec \uacbd\uc81c\uc801 \ubd88\uc774\uc775\uc744 \uc785\uc9c0 \uc54a\uc558\ub2e4\uba74 \uadf8 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \uad00\ud55c \uac83\uc774\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4. \ubc18\ub300\ub85c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub85c \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\uba70, \uc911\uc694\ubd80\ubd84 \ud574\ub2f9 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uacfc \uc77c\ubc18\uc778\uc758 \uac1d\uad00\uc801 \uae30\uc900\uc744 \ud568\uaed8 \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4.",B.a5w,B.awH,null)
B.b1Z=s([u.Ay,"\uc81c3\uc790\uc758 \uc0ac\uae30\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uac00 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4","\uae30\ub9dd\ud589\uc704\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a7H=s([u.Ay],t.s)
B.aQS=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc"],t.s)
B.bAe=new A.a("gen_cl_juridicalact_15","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.b1Z,0,"\uc0c1\ub300\ubc29\uc758 \uae30\ub9dd\ud589\uc704\ub85c \ucc29\uc624\uc5d0 \ube60\uc838 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \uc81c3\uc790\uc758 \uc0ac\uae30\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\uace0, \ucde8\uc18c\uc758 \ud6a8\uacfc\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.a7H,B.aQS,null)
B.b0R=s([u.s,"\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\uba70 \ucde8\uc18c\uc758 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uac15\ubc15\ud589\uc704\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c\ub294 \ubd88\ubc95\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc640 \uc694\uac74\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.aHh=s([u.s],t.s)
B.aLp=s(["\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c"],t.s)
B.bE2=new A.a("gen_cl_juridicalact_16","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.b0R,0,"\ud1b5\uc0c1\uc801\uc778 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc774\uc9c0\ub9cc, \uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\uac00 \uc644\uc804\ud788 \ubc15\ud0c8\ub41c \uc0c1\ud0dc(\uc758\uc0ac\ud45c\uc2dc\uc790\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uac83\uacfc \uac19\uc740 \uc0c1\ud0dc)\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \ubb34\ud6a8\ub77c\uace0 \ubcf8\ub2e4.",B.aHh,B.aLp,null)
B.Md=s([u.a0,"\ucc29\uc624\uc640 \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uc640 \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \ucc29\uc624\uc5d0 \uc758\ud55c \ucde8\uc18c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uc640 \uc0ac\uae30\ub294 \uacb0\ucf54 \ub3d9\uc2dc\uc5d0 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub294 \ubc30\ud0c0\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc778\uc815\ub418\uba74 \ucc29\uc624\uc758 \uc131\ub9bd \uc5ec\ubd80\ub294 \ud310\ub2e8\ud560 \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4"],t.s)
