B.bp7=new A.a("gen_cl_antisocial_1","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c103\uc870\uc5d0\uc11c \uc815\ud55c \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8 \uc694\uac74\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aiq,0,'\ubbfc\ubc95 \uc81c103\uc870\ub294 "\uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud55c \uc0ac\ud56d\uc744 \ub0b4\uc6a9\uc73c\ub85c \ud558\ub294 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"\uace0 \uaddc\uc815\ud55c\ub2e4. \uc5ec\uae30\uc11c \ubb34\ud6a8 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9 \uc790\uccb4(\ub610\ub294 \uc774\uc640 \uacb0\ud569\ub41c \ub3d9\uae30 \ub4f1)\uac00 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uba70, \ub2f9\uc0ac\uc790\uc758 \ub2a5\ub825\uc774\ub098 \ud615\uc2dd(\uad6c\ub450\xb7\uc11c\uba74), \uc774\ud589\uae30 \ub3c4\ub798 \uc5ec\ubd80\uc640\ub294 \ubb34\uad00\ud558\ub2e4.',B.b8R,B.b_u,null)
B.Ro=s(["\ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud560 \ub2f9\uc2dc","\uc774\ud589\uc774 \uc644\ub8cc\ub41c \ub54c","\ubd84\uc7c1\uc774 \uc18c\uc1a1\uc73c\ub85c \uc81c\uae30\ub41c \ub54c","\ubc95\ub960\ud589\uc704 \uc131\ub9bd \ud6c4 \uc0ac\uc815\ubcc0\uacbd\uc774 \uc0dd\uae34 \ub54c"],t.s)
B.aLJ=s(["\ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub54c, \uc989 \uc131\ub9bd \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8"],t.s)
