B.bdf=new A.a("gen_cl_antisocial_22","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uc0b4\uc778, \ubc29\ud654 \ub4f1 \ubc94\uc8c4\ud589\uc704\ub97c \uc2e4\ud589\ud558\ub294 \ub300\uac00\ub85c \uae08\uc804\uc744 \uc9c0\uae09\ud558\uae30\ub85c \ud55c \uccad\ubd80\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.aH4,1,"\ubc94\uc8c4\ud589\uc704\uc758 \uc2e4\ud589 \uc790\uccb4\ub97c \ub0b4\uc6a9\uc73c\ub85c \ud558\uac70\ub098 \uadf8 \ub300\uac00\ub97c \uc9c0\uae09\ud558\uae30\ub85c \ud558\ub294 \uacc4\uc57d\uc740 \uadf8 \ub0b4\uc6a9 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c \ucc98\uc74c\ubd80\ud130 \uc808\ub300\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uba70, \uc5b4\ub5a0\ud55c \uc870\uac74\uc774\ub098 \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4.",B.aXH,B.X6,null)
B.a50=s(["\uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\uc784\ucc28\uc778\ub9cc \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc804\ub300\ucc28\ub9cc \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.Kn=s(["\ub3d9\uae30\uc758 \ubd88\ubc95\uc744 \uc784\ub300\uc778\uc774 \uc778\uc2dd\ud55c \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
