B.bFh=new A.a("gen_cl_antisocial_24","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub97c \ub2f9\uc0ac\uc790\uac00 \ub098\uc911\uc5d0 \ucd94\uc778\ud55c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.Tl,2,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c \ubcf8\ub2e4\ub294 \uac83\uc774 \uc6d0\uce59(\uc81c139\uc870)\uc774\uc9c0\ub9cc, \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub294 \uadf8 \ubb34\ud6a8\uac00 \uc0ac\ud68c\uc9c8\uc11c \uc720\uc9c0\ub97c \uc704\ud55c \uac15\ud589\ubc95\uaddc\uc801 \uc131\uaca9\uc744 \uac00\uc9c0\ubbc0\ub85c \ucd94\uc778\uc5d0 \uc758\ud574\uc11c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\xb7\ud1b5\uc124\uc758 \uc785\uc7a5\uc774\ub2e4.",B.axv,B.o6,null)
B.aY0=s(["\uacc4\uc57d \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c \uc120\uc758\uc758 \uc81c3\uc790\ub97c \ud3ec\ud568\ud558\uc5ec \ub204\uad6c\uc5d0\uac8c\ub098 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ub4f1\uae30\ub97c \ub9c8\uce5c \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aZT=s(["\uc808\ub300\uc801 \ubb34\ud6a8\uc774\ubbc0\ub85c","\uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ub300\ud55c \uad00\uacc4\uc5d0\uc11c\ub3c4 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
