B.bn_=new A.a("gen_cl_antisocial_25","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\ub294 \ub204\uad6c\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294\uac00?",B.aY0,2,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\ub294 \uc0ac\ud68c\uc9c8\uc11c \uc720\uc9c0\ub77c\ub294 \uacf5\uc775\uc801 \uc694\uccad\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\uc774\ubbc0\ub85c, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ub300\ud55c \uad00\uacc4\uc5d0\uc11c\ub3c4 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc0c1\ub300\uc801 \ubb34\ud6a8(\uc608: \ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \ubb34\ud6a8)\uc640 \uad6c\ubcc4\ub41c\ub2e4.",B.aZT,B.pa,null)
B.aK4=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \ud56d\uc0c1 \uace7\ubc14\ub85c \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ubc95\uaddc \uc704\ubc18\uc5d0 \ub530\ub978 \ubcc4\ub3c4\uc758 \ud6a8\ub825(\ubb34\ud6a8 \ub4f1) \ubb38\uc81c\uc774\uace0, \uace7\ubc14\ub85c \uc81c103\uc870 \uc704\ubc18\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \uc544\ubb34\ub7f0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \ubc18\ub4dc\uc2dc \ucde8\uc18c\uc0ac\uc720\uac00 \ub41c\ub2e4"],t.s)
B.b3X=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub77c\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18(\uc81c103\uc870)\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.b46=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uacfc \uad6c\ubcc4"],t.s)
B.bBk=new A.a("gen_cl_antisocial_26","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ub2e8\uc21c\ud788 \uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ud55c \ubc95\ub960\ud589\uc704\ub294 \uadf8 \uc790\uccb4\ub85c \ubbfc\ubc95 \uc81c103\uc870\uc758 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294\uac00?",B.aK4,1,"\uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ud55c \ubc95\ub960\ud589\uc704\ub294 \uadf8 \ubc95\uaddc \uc790\uccb4\uac00 \uc815\ud558\ub294 \ud6a8\uacfc(\ubb34\ud6a8 \ub4f1)\uc758 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, \uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub77c\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18(\uc81c103\uc870)\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uadf8 \uc704\ubc18\uc758 \uc815\ub3c4\uac00 \uc0ac\ud68c\ud1b5\ub150\uc0c1 \uc6a9\uc778\ub420 \uc218 \uc5c6\uc744 \ub9cc\ud07c \uc911\ub300\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc81c103\uc870 \uc704\ubc18\uc73c\ub85c\ub3c4 \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4.",B.b3X,B.b46,null)
B.aRo=s(["\uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\uc740 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uacfc \ubcc4\uac1c\uc774\ubbc0\ub85c \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ud53c\ub2f4\ubcf4\ucc44\uad8c\uc774 \ubc18\uc0ac\ud68c\uc9c8\uc11c\ub85c \ubb34\ud6a8\ub77c\uba74 \uc774\ub97c \ub2f4\ubcf4\ud558\uae30 \uc704\ud55c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\ub3c4 \ubb34\ud6a8\uc774\ub2e4","\uc800\ub2f9\uad8c \ub4f1\uae30\uac00 \ub9c8\uccd0\uc9c0\uba74 \ub2f4\ubcf4\uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uce58\uc720\ub41c\ub2e4","\uc800\ub2f9\uad8c\uc790\uac00 \uc120\uc758\uc774\uba74 \ub2f4\ubcf4\uacc4\uc57d\uc740 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aU3=s(["\ud53c\ub2f4\ubcf4\ucc44\uad8c \ubc1c\uc0dd\uc758 \uc6d0\uc778\uc774 \ub41c \ubc95\ub960\ud589\uc704 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\ub85c \ubb34\ud6a8\ub77c\uba74","\uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d \uc5ed\uc2dc \ubb34\ud6a8"],t.s)
B.aqu=s(["\ubd80\uc885\uc131\uacfc \ub2f4\ubcf4\uacc4\uc57d \ubb34\ud6a8"],t.s)
B.bey=new A.a("gen_cl_antisocial_27","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud558\uc5ec \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.aRo,1,"\ub2f4\ubcf4\ubb3c\uad8c\uc740 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc5d0 \ub300\ud55c \ubd80\uc885\uc131\uc744 \uac00\uc9c0\ubbc0\ub85c, \ud53c\ub2f4\ubcf4\ucc44\uad8c \ubc1c\uc0dd\uc758 \uc6d0\uc778\uc774 \ub41c \ubc95\ub960\ud589\uc704 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\ub85c \ubb34\ud6a8\ub77c\uba74 \uc774\ub97c \ub2f4\ubcf4\ud558\uae30 \uc704\ud574 \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d \uc5ed\uc2dc \ubb34\ud6a8\uac00 \ub41c\ub2e4.",B.aU3,B.aqu,null)
B.Xt=s(["\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc720\ud6a8\ud558\ub2e4","\uae30\uac04\xb7\uc9c0\uc5ed\xb7\uc5c5\uc885 \ub4f1\uc758 \uc81c\ud55c\uc774 \ud569\ub9ac\uc801 \ubc94\uc704\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec \uadfc\ub85c\uc790 \ub4f1\uc758 \uc0dd\uc874\uacfc \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\ub97c \uacfc\ub3c4\ud558\uac8c \uc81c\uc57d\ud558\ub294 \uacbd\uc6b0 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc77c \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ub4f1\uae30\ud558\uc5ec\uc57c\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.aA7=s(["\ud569\ub9ac\uc801 \ud55c\ub3c4\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec","\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4"],t.s)
