B.bmc=new A.a("gen_cl_antisocial_28","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uc9c0\ub098\uce58\uac8c \uc7a5\uae30\uac04 \ub610\ub294 \uc804\uba74\uc801\uc73c\ub85c \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\ub97c \uc81c\ud55c\ud558\ub294 \uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Xt,1,"\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \uc601\uc5c5\uc0c1 \uc774\uc775 \ubcf4\ud638\ub97c \uc704\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0\ub9cc, \uadf8 \uae30\uac04\xb7\uc9c0\uc5ed\xb7\ub300\uc0c1 \uc5c5\ubb34\uc758 \ubc94\uc704\uac00 \ud569\ub9ac\uc801 \ud55c\ub3c4\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\uc640 \uc0dd\uc874\uc744 \uacfc\ub3c4\ud558\uac8c \uc81c\uc57d\ud558\ub294 \uc815\ub3c4\uc5d0 \uc774\ub974\uba74 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4.",B.aA7,B.aWb,null)
B.adP=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9","\ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c0\uac8c \ub41c \ub3d9\uae30 \ubc0f \uacbd\uc704","\ubc95\ub960\ud589\uc704\ub85c \uc778\ud574 \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc","\ubc95\ub960\ud589\uc704 \ub2f9\uc0ac\uc790\uc758 \uc7ac\uc0b0\uc138 \ub0a9\ubd80 \uc5ec\ubd80"],t.s)
B.aNi=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9, \uadf8 \uc131\ub9bd \uacfc\uc815\uc5d0\uc11c\uc758 \ubd88\ubc95\uc801 \ubc29\ubc95\uc758 \uc0ac\uc6a9 \uc5ec\ubd80, \ub3d9\uae30, \ubaa9\uc801, \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824"],t.s)
B.amq=s(["\ud310\ub2e8 \uace0\ub824\uc694\uc18c"],t.s)
B.bdy=new A.a("gen_cl_antisocial_29","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc778\uc9c0 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.adP,3,"\ud310\ub840\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \ud574\ub2f9 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud560 \ub54c \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9, \uadf8 \uc131\ub9bd \uacfc\uc815\uc5d0\uc11c\uc758 \ubd88\ubc95\uc801 \ubc29\ubc95\uc758 \uc0ac\uc6a9 \uc5ec\ubd80, \ub3d9\uae30, \ubaa9\uc801, \uc2e4\ud604\ub418\ub294 \ud6a8\uacfc \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud55c\ub2e4. \ub2f9\uc0ac\uc790\uc758 \uc138\uae08 \ub0a9\ubd80 \uc5ec\ubd80\uc640 \uac19\uc740 \uc0ac\uc815\uc740 \uc774\uc640 \ubb34\uad00\ud55c \uc694\uc18c\uc774\ub2e4.",B.aNi,B.amq,null)
B.aUn=s(["\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uc740 \ud615\uc2dd\uc774 \uac16\ucd94\uc5b4\uc9c4 \uc774\uc0c1 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ucc44\ubb34\uc561\uacfc \ub2f4\ubcf4\ubaa9\uc801\ubb3c \uac00\uc561\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \ud3ed\ub9ac\uc801\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ub0b4\uc9c0 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\ub4f1\uae30\uac00 \uc774\uc804\ub418\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud6a8\ub825\uc744 \ub2e4\ud234 \uc218 \uc5c6\ub2e4","\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uc740 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \ubd88\ub9ac\ud558\uba74 \ub2f9\uc5f0\ud788 \ucde8\uc18c\uc0ac\uc720\uac00 \ub41c\ub2e4"],t.s)
B.NJ=s(["\ucc44\uad8c\uc790\uac00 \ubd80\ub2f9\ud55c \ud3ed\ub9ac\ub97c \ucde8\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0","\ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4"],t.s)
B.adX=s(["\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d\uacfc \ud3ed\ub9ac"],t.s)
B.bk2=new A.a("gen_cl_antisocial_30","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d \uc790\uccb4\ub294 \uc720\ud6a8\ud558\ub354\ub77c\ub3c4, \uadf8 \uc608\uc57d\uc774 \ucc44\uad8c\uc790\uc758 \ud3ed\ub9ac \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\uc5b4 \ucc44\ubb34\uc561\uc5d0 \ube44\ud574 \ud604\uc800\ud788 \uace0\uac00\uc758 \ubd80\ub3d9\uc0b0\uc744 \ucde8\ub4dd\ud558\uac8c \ud558\ub294 \uacbd\uc6b0\uc758 \ubc95\uc801 \ud3c9\uac00\ub85c \uc633\uc740 \uac83\uc740?",B.aUn,1,"\ub300\ubb3c\ubcc0\uc81c\uc608\uc57d \uc790\uccb4\ub294 \ub2f4\ubcf4 \ubaa9\uc801\uc758 \uc720\ud6a8\ud55c \uacc4\uc57d\ud615\uc2dd\uc774\uc9c0\ub9cc, \ucc44\ubb34\uc561\uc5d0 \ube44\ud558\uc5ec \ud604\uc800\ud788 \uace0\uac00\uc778 \ubaa9\uc801\ubb3c\uc744 \uc774\uc804\ubc1b\ub3c4\ub85d \ud558\uc5ec \ucc44\uad8c\uc790\uac00 \ubd80\ub2f9\ud55c \ud3ed\ub9ac\ub97c \ucde8\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc81c103\uc870 \ub610\ub294 \uc81c104\uc870 \uc704\ubc18\uc73c\ub85c \uadf8 \uc608\uc57d(\ub610\ub294 \uadf8\uc5d0 \ub530\ub978 \uc774\uc804\uc758 \ud6a8\ub825)\uc774 \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4.",B.NJ,B.adX,null)
B.b_Q=s(["\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc5b8\uc81c\ub098 \ub300\ub9ac\uc778\uc5d0\uac8c \uba3c\uc800 \uadc0\uc18d\ub41c \ud6c4 \ubcf8\uc778\uc5d0\uac8c \uc774\uc804\ub41c\ub2e4","\ub300\ub9ac\ud589\uc704\ub294 \ub300\ub9ac\uc778\uacfc \ubcf8\uc778\uc774 \ud568\uaed8 \uc11c\uba85\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4"],t.s)
