B.bwY=new A.a("gen_cl_agency_1","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b_Q,0,"\ubbfc\ubc95 \uc81c114\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4. \ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc744 \uac70\uce58\uc9c0 \uc54a\uace0 \ucc98\uc74c\ubd80\ud130 \ubcf8\uc778\uc5d0\uac8c \uc9c1\uc811 \uadc0\uc18d\ub41c\ub2e4.",B.aX7,B.aXZ,null)
B.aXQ=s(["\ud56d\uc0c1 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf4\uc544 \uc6d0\uce59\uc801\uc73c\ub85c \ub300\ub9ac\uc778 \uc790\uc2e0\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4"],t.s)
B.aw5=s(["\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.aVa=s(["\ud604\uba85\uc8fc\uc758"],t.s)
B.byH=new A.a("gen_cl_agency_2","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uacbd\uc6b0(\ud604\uba85\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0)\uc758 \ud6a8\uacfc\ub294?",B.aXQ,1,"\ubbfc\ubc95 \uc81c115\uc870 \ubcf8\ubb38\uc740 \ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc790\uae30\ub97c \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub2e8\uc11c\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \uc81c114\uc870\uac00 \uc900\uc6a9\ub418\uc5b4 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.aw5,B.aVa,null)
B.aNl=s(["\ubcf8\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc0c1\ub300\ubc29\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubcf8\uc778\uacfc \ub300\ub9ac\uc778 \uc911 \uc720\ub9ac\ud55c \ucabd\uc744 \uc120\ud0dd\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.agD=s(["\uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4"],t.s)
B.KZ=s(["\ub300\ub9ac\ud589\uc704 \ud558\uc790\uc758 \ud310\ub2e8\uae30\uc900"],t.s)
B.bmn=new A.a("gen_cl_agency_3","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790(\uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30\xb7\uac15\ubc15, \ud2b9\uc815 \uc0ac\uc815\uc5d0 \ub300\ud55c \uc545\uc758\xb7\uacfc\uc2e4 \ub4f1) \uc720\ubb34\ub294 \ub204\uad6c\ub97c \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?",B.aNl,1,"\ubbfc\ubc95 \uc81c116\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30\xb7\uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc778\ud558\uc5ec \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0\uc5d0 \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4. \uc2e4\uc81c\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc740 \ub300\ub9ac\uc778\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.",B.agD,B.KZ,null)
B.ajF=s(["\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \ud589\uc704\ub2a5\ub825\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4","\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\uba70, \uc81c\ud55c\ub2a5\ub825\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc778 \uacbd\uc6b0 \uadf8 \ub300\ub9ac\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \uc131\ub144\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4"],t.s)
