B.XU=s(["\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ubd88\uc694"],t.s)
B.bsb=new A.a("gen_cl_agency_4","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc758 \ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ajF,1,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ub300\ub9ac\ud589\uc704\uc758 \ubc95\ub960\ud6a8\uacfc\uac00 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\uc5b4 \ub300\ub9ac\uc778 \uc790\uc2e0\uc740 \ubd88\uc774\uc775\uc744 \uc785\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\uba70, \ub530\ub77c\uc11c \uc81c\ud55c\ub2a5\ub825\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\ub2e4.",B.p_,B.XU,null)
B.avi=s(["\ubcf4\uc874\ud589\uc704 \ubc0f \ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc744 \ucc98\ubd84\ud558\ub294 \ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704","\uc81c\ud55c \uc5c6\uc774 \ubaa8\ub4e0 \ucc98\ubd84\ud589\uc704"],t.s)
B.aZ4=s(["\ubcf4\uc874\ud589\uc704\uc640","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uadf8 \uc774\uc6a9 \ub610\ub294 \uac1c\ub7c9\ud558\ub294 \ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.apR=s(["\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc758 \uad8c\ud55c\ubc94\uc704"],t.s)
B.bEu=new A.a("gen_cl_agency_5","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc774 \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc740 \uac83\uc740?",B.avi,0,"\ubbfc\ubc95 \uc81c118\uc870\uc5d0 \ub530\ub77c \uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \u2460 \ubcf4\uc874\ud589\uc704\uc640 \u2461 \ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uadf8 \uc774\uc6a9 \ub610\ub294 \uac1c\ub7c9\ud558\ub294 \ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4. \ucc98\ubd84\ud589\uc704\ub098 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704\ub294 \ud560 \uc218 \uc5c6\ub2e4.",B.aZ4,B.apR,null)
B.aAQ=s(["\ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4","\ubc18\ub4dc\uc2dc \uc804\uc6d0\uc774 \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud560 \uc218 \uc788\ub2e4","\ub2e4\uc218\uacb0\ub85c \ub300\ub9ac\ud589\uc704 \uc5ec\ubd80\ub97c \uacb0\uc815\ud55c\ub2e4","\uc5f0\uc7a5\uc790\uac00 \ub300\ud45c\ub85c \ub300\ub9ac\ud55c\ub2e4"],t.s)
B.a0w=s(["\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4"],t.s)
B.b6A=s(["\uac01\uc790\ub300\ub9ac\uc758 \uc6d0\uce59"],t.s)
B.bAk=new A.a("gen_cl_agency_6","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \uc218\uc778(\u6578\u4eba)\uc778 \uacbd\uc6b0 \ub300\ub9ac \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc6d0\uce59\uc740?",B.aAQ,0,"\ubbfc\ubc95 \uc81c119\uc870\ub294 \ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\uac01\uc790\ub300\ub9ac\uc758 \uc6d0\uce59). \uacf5\ub3d9\ub300\ub9ac\ub85c \ud558\ub824\uba74 \ubc95\ub960\uc758 \uaddc\uc815\uc774\ub098 \uc218\uad8c\ud589\uc704\uc5d0\uc11c \ubcc4\ub3c4\ub85c \uc815\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.a0w,B.b6A,null)
B.aRx=s(["\uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ub300\ub9ac\uc778\uc774 \ud544\uc694\ud558\ub2e4\uace0 \ud310\ub2e8\ud558\uba74 \ud56d\uc0c1 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a7l=s(["\uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.Mh=s(["\uc784\uc758\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c \uc81c\ud55c"],t.s)
B.bjQ=new A.a("gen_cl_agency_7","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc784\uc758\ub300\ub9ac\uc778\uc774 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.aRx,1,"\ubbfc\ubc95 \uc81c120\uc870\uc5d0 \ub530\ub77c \uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc784\uc758\ub300\ub9ac\ub294 \ubcf8\uc778\uc758 \uc2e0\ub8b0\uc5d0 \uae30\ucd08\ud558\ubbc0\ub85c \ubcf5\uc784\uad8c\uc774 \uc6d0\uce59\uc801\uc73c\ub85c \uc81c\ud55c\ub41c\ub2e4.",B.a7l,B.Mh,null)
B.aZr=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c\ub9cc \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\uc744 \ub54c\uc5d0\ub9cc \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aZW=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.adj=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c"],t.s)
B.bqM=new A.a("gen_cl_agency_8","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcf5\uc784\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aZr,1,"\ubbfc\ubc95 \uc81c122\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\ub2e4. \ubc95\uc815\ub300\ub9ac\ub294 \ubcf8\uc778\uc758 \uac1c\uc778\uc801 \uc2e0\ub8b0\uc640 \ubb34\uad00\ud558\uac8c \ubc95\ub960\uc758 \uaddc\uc815\uc73c\ub85c \ubc1c\uc0dd\ud558\ubbc0\ub85c, \uc784\uc758\ub300\ub9ac\uc640 \ub2ec\ub9ac \ubcf5\uc784\uad8c\uc774 \ud3ed\ub113\uac8c \uc778\uc815\ub418\ub294 \ub300\uc2e0 \uc120\uc784\uac10\ub3c5\uc5d0 \uad00\ud55c \ucc45\uc784\uc774 \ubb34\uac81\ub2e4.",B.aZW,B.adj,null)
B.Mx=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uc778\uc77c \ubfd0 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc740 \uc544\ub2c8\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\ub97c \uac00\uc9c4\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc758 \uc774\ud589\ubcf4\uc870\uc790\uc5d0 \ubd88\uacfc\ud558\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc758 \ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4"],t.s)
B.VR=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \ub300\ub9ac\ud558\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\uac00 \uc788\ub2e4"],t.s)
B.b4Q=s(["\ubcf5\ub300\ub9ac\uc778\uc758 \uc9c0\uc704"],t.s)
B.bjk=new A.a("gen_cl_agency_9","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubcf5\ub300\ub9ac\uc778\uc758 \ubc95\uc801 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Mx,1,"\ubbfc\ubc95 \uc81c123\uc870\uc5d0 \ub530\ub77c \ubcf5\ub300\ub9ac\uc778\uc740 \uadf8 \uad8c\ud55c \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \ub300\ub9ac\ud558\uba70, \ub300\ub9ac\uc778\uacfc \ub3d9\uc77c\ud55c \uad8c\ub9ac\uc758\ubb34\uac00 \uc788\ub2e4. \ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc774 \uc120\uc784\ud558\uc600\uc744 \ubfd0 \uc5b4\ub514\uae4c\uc9c0\ub098 \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\ubbc0\ub85c, \uadf8 \ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub41c\ub2e4.",B.VR,B.b4Q,null)
B.aC3=s(["\ub300\ub9ac\uad8c\uacfc \ubb34\uad00\ud558\uac8c \uc874\uc18d\ud55c\ub2e4","\uc6d0\uce59\uc801\uc73c\ub85c \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4","\ubcf8\uc778\uc758 \uc0c8\ub85c\uc6b4 \uc2b9\ub099\uc774 \uc788\uc5b4\uc57c \uc18c\uba78\ud55c\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc774 \uc0ac\uc784\ud574\uc57c\ub9cc \uc18c\uba78\ud55c\ub2e4"],t.s)
B.aMV=s(["\ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ubc1c\uc0dd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ubd80\uc885\uc131\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.Yi=s(["\ubcf5\ub300\ub9ac\uad8c\uc758 \ubd80\uc885\uc131"],t.s)
B.bve=new A.a("gen_cl_agency_10","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud55c \uacbd\uc6b0, \uadf8 \ub300\ub9ac\uc778\uc774 \uc120\uc784\ud55c \ubcf5\ub300\ub9ac\uc778\uc758 \ubcf5\ub300\ub9ac\uad8c\uc740?",B.aC3,1,"\ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ubc1c\uc0dd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ubd80\uc885\uc131\uc744 \uac00\uc9c4\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \uadf8\uc5d0 \uae30\ucd08\ud55c \ubcf5\ub300\ub9ac\uc778\uc758 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4.",B.aMV,B.Yi,null)
B.a6R=s(["\uc790\uae30\uacc4\uc57d\uc774\ub780 \ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud589\uc704\ub97c \ud558\uba74\uc11c \uc0c1\ub300\ubc29\uc73c\ub85c\uc11c \uc790\uae30 \uc790\uc2e0\uacfc \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\uc30d\ubc29\ub300\ub9ac\ub780 \ub3d9\uc77c\uc778\uc774 \ud558\ub098\uc758 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc744 \ub300\ub9ac\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub418\ub098, \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc788\uac70\ub098 \ub2e8\uc21c\ud55c \ucc44\ubb34\uc758 \uc774\ud589\uc778 \uacbd\uc6b0\uc5d0\ub294 \ud5c8\uc6a9\ub41c\ub2e4","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\ub294 \uc608\uc678 \uc5c6\uc774 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.b8_=s(["\uc774\ub97c \uc704\ubc18\ud55c \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c \ubb34\uad8c\ub300\ub9ac \ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ubbc0\ub85c"],t.s)
B.abD=s(["\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac"],t.s)
B.bfs=new A.a("gen_cl_agency_11","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a6R,3,'\ubbfc\ubc95 \uc81c124\uc870\ub294 \uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\ub97c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ud558\uba74\uc11c\ub3c4, \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc788\uac70\ub098 \ucc44\ubb34\uc758 \uc774\ud589\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ud55c\ub2e4. \uc774\ub97c \uc704\ubc18\ud55c \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c \ubb34\uad8c\ub300\ub9ac \ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ubbc0\ub85c, "\uc608\uc678 \uc5c6\uc774 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.b8_,B.abD,null)
B.adA=s(["\ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc774\ubbc0\ub85c \ud56d\uc0c1 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \ubc30\uc784\uc801 \uc758\ub3c4\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\ub358 \uacbd\uc6b0\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4","\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc740 \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\uba70 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc77c \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uacfc\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.arP=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \uc9c4\uc758(\ubc30\uc784\uc801 \uc758\ub3c4)\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294","\ubcf8\uc778\uc5d0\uac8c \uadf8 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.a9Y=s(["\ub300\ub9ac\uad8c \ub0a8\uc6a9"],t.s)
B.bs6=new A.a("gen_cl_agency_12","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ud589\uc704\ud558\uc600\uc73c\ub098 \uc624\ub85c\uc9c0 \uc790\uae30 \ub610\ub294 \uc81c3\uc790\uc758 \uc774\uc775\uc744 \ub3c4\ubaa8\ud560 \ubaa9\uc801\uc73c\ub85c \ub300\ub9ac\ud589\uc704\ub97c \ud55c \uacbd\uc6b0(\ub300\ub9ac\uad8c \ub0a8\uc6a9)\uc758 \ud6a8\uacfc\ub294?",B.adA,1,"\ub300\ub9ac\uad8c \ub0a8\uc6a9\uc758 \uacbd\uc6b0 \ud615\uc2dd\uc801\uc73c\ub85c\ub294 \ub300\ub9ac\uad8c \ubc94\uc704 \ub0b4\uc758 \ud589\uc704\uc774\uc9c0\ub9cc, \ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \uc9c4\uc758(\ubc30\uc784\uc801 \uc758\ub3c4)\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ube44\uc9c4\uc758\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc81c107\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub97c \uc720\ucd94\uc801\uc6a9\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \uadf8 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.",B.arP,B.a9Y,null)
