B.bwc=new A.a("gen_cl_intent_17","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \ub9e4\ub3c4\uc778\uc774 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \ub9e4\uc218\uc778\uc774 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.a_G,1,"\ud310\ub840\ub294 \ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc758 \ud558\uc790\ub85c \uc778\ud558\uc5ec \ub9e4\ub3c4\uc778\uc774 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \ub9e4\uc218\uc778\uc774 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\ub294 \uac83\uc774 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc544 \uc591 \uc81c\ub3c4\uc758 \uacbd\ud569\uc744 \uc778\uc815\ud55c\ub2e4.",B.auE,B.RG,null)
B.a3I=s(["\ud45c\uc758\uc790\uc758 \uc9c1\uc5c5, \ud589\uc704\uc758 \uc885\ub958\xb7\ubaa9\uc801 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \ubcf4\ud1b5 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ud604\uc800\ud788 \uacb0\uc5ec\ud55c \uac83","\ud45c\uc758\uc790\uac00 \uc870\uae08\uc774\ub77c\ub3c4 \ubd80\uc8fc\uc758\ud588\ub358 \ubaa8\ub4e0 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uc774 \ubd80\uc8fc\uc758\ud588\ub358 \uacbd\uc6b0","\ud45c\uc758\uc790\uac00 \uace0\uc758\ub85c \ucc29\uc624\ub97c \uc720\ubc1c\ud55c \uacbd\uc6b0"],t.s)
B.b6c=s(["\ud45c\uc758\uc790\uc758 \uc9c1\uc5c5, \ud589\uc704\uc758 \uc885\ub958\xb7\ubaa9\uc801 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \ubcfc \ub54c \ubcf4\ud1b5 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ud604\uc800\ud788 \uacb0\uc5ec\ud55c \uac83\uc744 \ub9d0\ud55c\ub2e4"],t.s)
B.Qf=s(["\uc911\ub300\ud55c \uacfc\uc2e4\uc758 \uc758\ubbf8"],t.s)
B.bv7=new A.a("gen_cl_intent_18","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,'"\uc911\ub300\ud55c \uacfc\uc2e4"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a3I,0,"\ud310\ub840\uc0c1 \uc911\ub300\ud55c \uacfc\uc2e4\uc774\ub780 \ud45c\uc758\uc790\uc758 \uc9c1\uc5c5, \ud589\uc704\uc758 \uc885\ub958\xb7\ubaa9\uc801 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \ubcfc \ub54c \ubcf4\ud1b5 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ud604\uc800\ud788 \uacb0\uc5ec\ud55c \uac83\uc744 \ub9d0\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uacbd\uacfc\uc2e4\uacfc \uad6c\ubcc4\ub418\ub294 \uac1c\ub150\uc774\ub2e4.",B.b6c,B.Qf,null)
B.a94=s(["\ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\uc73c\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uace0 \uc774\uc6a9\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc2e0\uc758\uce59\uc0c1 \ucde8\uc18c\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub2e4","\uc774 \uacbd\uc6b0 \uc0c1\ub300\ubc29\ub9cc \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc774 \uacbd\uc6b0 \ucc29\uc624\ucde8\uc18c\uac00 \uc544\ub2c8\ub77c \uc0ac\uae30\ucde8\uc18c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
