B.bCA=new A.a("gen_cl_intent_19","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud55c \uacbd\uc6b0, \ucc29\uc624\ucde8\uc18c\uac00 \ud5c8\uc6a9\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.a94,1,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\ub77c\ub3c4, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uba74\uc11c \uc774\ub97c \uc774\uc6a9\ud55c \ub54c\uc5d0\ub294 \uc2e0\uc758\uce59\uc5d0 \ubc18\ud558\ubbc0\ub85c \ud45c\uc758\uc790\uc758 \ucc29\uc624\ucde8\uc18c\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aSk,B.aNT,null)
B.aEu=s(["\uae30\ub9dd\ud589\uc704\uc758 \uc874\uc7ac","\uae30\ub9dd\ud589\uc704\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc84c\uc744 \uac83"],t.s)
