B.Y6=s(["\uc0ac\uae30\ub098 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.akc=s(["\uc0ac\uae30\xb7\uac15\ubc15\ucde8\uc18c\uc640 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.bgI=new A.a("gen_cl_intent_23","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \ub204\uad6c\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ub294\uac00?",B.aa6,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \uc0ac\uae30\ub098 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ucc29\uc624\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uac70\ub798\uc758 \uc548\uc804\uc744 \uc704\ud55c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774\ub2e4.",B.Y6,B.akc,null)
B.aTv=s(["\ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub3c4 \uac00\ub2a5\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub9cc \uac00\ub2a5\ud558\uace0 \ucde8\uc18c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \ub3d9\uc2dc\uc5d0 \ud560 \uc218 \uc5c6\uace0 \uc591\uc790\ud0dd\uc77c\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.a_m=s(["\uae30\ub9dd\ud589\uc704\uac00 \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \ud45c\uc758\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.agf=s(["\uc0ac\uae30\ucde8\uc18c\uc640 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.bjz=new A.a("gen_cl_intent_24","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ubcc4\ub3c4\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aTv,1,"\ud310\ub840\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c, \uae30\ub9dd\ud589\uc704\uac00 \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \ud45c\uc758\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.a_m,B.agf,null)
B.arB=s(["\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb35\ube44\ub294 \uae30\ub9dd\ud589\uc704\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2e0\uc758\uce59\uc0c1 \uace0\uc9c0\uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubb35\ube44\ub3c4 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc2a4\uc2a4\ub85c \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc774\uc0c1 \ubb35\ube44\ub294 \ud56d\uc0c1 \uc815\ub2f9\ud558\ub2e4","\ubb35\ube44\ub294 \uacc4\uc57d \uccb4\uacb0 \ud6c4\uc5d0\ub9cc \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.a3N=s(["\uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0","\uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b60=s(["\ubb35\ube44\uc640 \uae30\ub9dd\ud589\uc704"],t.s)
B.bix=new A.a("gen_cl_intent_25","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uacc4\uc57d \uccb4\uacb0 \uc2dc \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \uc0ac\uc2e4\uc744 \uc54c\uba74\uc11c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\uc740 \uac83(\ubb35\ube44)\uc774 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub294?",B.arB,1,"\ud310\ub840\ub294 \uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0, \uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.a3N,B.b60,null)
B.RV=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucde8\uc18c\uad8c\uc740 \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud558\ub294 \ud55c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.a6Z=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70"],t.s)
B.b2l=s(["\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c\ucc99\uae30\uac04)"],t.s)
B.bFV=new A.a("gen_cl_intent_26","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624, \uc0ac\uae30, \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.RV,0,"\ubbfc\ubc95 \uc81c146\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70, \uc774 \uae30\uac04\uc740 \uc81c\ucc99\uae30\uac04\uc73c\ub85c\uc11c \uadf8 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4.",B.a6Z,B.b2l,null)
B.ak1=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04\uc5d0 \ubb34\ud6a8\uc774\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8\uc774\ub2e4"],t.s)
B.ayu=s(["\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4"],t.s)
B.Me=s(["\uc758\uc0ac\ud45c\uc2dc \ud558\uc790 \uc720\ud615 \ube44\uad50"],t.s)
B.bA0=new A.a("gen_cl_intent_27","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \uc6d0\uce59\uc801 \ud6a8\uacfc\ub97c \ube44\uad50\ud55c \uac83\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ak1,3,'\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8(\uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04 \ubb34\ud6a8, \ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4. \uc0ac\uae30\xb7\uac15\ubc15\uc740 \ucde8\uc18c\uc0ac\uc720\uc77c \ubfd0 \ub2f9\uc5f0\ubb34\ud6a8\ub294 \uc544\ub2c8\ubbc0\ub85c(\ub2e4\ub9cc \uac15\ubc15\uc774 \uadf9\uc2ec\ud558\uc5ec \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ud55c \uacbd\uc6b0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), "\ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.ayu,B.Me,null)
B.aDf=s(["\uadf8\ub7ec\ud55c \ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4","\uc774\ub7ec\ud55c \ud2b9\uc57d\uc740 \ud56d\uc0c1 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.a6s=s(["\ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4"],t.s)
B.ae4=s(["\ucc29\uc624\ucde8\uc18c\uad8c \ubc30\uc81c\ud2b9\uc57d"],t.s)
B.bq9=new A.a("gen_cl_intent_28","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub2f9\uc0ac\uc790\uac00 \ubbf8\ub9ac \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ubc30\uc81c\ud558\uae30\ub85c \ud558\ub294 \ud2b9\uc57d\uc758 \ud6a8\ub825\uc740?",B.aDf,1,"\ucc29\uc624\ucde8\uc18c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c109\uc870\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub418\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.",B.a6s,B.ae4,null)
B.WE=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uac00 \uc694\uad6c\ub41c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc5c6\uc73c\ubbc0\ub85c \uadf8 \uc778\uc2dd \uc5ec\ubd80\ub97c \uc694\uad6c\ud560 \uc218 \uc5c6\uc5b4 \ud45c\uc758\uc790\ub294 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc774 \uacbd\uc6b0 \ucde8\uc18c \uc790\uccb4\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ub41c \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aA5=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aHN=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc640 \uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.beS=new A.a("gen_cl_intent_29","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704(\uc608: \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704)\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0 \ucde8\uc18c \uc694\uac74\uc740?",B.WE,1,'\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc758 "\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0"\ub77c\ub294 \uc81c\ud55c\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc804\uc81c\ub85c \ud55c \uac83\uc774\ubbc0\ub85c, \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.',B.aA5,B.aHN,null)
B.aUV=s(["\ud45c\uc758\uc790\uac00 \uc758\uc0ac\ud45c\uc2dc\ub97c \ubc1c\uc1a1\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ubc1c\uc2e0\uc8fc\uc758)","\uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)","\uc0c1\ub300\ubc29\uc774 \uadf8 \ub0b4\uc6a9\uc744 \uc2e4\uc81c\ub85c \uc77d\uc740 \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uc758\uc0ac\ud45c\uc2dc\ub294 \uc791\uc131\ud55c \ub0a0\uc9dc\ub97c \uae30\uc900\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.aQf=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)"],t.s)
B.b3u=s(["\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30"],t.s)
B.bvs=new A.a("gen_cl_intent_30","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30(\uc81c111\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUV,1,"\ubbfc\ubc95 \uc81c111\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758). \ub610\ud55c \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud45c\uc758\uc790\uac00 \ud1b5\uc9c0\ub97c \ubc1c\uc1a1\ud55c \ud6c4 \uc0ac\ub9dd\ud558\uac70\ub098 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub418\uc5b4\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4.",B.aQf,B.b3u,null)
B.aeB=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ubd88\uade0\ud615\uc774 \uc870\uae08\uc774\ub77c\ub3c4 \uc788\uc73c\uba74 \uc131\ub9bd\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\uc77c \uac83","\uacc4\uc57d\uc11c\uac00 \uc791\uc131\ub418\uc9c0 \uc54a\uc740 \uad6c\ub450 \uacc4\uc57d\uc77c \uac83","\uacc4\uc57d\uae08\uc774 \uc9c0\uae09\ub418\uc9c0 \uc54a\uc558\uc744 \uac83"],t.s)
B.ah6=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
