B.bGO=new A.a("gen_cl_unfair_3","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc778 "\uacbd\uc194"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aAf,0,"\uacbd\uc194\uc774\ub780 \uc758\uc0ac\ub97c \uacb0\uc815\ud568\uc5d0 \uc788\uc5b4 \ubcf4\ud1b5\uc778\uc5d0\uac8c \uc694\uad6c\ub418\ub294 \uc815\ub3c4\uc758 \uc2e0\uc911\ud55c \uace0\ub824\ub97c \ud558\uc9c0 \uc544\ub2c8\ud55c \uc2ec\ub9ac\uc0c1\ud0dc\ub97c \ub9d0\ud55c\ub2e4. \uc774\ub294 \ubb34\uacbd\ud5d8\uacfc \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ub3c5\ub9bd\uc801 \uc694\uac74\uc774\ub2e4.",B.Qm,B.Qr,null)
B.ZJ=s(["\ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0\uc11c\uc758 \uacbd\ud5d8\ubd80\uc871\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uac70\ub798\uc77c\ubc18\uc5d0 \ub300\ud55c \uacbd\ud5d8\ubd80\uc871\uc744 \uc758\ubbf8\ud558\uba70 \ud2b9\uc815 \ubd84\uc57c\uc5d0 \uad6d\ud55c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud559\ub825\uc774 \ub0ae\uc740 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc5f0\ub839\uc774 \uc5b4\ub9b0 \uac83\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
