B.bmX=new A.a("gen_cl_unfair_4","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc778 "\ubb34\uacbd\ud5d8"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.ZJ,1,"\ud310\ub840\uc0c1 \ubb34\uacbd\ud5d8\uc774\ub780 \uc5b4\ub290 \ud2b9\uc815\uc601\uc5ed\uc5d0\uc11c\uc758 \uacbd\ud5d8\ubd80\uc871\uc774 \uc544\ub2c8\ub77c \uac70\ub798\uc77c\ubc18\uc5d0 \ub300\ud55c \uacbd\ud5d8\ubd80\uc871\uc744 \uc758\ubbf8\ud55c\ub2e4. \uc989 \ud574\ub2f9 \uac70\ub798 \ubd84\uc57c\uc5d0 \ub300\ud55c \uc9c0\uc2dd\uc774 \uc788\ub354\ub77c\ub3c4 \uac70\ub798 \uacbd\ud5d8 \uc804\ubc18\uc774 \ubd80\uc871\ud558\uba74 \ubb34\uacbd\ud5d8 \uc694\uac74\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.a5G,B.Wl,null)
B.aWt=s(["\uc138 \uac00\uc9c0 \uc694\uac74\uc744 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\uc138 \uac00\uc9c0 \uc911 \uc5b4\ub290 \ud558\ub098\ub9cc \uac16\ucd94\uc5b4\ub3c4 \ucda9\uc871\ub418\ub294 \ud0dd\uc77c\uc801 \uc694\uac74\uc774\ub2e4","\uad81\ubc15\ub9cc \uc788\uc73c\uba74 \ub098\uba38\uc9c0\ub294 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc194\uacfc \ubb34\uacbd\ud5d8\ub9cc \uc788\uc73c\uba74 \uad81\ubc15\uc740 \uc694\uad6c\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aId=s(["\uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \uadf8 \ubaa8\ub450\uac00 \uad6c\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\uc911 \uc77c\ubd80\ub9cc \uac16\ucd94\uc5b4\uc838\ub3c4 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
