B.bHg=new A.a("gen_cl_unfair_5","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aWt,1,"\ud310\ub840\ub294 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \uadf8 \ubaa8\ub450\uac00 \uad6c\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\uc911 \uc77c\ubd80\ub9cc \uac16\ucd94\uc5b4\uc838\ub3c4 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \ud0dd\uc77c\uc801 \uc694\uac74\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aId,B.MJ,null)
B.N_=s(["\ubc95\ub960\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc774\ud589\uc774 \uc644\ub8cc\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubd84\uc7c1\uc774 \uc18c\uc1a1\uc73c\ub85c \uc81c\uae30\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubaa9\uc801\ubb3c\uc758 \uc2dc\uac00\uac00 \uac00\uc7a5 \ub192\uc558\ub358 \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aEQ=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
