B.bDx=new A.a("gen_cl_unfair_6","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 "\ud604\uc800\ud55c \ubd88\uade0\ud615" \uc5ec\ubd80\ub294 \uc5b4\ub290 \uc2dc\uc810\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?',B.N_,0,"\ud310\ub840\ub294 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ud6c4\uc758 \uac00\uaca9 \ubcc0\ub3d9\uc740 \ud310\ub2e8\uc758 \uae30\ucd08\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aEQ,B.aZw,null)
B.aqw=s(["\uc0c1\ub300\ubc29\uc758 \uad81\ubc15 \ub4f1 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc54c\uace0 \uc788\uc5c8\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac\uae4c\uc9c0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uc5d0\uac8c \ud615\uc0ac\uc0c1 \uace0\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uac00 \uacc4\uc57d\uc11c\ub97c \uc9c1\uc811 \uc791\uc131\ud558\uc600\uc5b4\uc57c \ud55c\ub2e4"],t.s)
