B.bvm=new A.a("gen_cl_unfair_15","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c103\uc870(\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704)\uc640 \uc81c104\uc870(\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704)\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \ud1b5\uc124\uc758 \ud0dc\ub3c4\ub294?",B.aOu,1,"\ud1b5\uc124\uc740 \uc81c104\uc870\ub97c \uc81c103\uc870\uac00 \uc815\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \uc911, \ub2f9\uc0ac\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud55c \ud3ed\ub9ac\ud589\uc704\ub97c \ubcc4\ub3c4\ub85c \uc720\ud615\ud654\ud558\uc5ec \uaddc\uc815\ud55c \ud2b9\ubcc4\uaddc\uc815\uc73c\ub85c \uc774\ud574\ud55c\ub2e4.",B.aqN,B.oN,null)
B.aa7=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \uac1d\uad00\uc801 \uac00\uce58\ub97c \ube44\uad50\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4","\ub2f9\uc0ac\uc790\uc758 \uc8fc\uad00\uc801 \ub9cc\uc871\ub3c4\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d\uc11c\uc5d0 \uae30\uc7ac\ub41c \uae08\uc561\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d \uccb4\uacb0 \uc7a5\uc18c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
