B.bBG=new A.a("gen_cl_unfair_18","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd80\ub3d9\uc0b0\uc744 \uc2dc\uac00\uc758 \uc808\ubc18 \uc774\ud558 \uac00\uaca9\uc73c\ub85c \ub9e4\ub3c4\ud558\uc600\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aUv,1,"\ud310\ub840\ub294 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc774\ub77c\ub294 \uc8fc\uad00\uc801 \uc694\uac74\uacfc \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\ud589\uc704\uc5d0 \ub300\ud55c \uc774\uc6a9\uc758\uc0ac\uae4c\uc9c0 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc838\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.a7p,B.aT8,null)
