B.btV=new A.a("gen_cl_cond_4","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ub2f9\uc0ac\uc790\uac00 \uc870\uac74\uc131\ucde8\uc758 \ud6a8\ub825\uc744 \uadf8 \uc131\ucde8 \uc804\uc73c\ub85c \uc18c\uae09\ud558\uac8c \ud560 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.aeA,1,"\ubbfc\ubc95 \uc81c147\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790\uac00 \uc870\uac74\uc131\ucde8\uc758 \ud6a8\ub825\uc744 \uadf8 \uc131\ucde8 \uc804\uc5d0 \uc18c\uae09\ud558\uac8c \ud560 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\uc5d0 \uc758\ud55c\ub2e4. \uc989 \uc6d0\uce59\uc801 \uc7a5\ub798\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \uc18c\uae09\ud6a8\ub85c \ubc14\uafc0 \uc218 \uc788\ub2e4.",B.aBJ,B.a83,null)
B.aqr=s(["\uc870\uac74\ubd80 \uad8c\ub9ac\ub294 \ubcf4\ud638\ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc544\ubb34\ub7f0 \ucc45\uc784\uc774 \uc5c6\ub2e4","\uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\ud55c \ub3d9\uc548\uc5d0\ub3c4 \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud558\uba74 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4","\uc774 \uacbd\uc6b0 \uc870\uac74 \uc790\uccb4\uac00 \ubb34\ud6a8\ub85c \ub41c\ub2e4","\uc774 \uacbd\uc6b0 \ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \ucde8\uc18c\ub41c\ub2e4"],t.s)
B.b2o=s(["\uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\ud55c \ub3d9\uc548\uc5d0 \uc870\uac74\uc774 \uc131\ucde8\ub41c \uacbd\uc6b0\uc5d0 \uc0c1\ub300\ubc29\uc774 \uc5bb\uc744 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
