B.bBr=new A.a("gen_cl_cond_5","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\uc778 \ub3d9\uc548 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \uce68\ud574\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc(\uc81c148\uc870)\ub85c \uc633\uc740 \uac83\uc740?",B.aqr,1,"\ubbfc\ubc95 \uc81c148\uc870\uc5d0 \ub530\ub77c \uc870\uac74 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\ub294 \uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\ud55c \ub3d9\uc548\uc5d0 \uc870\uac74\uc774 \uc131\ucde8\ub41c \uacbd\uc6b0\uc5d0 \uc0c1\ub300\ubc29\uc774 \uc5bb\uc744 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4. \uc870\uac74\ubd80 \uad8c\ub9ac \uc5ed\uc2dc \uc77c\uc885\uc758 \uae30\ub300\uad8c\uc73c\ub85c\uc11c \ubcf4\ud638\ub41c\ub2e4.",B.b2o,B.WS,null)
B.aAb=s(["\uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud55c \ucc98\ubd84","\uc0c1\uc18d","\ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud558\ub294 \ud589\uc704","\uc870\uac74\ubd80 \uad8c\ub9ac \uc790\uccb4\ub97c \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uc77c\ubc29\uc801 \ud3ec\uae30"],t.s)
B.aUq=s(["\uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\ud55c \uad8c\ub9ac\uc758\ubb34\ub294 \uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ucc98\ubd84, \uc0c1\uc18d, \ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.T4=s(["\uc870\uac74\ubd80 \uad8c\ub9ac\uc758 \ucc98\ubd84 \ub4f1"],t.s)
B.buT=new A.a("gen_cl_cond_6","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\uc778 \uad8c\ub9ac\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aAb,3,"\ubbfc\ubc95 \uc81c149\uc870\uc5d0 \ub530\ub77c \uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\ud55c \uad8c\ub9ac\uc758\ubb34\ub294 \uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ucc98\ubd84, \uc0c1\uc18d, \ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc870\uac74\ubd80 \uad8c\ub9ac \uc790\uccb4\ub97c \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uba74\uc11c \uc77c\ubc29\uc801\uc73c\ub85c \uc18c\uae09 \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc740 \uc774 \uc870\ubb38\uc774 \ud5c8\uc6a9\ud558\ub294 \ud589\uc704\uac00 \uc544\ub2c8\ub2e4.",B.aUq,B.T4,null)
B.Zp=s(["\uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \uc544\ubb34\ub7f0 \uad8c\ub9ac\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc870\uac74 \uc131\ucde8\ub97c \ubc29\ud574\ud55c \uc790\uc5d0\uac8c \ud615\uc0ac\ucc45\uc784\ub9cc \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.aw1=s(["\uc870\uac74\uc758 \uc131\ucde8\ub85c \uc778\ud558\uc5ec \ubd88\uc774\uc775\uc744 \ubc1b\uc744 \ub2f9\uc0ac\uc790\uac00 \uc2e0\uc758\uc131\uc2e4\uc5d0 \ubc18\ud558\uc5ec \uc870\uac74\uc758 \uc131\ucde8\ub97c \ubc29\ud574\ud55c \ub54c\uc5d0\ub294 \uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aH9=s(["\uc870\uac74\uc131\ucde8\uc758 \ubc29\ud574\uc640 \uc758\uc81c"],t.s)
B.biT=new A.a("gen_cl_cond_7","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc758 \uc131\ucde8\ub85c \ubd88\uc774\uc775\uc744 \ubc1b\uc744 \uc790\uac00 \uc2e0\uc758\uc131\uc2e4\uc5d0 \ubc18\ud558\uc5ec \uc870\uac74\uc758 \uc131\ucde8\ub97c \ubc29\ud574\ud55c \uacbd\uc6b0(\uc81c150\uc870 \uc81c1\ud56d)\uc758 \ud6a8\uacfc\ub294?",B.Zp,0,"\ubbfc\ubc95 \uc81c150\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc870\uac74\uc758 \uc131\ucde8\ub85c \uc778\ud558\uc5ec \ubd88\uc774\uc775\uc744 \ubc1b\uc744 \ub2f9\uc0ac\uc790\uac00 \uc2e0\uc758\uc131\uc2e4\uc5d0 \ubc18\ud558\uc5ec \uc870\uac74\uc758 \uc131\ucde8\ub97c \ubc29\ud574\ud55c \ub54c\uc5d0\ub294 \uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.aw1,B.aH9,null)
B.a1D=s(["\uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud558\uc9c0 \uc544\ub2c8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc870\uac74\uc744 \uc131\ucde8\uc2dc\ud0a8 \uc790\ub294 \uadf8 \uc774\uc775\uc744 \uadf8\ub300\ub85c \ucde8\ub4dd\ud55c\ub2e4","\uc774 \uacbd\uc6b0 \ubc95\ub960\ud589\uc704\ub294 \uc790\ub3d9\uc73c\ub85c \ucde8\uc18c\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uc870\uac74 \uc790\uccb4\uac00 \ucc98\uc74c\ubd80\ud130 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.aJ3=s(["\uc870\uac74\uc758 \uc131\ucde8\ub85c \uc778\ud558\uc5ec \uc774\uc775\uc744 \ubc1b\uc744 \ub2f9\uc0ac\uc790\uac00 \uc2e0\uc758\uc131\uc2e4\uc5d0 \ubc18\ud558\uc5ec \uc870\uac74\uc744 \uc131\ucde8\uc2dc\ud0a8 \ub54c\uc5d0\ub294 \uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud558\uc9c0 \uc544\ub2c8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
