B.aYW=s(["\uadf8 \uc870\uac74\ub9cc \ubb34\ud6a8\uc774\uace0 \ub098\uba38\uc9c0 \ubc95\ub960\ud589\uc704\ub294 \uc720\ud6a8\ud558\ub2e4","\uc870\uac74\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubc95\ub960\ud589\uc704 \uc804\ubd80\uac00 \ubb34\ud6a8\ub85c \ub41c\ub2e4","\uc870\uac74\uc774 \ubb34\ud6a8\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\ub85c\uc11c \uc720\ud6a8\ud558\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc120\uc758\uc774\uba74 \ubc95\ub960\ud589\uc704\uac00 \uc720\ud6a8\ud558\uac8c \ub41c\ub2e4"],t.s)
B.a5q=s(["\uc870\uac74\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud55c \uac83\uc778 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
