B.be5=new A.a("gen_cl_cond_9","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud55c \uac83\uc778 \uacbd\uc6b0(\ubd88\ubc95\uc870\uac74, \uc81c151\uc870 \uc81c1\ud56d)\uc758 \ud6a8\uacfc\ub294?",B.aYW,1,"\ubbfc\ubc95 \uc81c151\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud55c \uac83\uc778 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4. \uc870\uac74\ub9cc \ubd84\ub9ac\ud558\uc5ec \ubb34\ud6a8\ub85c \ud558\uc9c0 \uc54a\uace0 \ubc95\ub960\ud589\uc704 \uc804\uccb4\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc774\ub2e4.",B.a5q,B.a2B,null)
B.KD=s(["\uc815\uc9c0\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uac00 \ub418\uace0, \ud574\uc81c\uc870\uac74\uc774\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ub41c\ub2e4","\uc815\uc9c0\uc870\uac74\uc774\ub4e0 \ud574\uc81c\uc870\uac74\uc774\ub4e0 \ud56d\uc0c1 \ubb34\ud6a8\ub85c \ub41c\ub2e4","\uc815\uc9c0\uc870\uac74\uc774\uba74 \ubb34\ud6a8, \ud574\uc81c\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uac00 \ub41c\ub2e4","\uae30\uc131\uc870\uac74\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\ub960\ud589\uc704\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.S3=s(["\uc870\uac74\uc774 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc2dc \uc774\ubbf8 \uc131\ucde8\ud55c \uac83\uc778 \uacbd\uc6b0\uc5d0\ub294, \uadf8 \uc870\uac74\uc774 \uc815\uc9c0\uc870\uac74\uc774\uba74 \uc870\uac74 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\ub85c \ud558\uace0 \ud574\uc81c\uc870\uac74\uc774\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
B.b2G=s(["\uae30\uc131\uc870\uac74"],t.s)
