B.bkQ=new A.a("gen_cl_revoc_25","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,'\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uae30\uc0b0\uc810\uc778 "\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc758 \uc758\ubbf8\ub85c \uc633\uc740 \uac83\uc740?',B.aWd,0,'"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc774\ub780 \ucde8\uc18c\uc758 \uc6d0\uc778(\uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1)\uc774 \uc885\ub8cc\ub418\uc5b4 \ucde8\uc18c\uad8c\uc790\uac00 \uc720\ud6a8\ud558\uac8c \ucd94\uc778\ud560 \uc218 \uc788\uac8c \ub41c \ub0a0\uc744 \uc758\ubbf8\ud55c\ub2e4. \uc608\ucee8\ub300 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc131\ub144\uc774 \ub41c \ub0a0, \uc0ac\uae30\xb7\uac15\ubc15 \uc0c1\ud0dc\uc5d0\uc11c \ubc97\uc5b4\ub09c \ub0a0 \ub4f1\uc774 \uc774\uc5d0 \ud574\ub2f9\ud55c\ub2e4.',B.abH,B.aSJ,null)
B.aCN=s(["\ucde8\uc18c\uac00 \uc788\uae30 \uc804\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \uc720\ud6a8\ud558\ubbc0\ub85c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\uc5b8\uc81c\ub098 \uc81c3\uc790\uc758 \ucde8\ub4dd\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc81c3\uc790\ub294 \ud56d\uc0c1 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ucc98\ubd84 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.a7v=s(["\ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8"],t.s)
B.b22=s(["\ucde8\uc18c \uc804 \ucc98\ubd84\ud589\uc704\uc758 \ud6a8\ub825"],t.s)
B.byU=new A.a("gen_cl_revoc_26","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c \uadf8 \ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\ubb3c\uc774 \uc81c3\uc790\uc5d0\uac8c \ucc98\ubd84\ub41c \uacbd\uc6b0 \uc6d0\uce59\uc801\uc778 \uacb0\uacfc\ub294?",B.aCN,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4. \uc774\ud6c4 \ucde8\uc18c\uac00 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub418\uc9c0\ub9cc, \uac70\ub798 \uc548\uc804\uc744 \uc704\ud574 \ubcc4\ub3c4\ub85c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uac00 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0(\uc608: \uc0ac\uae30\xb7\uac15\ubc15\xb7\ucc29\uc624\uc758 \uacbd\uc6b0 \uc81c3\uc790 \ub300\ud56d\ubd88\uac00 \uaddc\uc815)\uac00 \uc788\ub2e4.",B.a7v,B.b22,null)
B.Vy=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4","\uc774\uc758\ub97c \ubcf4\ub958\ud55c \uc774\ud589","\uac15\uc81c\uc9d1\ud589\uc758 \uc815\uc9c0","\ucde8\uc18c\uad8c\uc758 \ud3ec\uae30 \uc120\uc5b8"],t.s)
B.IM=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4"],t.s)
