B.beI=new A.a("gen_cl_revoc_27","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\ub97c \uc81c3\uc790\uc5d0\uac8c \uc591\ub3c4\ud55c \uacbd\uc6b0, \uc774\ub294 \uc5b4\ub5a4 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uac00?",B.Vy,0,"\ubbfc\ubc95 \uc81c145\uc870 \uc81c5\ud638\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4. \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc774\ub7ec\ud55c \ucc98\ubd84\ud589\uc704\ub97c \ud558\uc600\ub2e4\uba74, \uadf8 \ubc95\ub960\ud589\uc704\ub97c \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \uc804\uc81c\ud558\uace0 \ud589\ub3d9\ud55c \uac83\uc774\ubbc0\ub85c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \uac04\uc8fc\ub41c\ub2e4.",B.IM,B.asy,null)
B.aIQ=s(["\ucde8\uc18c\uc6d0\uc778\uc774 \uc5ec\ub7ec \uac1c \uacbd\ud569\ud560 \uc218 \uc788\ub2e4(\uc608: \uc81c\ud55c\ub2a5\ub825\uacfc \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0)","\ucde8\uc18c\uc6d0\uc778\uc740 \ubc18\ub4dc\uc2dc \ud55c \uac00\uc9c0\ub9cc \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc774 \uacbd\ud569\ud558\uba74 \ubc95\ub960\ud589\uc704\ub294 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc758 \uacbd\ud569\uc740 \ubbfc\ubc95\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
