B.bDw=new A.a("gen_cl_void_4","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ub300\ud45c\uc801 \ubc1c\uc0dd \uc6d0\uc778\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.aPJ,3,'\uac15\ud589\ubc95\uaddc \uc704\ubc18, \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870), \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870), \uc6d0\uc2dc\uc801 \ubd88\ub2a5, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc758 \ub2f9\uc0ac\uc790 \uac04 \ud6a8\ub825\uc740 \ubaa8\ub450 "\ubb34\ud6a8"\uc758 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4. \ubc18\uba74 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.',B.aCL,B.acN,null)
B.avK=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub098, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub3c4 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4","\ub204\uad6c\uc5d0\uac8c\ub3c4 \ubb34\ud6a8\ub85c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\ub9cc \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b0X=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub098, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4"],t.s)
