B.bu0=new A.a("gen_cl_void_6","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\ub85c \ubb34\ud6a8\uac00 \ub41c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNG,0,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\ub098 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\ub85c \uc778\ud55c \ubb34\ud6a8\ub294 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc0c1\ub300\uc801 \ubb34\ud6a8\uc778 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc640 \uacb0\uc815\uc801\uc73c\ub85c \ub2e4\ub978 \uc810\uc774\ub2e4. \ub610\ud55c \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ubbc0\ub85c \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.axG,B.aKx,null)
B.aHL=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc774\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc804\ubd80\uac00 \ubb34\ud6a8\uc774\ub2e4","\uc77c\ubd80\uac00 \ubb34\ud6a8\uc774\uba74 \ud56d\uc0c1 \ub098\uba38\uc9c0 \ubd80\ubd84\ub3c4 \ud568\uaed8 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8\ub294 \uc5b8\uc81c\ub098 \uc804\ubd80\ubb34\ud6a8\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8 \uaddc\uc815\uc740 \uac15\ud589\uaddc\uc815\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.LK=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
B.aF4=s(["\uc77c\ubd80\ubb34\ud6a8\uc758 \uc6d0\uce59(\uc81c137\uc870)"],t.s)
B.bif=new A.a("gen_cl_void_7","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aHL,0,"\ubbfc\ubc95 \uc81c137\uc870\ub294 \ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uc6d0\uce59\uc744 \uc815\ud558\uba74\uc11c\ub3c4, \uadf8 \ubb34\ud6a8 \ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc608\uc678\ub97c \ud568\uaed8 \uaddc\uc815\ud55c\ub2e4.",B.LK,B.aF4,null)
B.Sx=s([u.Fy,"\ubb34\ud6a8 \ubd80\ubd84\uc758 \ube44\uc911\uc774 \uc804\uccb4\uc758 \uc808\ubc18 \ubbf8\ub9cc\uc774\uc5b4\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc758 \ubcc4\ub3c4 \ud5c8\uac00\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ub3d9\uc758\ub9cc \uc788\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4"],t.s)
