B.bBh=new A.a("gen_cl_void_9","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6i,0,"\ubbfc\ubc95 \uc81c138\uc870\ub294 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0, \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub354\ub77c\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\ub3c4\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658). \uc608\ucee8\ub300 \ube44\ubc00\uc99d\uc11c\uc5d0 \uc758\ud55c \uc720\uc5b8\uc73c\ub85c\uc11c \ubb34\ud6a8\uc774\ub098 \uc790\ud544\uc99d\uc11c \uc720\uc5b8\uc758 \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0\uac00 \ub300\ud45c\uc801\uc774\ub2e4.",B.amR,B.Td,null)
B.aJx=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ucd94\uc778\ud558\uc5ec\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ucd94\uc778\ud558\uba74 \ucc98\uc74c\ubd80\ud130 \uc720\ud6a8\ud588\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud55c\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc740 \ubc95\ub960\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \uac1c\ub150\uc774\ub2e4","\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \ubaa8\ub974\uace0 \ucd94\uc778\ud558\uba74 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c \ubcf8\ub2e4"],t.s)
