B.bjd=new A.a("gen_cl_void_10","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJx,0,'\ubbfc\ubc95 \uc81c139\uc870 \ubcf8\ubb38\uc740 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub2e8\uc11c\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 "\uc54c\uace0" \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778\uc774 \uc6d0\ub798 \ud589\uc704\ub97c \uadf8\ub300\ub85c \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \uac83\uacfc\ub294 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.',B.Rq,B.aVo,null)
B.aJG=s(["\ub2f9\uc0ac\uc790\uac00 \uadf8 \ud589\uc704\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0\uc11c \ucd94\uc778\ud558\uc5ec\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \ubaa8\ub974\uace0 \ucd94\uc778\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ucd94\uc778 \ud6c4 3\ub144\uc774 \uacbd\uacfc\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
