B.bBM=new A.a("gen_cl_void_16","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\ub85c \ubb34\ud6a8\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc774 \uc544\ub2cc \uac83\uc740?",B.b4L,3,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \ubb34\ud6a8\ub85c \ub418\uae30 \uc704\ud574\uc11c\ub294 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \uc911 \ud558\ub098, \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac(\uc545\uc758)\ub77c\ub294 \uc138 \uc694\uac74\uc774 \ubaa8\ub450 \ud544\uc694\ud558\ub2e4. \ud53c\ud574\uc790\uc5d0\uac8c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc874\uc7ac\ud558\ub294\uc9c0 \uc5ec\ubd80\ub294 \uc81c104\uc870\uc758 \uc694\uac74\uacfc \ubb34\uad00\ud558\ub2e4.",B.J6,B.aU_,null)
