B.bvn=new A.a("gen_cl_void_17","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uc774\ud589\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0 \uadf8 \ubc18\ud658 \uadfc\uac70\ub294?",B.a_S,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc774 \uc788\ub2e4\uba74 \uadf8 \uc774\ud589\uc740 \ubc95\ub960\uc0c1 \uc6d0\uc778 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uac83\uc774\ubbc0\ub85c, \ubd80\ub2f9\uc774\ub4dd\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c741\uc870\uc5d0 \ub530\ub77c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \ubc18\uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18 \ub4f1 \ubd88\ubc95\uc6d0\uc778\uae09\uc5ec(\uc81c746\uc870)\uc5d0 \ud574\ub2f9\ud558\uba74 \uc608\uc678\uc801\uc73c\ub85c \ubc18\ud658\uccad\uad6c\uac00 \uc81c\ud55c\ub420 \uc218 \uc788\ub2e4.",B.aIL,B.ayL,null)
B.aEq=s(["\ubd88\ubc95\uc758 \uc6d0\uc778\uc73c\ub85c \uc7ac\uc0b0\uc744 \uae09\uc5ec\ud55c \uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\ubd88\ubc95\uc758 \uc6d0\uc778\uc73c\ub85c \uae09\uc5ec\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ud56d\uc0c1 \ubc18\ud658\ubc1b\uc744 \uc218 \uc788\ub2e4","\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\ub294 \ud56d\uc0c1 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\uc774\ub2e4","\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec \uaddc\uc815\uc740 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad00\ud558\ub2e4"],t.s)
B.M5=s(["\ubd88\ubc95\uc758 \uc6d0\uc778\uc73c\ub85c \uc7ac\uc0b0\uc744 \uae09\uc5ec\ud558\uac70\ub098 \ub178\ubb34\ub97c \uc81c\uacf5\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc774\uc775\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
