B.bzI=new A.a("gen_cl_void_20","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac00\ub9f9\uacc4\uc57d\uc758 \ub0b4\uc6a9 \uc911 \uc77c\ubd80 \uc870\ud56d\uc774 \uac15\ud589\ubc95\uaddc(\uac00\ub9f9\uc0ac\uc5c5\ubc95 \ub4f1)\uc5d0 \uc704\ubc18\ub418\uc5b4 \ubb34\ud6a8\uc778 \uacbd\uc6b0, \ub098\uba38\uc9c0 \uacc4\uc57d \uc870\ud56d\uc758 \ud6a8\ub825\uc740?",B.aAC,0,"\ubbfc\ubc95 \uc81c137\uc870\uc758 \uc77c\ubd80\ubb34\ud6a8 \ubc95\ub9ac\uc5d0 \ub530\ub77c, \uac00\ub9f9\uacc4\uc57d \uc911 \uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\ub294 \ud2b9\uc815 \uc870\ud56d\uc774 \ubb34\ud6a8\ub77c \ud558\ub354\ub77c\ub3c4 \uadf8 \ubb34\ud6a8 \ubd80\ubd84\uc774 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub41c\ub2e4\uba74 \ub098\uba38\uc9c0 \uacc4\uc57d \uc870\ud56d\uc740 \uc720\ud6a8\ud558\uac8c \uc874\uc18d\ud560 \uc218 \uc788\ub2e4.",B.al2,B.NL,null)
B.aSI=s(["\ubb34\ud6a8\uc774\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\uc0c1\ub300\ubc29\ub9cc \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
