B.bnt=new A.a("gen_cl_void_21","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ube44\uc9c4\uc758\ud45c\uc2dc(\uc81c107\uc870)\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.aSI,0,"\ubbfc\ubc95 \uc81c107\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub294 \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\uac00 \ubb34\ud6a8\ub77c\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ubb34\ud6a8\ub3c4 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4.",B.ads,B.ayq,null)
B.aRg=s(["\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870), \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\ub9cc","\ube44\uc9c4\uc758\ud45c\uc2dc(\uc81c107\uc870)\ub9cc","\ucc29\uc624(\uc81c109\uc870)\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub9cc"],t.s)
