B.bxE=new A.a("gen_cl_void_22","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uc911 \uc808\ub300\uc801 \ubb34\ud6a8\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74?",B.aRg,0,"\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ud574\ub2f9\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\uc640 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub294 \uc808\ub300\uc801 \ubb34\ud6a8\uc774\ub2e4. \ubc18\uba74 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc, \ube44\uc9c4\uc758\ud45c\uc2dc, \ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ubaa8\ub450 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ub294 \uc0c1\ub300\uc801 \ubb34\ud6a8(\ub610\ub294 \ucde8\uc18c\ub85c\uc11c \ub300\ud56d\ubd88\uac00)\uc758 \uad6c\uc870\ub97c \ucde8\ud55c\ub2e4.",B.b1z,B.ac4,null)
B.PG=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc774\ud589\ub418\uc9c0 \uc54a\uc740 \uc774\uc0c1 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubb34\ud6a8\ub294 \ubc95\uc6d0\uc758 \ud655\uc778\ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \ube44\ub85c\uc18c \ud6a8\ub825\uc774 \uc5c6\uc5b4\uc9c4\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc18c\uc1a1\uc5d0\uc11c \ud655\uc778\uc758 \uc18c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
