B.bmp=new A.a("gen_cl_void_28","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.azM,1,'\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub77c\ub3c4 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uadf8 \uc720\ud6a8\xb7\ubb34\ud6a8 \uc5ec\ubd80\uc5d0 \uad00\ud55c \ub2e4\ud23c\uc774 \uc788\uac70\ub098, \uc0c1\ub300\ubc29\uc774 \ubb34\ud6a8\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c "\uc774\ud589 \uc804\uc774\ub77c\uba74 \uc544\ubb34 \ubb38\uc81c\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\uc81c\ub85c\ub294 \ud655\uc778\uc758 \uc18c \ub4f1\uc744 \ud1b5\ud574 \ubb34\ud6a8\uc784\uc744 \uba85\ud655\ud788 \ud560 \ud544\uc694\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.',B.a0g,B.agY,null)
B.aSD=s(["\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc774 \uc788\ub294 \uacbd\uc6b0)","\ucde8\uc18c\uad8c\uc758 3\ub144\xb710\ub144 \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)","\ubc95\uc815\ucd94\uc778(\uc81c145\uc870)","\ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870)"],t.s)
B.auA=s(["\uadf8 \uc774\ud589\uc774 \ubc95\ub960\uc0c1 \uc6d0\uc778 \uc5c6\ub294 \uac83\uc774 \ub418\uc5b4 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc81c741\uc870)\uc758 \ubb38\uc81c\uac00 \uacf5\ud1b5\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
