B.be7=new A.a("gen_cl_void_29","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \ubaa8\ub450\uc5d0 \uacf5\ud1b5\uc801\uc73c\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \uc81c\ub3c4\ub294?",B.aSD,0,"\ubb34\ud6a8\uc774\ub4e0 \ucde8\uc18c\ub418\uc5b4 \uc18c\uae09\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\uc5c8\ub4e0, \ubc95\ub960\uc0c1 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uc774\ud589\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc774\ud589\uc774 \ubc95\ub960\uc0c1 \uc6d0\uc778 \uc5c6\ub294 \uac83\uc774 \ub418\uc5b4 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc81c741\uc870)\uc758 \ubb38\uc81c\uac00 \uacf5\ud1b5\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4. \ubc18\uba74 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04, \ubc95\uc815\ucd94\uc778, \ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud2b9\uc720\ud55c \uc81c\ub3c4\uc774\ub2e4.",B.auA,B.a5S,null)
