B.XJ=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b7u=s(["\ub3d9\uc758 \uc5c6\ub294 \ubbf8\uc131\ub144\uc790 \ud589\uc704\uc758 \ud6a8\ub825(\uc81c5\uc870 \uc81c2\ud56d)"],t.s)
B.boy=new A.a("gen_cl_minor_2","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc740?",B.aqb,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c, \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.XJ,B.b7u,null)
B.Xf=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704","\ubd80\ub3d9\uc0b0\uc744 \ub9e4\uc218\ud558\ub294 \ud589\uc704","\uae08\uc804\uc744 \ub300\ucc28(\ube4c\ub9ac\ub294)\ud558\ub294 \ud589\uc704","\ud0c0\uc778\uc758 \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \ud589\uc704"],t.s)
B.aUz=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704"],t.s)
B.PZ=s(["\ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c)"],t.s)
B.bfU=new A.a("gen_cl_minor_3","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294?",B.Xf,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub294 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \ud589\uc704\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubc18\uba74 \ubd80\ub3d9\uc0b0 \ub9e4\uc218, \uae08\uc804 \ub300\ucc28, \ubcf4\uc99d\ud589\uc704\ub294 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.aUz,B.PZ,null)
B.We=s(["\ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc7ac\uc0b0\uc5d0 \uad00\ud558\uc5ec\ub294 \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc744 \ud5c8\ub77d\ubc1b\uc544\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uac1c\ubcc4 \ub3d9\uc758\uac00 \ub9e4\ubc88 \ud544\uc694\ud558\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc774\ub77c\ub3c4 \ucc98\ubd84\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84 \ud5c8\ub77d\uc740 \uc5b8\uc81c\ub098 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b_3=s(["\uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Uw=s(["\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84(\uc81c6\uc870)"],t.s)
B.bCW=new A.a("gen_cl_minor_4","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ucc98\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.We,0,"\ubbfc\ubc95 \uc81c6\uc870\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubc94\uc704\ub97c \uc815\ud558\uc5ec \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud574\uc11c\ub294 \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \uc6a9\ub3c8\uc73c\ub85c \uc900 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub300\ud45c\uc801\uc774\uba70, \uc774 \uacbd\uc6b0 \ub9e4\ubc88 \uac1c\ubcc4 \ub3d9\uc758\ub97c \ub2e4\uc2dc \ubc1b\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4.",B.b_3,B.Uw,null)
B.LD=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4","\ud5c8\ub77d\ubc1b\uc740 \uc601\uc5c5\uc774\ub77c\ub3c4 \ub9e4 \uac70\ub798\ub9c8\ub2e4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\uc601\uc5c5\uc758 \ud5c8\ub77d\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ud655\uc815\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aHG=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
