B.bjs=new A.a("gen_cl_minor_5","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\uc758 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.LD,0,"\ubbfc\ubc95 \uc81c8\uc870 \uc81c1\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\ub294 \uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \uc601\uc5c5\uc5d0 \ubd80\uc801\ub2f9\ud568\uc774 \ubc1c\uacac\ub418\uba74 \uadf8 \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4.",B.aHG,B.aLG,null)
B.Vt=s(["\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc774 \ub418\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcc4\ub3c4 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
B.b_5=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub300\ub9ac(\uc81c117\uc870)"],t.s)
B.bw5=new A.a("gen_cl_minor_6","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Vt,0,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub300\ub9ac\ud589\uc704\uc758 \ubc95\ub960\ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc774 \uc544\ub2c8\ub77c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c, \ubbf8\uc131\ub144\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ub300\ub9ac\uc778\uc774 \ub418\uc5b4 \ub300\ub9ac\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4.",B.p_,B.b_5,null)
B.VK=s(["\ud63c\uc778\uc73c\ub85c \uc131\ub144\uc5d0 \uc774\ub978 \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc131\ub144\uc758\uc81c)","\ud63c\uc778\ud574\ub3c4 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0\ub294 \ubcc0\ud654\uac00 \uc5c6\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc5ec\uc804\ud788 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\uc5d0 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc774\ud63c\ud558\uba74 \ub2e4\uc2dc \ubbf8\uc131\ub144\uc790 \uc9c0\uc704\ub85c \ubcf5\uadc0\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.Ni=s(["\ubbf8\uc131\ub144\uc790\uac00 \ud63c\uc778\uc744 \ud55c \ub54c\uc5d0\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4"],t.s)
