B.brO=new A.a("gen_cl_minor_7","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.VK,0,"\ubbfc\ubc95 \uc81c826\uc870\uc7582\ub294 \ubbf8\uc131\ub144\uc790\uac00 \ud63c\uc778\uc744 \ud55c \ub54c\uc5d0\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4(\uc131\ub144\uc758\uc81c). \uc774\uc5d0 \ub530\ub77c \ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \uc644\uc804\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\uac8c \ub41c\ub2e4.",B.Ni,B.aaq,null)
