B.bdB=new A.a("gen_cl_minor_8","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud558\uc5ec \uac00\uc9c0\ub294 \uad8c\ud55c\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.b1J,0,"\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud574 \ub3d9\uc758\uad8c(\uc81c5\uc870), \ub300\ub9ac\uad8c(\uc81c920\uc870 \ub4f1), \uadf8\ub9ac\uace0 \ub3d9\uc758 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\xb7\ucd94\uc778\uad8c(\uc81c140\uc870, \uc81c143\uc870)\uc744 \uac00\uc9c4\ub2e4. \ud615\uc0ac\ucc98\ubc8c\uad8c\uc740 \ubbfc\ubc95\uc0c1 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uad8c\ud55c\uc774 \uc544\ub2c8\ub2e4.",B.WK,B.b1R,null)
B.a2M=s(["\uc0c1\ub300\ubc29\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \uc77c\uc815 \uae30\uac04 \ub0b4 \ucde8\uc18c \ub610\ub294 \ucd94\uc778 \uc5ec\ubd80\uc5d0 \ub300\ud55c \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4","\ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \uc0c1\ub300\ubc29\uc774 \uc544\ub2c8\ub77c \uc81c\ud55c\ub2a5\ub825\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ud655\ub2f5\ucd09\uad6c\uac00 \uc788\uc5b4\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uc751\ub2f5\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4","\ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \ubbf8\uc131\ub144\uc790\uac00 \uc131\ub144\uc774 \ub418\uae30 \uc804\uc5d0\ub294 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aPv=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc5d0 \ub300\ud558\uc5ec 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
