B.btT=new A.a("gen_cl_minor_9","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \uac00\uc9c0\ub294 \ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2M,0,"\ubbfc\ubc95 \uc81c15\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0 \ub300\ud558\uc5ec 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \uadf8 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ubd88\uc548\uc815\ud55c \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ud0a4\uae30 \uc704\ud55c \uc0c1\ub300\ubc29 \ubcf4\ud638 \uc81c\ub3c4\uc774\ub2e4.",B.aPv,B.Yg,null)
B.a79=s(["\uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\uc544\ubb34\ub7f0 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
