B.byw=new A.a("gen_cl_minor_10","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.a79,0,"\ubbfc\ubc95 \uc81c15\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uace0\ub3c4 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \uc774\ub294 \ubc95\ub960\uad00\uacc4\ub97c \uc2e0\uc18d\ud788 \uc720\ud6a8\ub85c \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.aVO,B.akT,null)
B.abV=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uacc4\uc57d\uc744 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uacc4\uc57d\uc744 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4","\ucca0\ud68c\uad8c\uc740 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uc778\uc815\ub41c\ub2e4","\ucca0\ud68c\uad8c\uc740 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.aB_=s(["\uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
