B.bFR=new A.a("gen_cl_minor_11","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc0c1\ub300\ubc29\uc758 \ucca0\ud68c\uad8c(\uc81c16\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.abV,0,"\ubbfc\ubc95 \uc81c16\uc870 \uc81c1\ud56d\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uacc4\uc57d\uc740 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \uacc4\uc57d \ub2f9\uc2dc \uc81c\ud55c\ub2a5\ub825\uc790\uc784\uc744 \uc54c\uc558\uc744 \uacbd\uc6b0(\uc545\uc758\uc758 \uc0c1\ub300\ubc29)\uc5d0\ub294 \uc774\ub7ec\ud55c \ucca0\ud68c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aB_,B.a5l,null)
B.aVU=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704","\uc81c\ud55c\ub2a5\ub825\uc790\uc640 \ub9fa\uc740 \uc30d\ubc29 \uacc4\uc57d","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub3d9\uc758\ud55c \ud589\uc704","\uc601\uc5c5\uc774 \ud5c8\ub77d\ub41c \ubc94\uc704\uc758 \ud589\uc704"],t.s)
B.Q0=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud558\uc5ec\ub294 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.MS=s(["\uc0c1\ub300\ubc29\uc758 \uac70\uc808\uad8c(\uc81c16\uc870 \uc81c2\ud56d)"],t.s)
B.bvk=new A.a("gen_cl_minor_12","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc0c1\ub300\ubc29\uc758 \uac70\uc808\uad8c(\uc81c16\uc870 \uc81c2\ud56d)\uc774 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\ub294?",B.aVU,0,"\ubbfc\ubc95 \uc81c16\uc870 \uc81c2\ud56d\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud558\uc5ec\ub294 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uacc4\uc57d\uacfc \ub2ec\ub9ac \ub2e8\ub3c5\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc77c\ubc29\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ubbc0\ub85c, \uadf8 \ud6a8\ub825\uc774 \ubd88\ud655\uc2e4\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uac70\uc808\uad8c\uc744 \uc778\uc815\ud55c \uac83\uc774\ub2e4.",B.Q0,B.MS,null)
B.aG7=s(["\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc774 \uc624\ud788\ub824 \uc5f0\uc7a5\ub41c\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ucde8\uc18c\uad8c\ub9cc \uc778\uc815\ub418\uace0 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc758 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
