B.blK=new A.a("gen_cl_minor_13","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc18d\uc784\uc218(\uc81c17\uc870)\ub85c \uc0c1\ub300\ubc29\uc774 \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ub41c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.aG7,0,"\ubbfc\ubc95 \uc81c17\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc18d\uc784\uc218\ub85c\uc368 \uc790\uae30\ub97c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud558\uac70\ub098 \ubbf8\uc131\ub144\uc790\xb7\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc774 \uc18d\uc784\uc218\ub85c\uc368 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc0c1\ub300\ubc29\uc744 \uae30\ub9dd\ud55c \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ub354 \uc774\uc0c1 \ubcf4\ud638\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.atv,B.aD6,null)
B.aTq=s(["\uc801\uadf9\uc801\uc73c\ub85c \uc0c1\ub300\ubc29\uc744 \uc18d\uc774\ub824\ub294 \uc220\ucc45\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ub418\uace0, \ub2e8\uc21c\ud788 \uc131\ub144\uc790\ub77c\uace0 \ub9d0\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc5c4\uaca9\ud558\uac8c \ud574\uc11d\ub41c\ub2e4","\ubbf8\uc131\ub144\uc790\ub77c\ub294 \uc0ac\uc2e4\uc744 \ubc1d\ud788\uc9c0 \uc54a\uc740 \ubaa8\ub4e0 \uacbd\uc6b0\uc5d0 \uc18d\uc784\uc218\uac00 \uc778\uc815\ub41c\ub2e4","\uc18d\uc784\uc218 \uc5ec\ubd80\ub294 \ubb38\uc81c\ub418\uc9c0 \uc54a\uace0 \uacb0\uacfc\ub9cc \uc911\uc694\ud558\ub2e4","\uc18d\uc784\uc218\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
B.amQ=s(["\uc801\uadf9\uc801\uc73c\ub85c \uc0c1\ub300\ubc29\uc744 \uc18d\uc774\ub824\ub294 \uc220\ucc45\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ub418\uace0"],t.s)
