B.buy=new A.a("gen_cl_minor_14","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,'\uc81c17\uc870\uc758 "\uc18d\uc784\uc218"\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aTq,0,'\ud310\ub840\ub294 \uc81c17\uc870\uc758 "\uc18d\uc784\uc218"\ub97c \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf4\ud638\uc758 \uc608\uc678 \uaddc\uc815\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uc5c4\uaca9\ud558\uac8c \ud574\uc11d\ud558\uc5ec, \uc801\uadf9\uc801\uc73c\ub85c \uae30\ub9dd\uc218\ub2e8\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc778\uc815\ud558\uace0, \ub2e8\uc21c\ud788 \uc790\uc2e0\uc774 \uc131\ub144\uc790\ub77c\uace0 \uc5b8\uae09\ud558\uac70\ub098 \uce68\ubb35\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \uc18d\uc784\uc218\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.',B.amQ,B.aRw,null)
B.b2y=s([u.hz,"\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud56d\uc0c1 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \ub2a5\ub825\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4","\ubbfc\ubc95\uc774 \uba85\uc2dc\uc801\uc73c\ub85c \uc608\uc678\ub97c \ub450\uc9c0 \uc54a\uc544 \ud574\uc11d\uc0c1 \uc778\uc815\ub420 \ubfd0\uc774\ub2e4"],t.s)
