B.bBd=new A.a("gen_cl_minor_15","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc774 \uc790\uc2e0\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\uc744 \ub2e8\ub3c5\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uc774\uc720\ub294?",B.b2y,0,"\ucde8\uc18c\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c \ubd88\ub9ac\ud55c \ubc95\ub960\ud589\uc704\ub97c \ubb34\ud6a8\ud654\ud558\uc5ec \uadf8\ub97c \ubcf4\ud638\ud558\ub294 \ubc29\ud5a5\uc758 \ud589\uc704\uc774\ubbc0\ub85c, \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc694\uad6c\ud560 \uc774\uc720\uac00 \uc5c6\ub2e4. \uc774\uc5d0 \ub530\ub77c \ubbfc\ubc95 \uc81c140\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ucde8\uc18c\uad8c\uc790\ub85c \uba85\uc2dc\ud558\uc5ec \ubcf8\uc778\uc774 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.alK,B.ajK,null)
B.a48=s(["\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4","\ubc1b\uc740 \uc774\uc775 \uc804\ubd80\ub97c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc18\ud658\uc758\ubb34\uac00 \uc804\ud600 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\uc2e0 \uc804\uc561\uc744 \ubc30\uc0c1\ud574\uc57c \ud55c\ub2e4"],t.s)
B.b70=s(["\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4"],t.s)
B.aLS=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704(\uc81c141\uc870 \ub2e8\uc11c)"],t.s)
B.bBl=new A.a("gen_cl_minor_16","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ub9e4\ub9e4\uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \ud6c4 \uc774\ub97c \ucde8\uc18c\ud55c \uacbd\uc6b0, \ubbf8\uc131\ub144\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704\ub294?",B.a48,0,"\uc81c141\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc18\ud658\ud560 \ucc45\uc784\uc774 \uc788\ub2e4. \uc608\ucee8\ub300 \ub9e4\ub9e4\ub300\uae08\uc744 \ubc1b\uc544 \uc774\ubbf8 \uc18c\ube44\ud574\ubc84\ub838\ub2e4\uba74 \uadf8 \uc18c\ube44\ud55c \ubd80\ubd84\uc740 \ubc18\ud658\uc758\ubb34\uc5d0\uc11c \uc81c\uc678\ub420 \uc218 \uc788\ub2e4.",B.b70,B.aLS,null)
B.ar6=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\uc73c\ub098, \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ub450 \uc81c\ub3c4\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c \ubc29\uc2dd\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud53c\uc131\ub144\ud6c4\uacac\uc778\ub3c4 \ubbf8\uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud558\uac8c \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub85c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aaK=s(["\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.NG=s(["\ubbf8\uc131\ub144\uc790\uc640 \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ube44\uad50"],t.s)
B.blU=new A.a("gen_cl_minor_17","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc640 \uc131\ub144\ud6c4\uacac\uc744 \ubc1b\ub294 \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ar6,0,"\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098(\uc81c5\uc870), \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc758 \uc5ec\ubd80\ub97c \ubd88\ubb38\ud558\uace0 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c10\uc870 \uc81c1\ud56d). \ub2e4\ub9cc \uac00\uc815\ubc95\uc6d0\uc774 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ucc28\uc774\uac00 \uc788\ub2e4.",B.aaK,B.NG,null)
B.aEm=s(["\uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ubbc0\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\uc0c1\ub300\ubc29\ub3c4 \ucde8\uc18c\uad8c\uc790\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ud5c8\ub77d\uc744 \ubc1b\uc73c\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.SY=s(["\ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ub2e4"],t.s)
