B.buf=new A.a("gen_cl_prescription_5","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubbfc\ubc95 \uc81c164\uc870\uac00 \uc815\ud558\ub294 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8 \ub300\uc0c1 \ucc44\uad8c\uc774 \uc544\ub2cc \uac83\uc740?",B.aTo,3,"\ub3c4\uae09\ubc1b\uc740 \uc790 \ubc0f \uae30\uc0ac \ub4f1 \uacf5\uc0ac\uc758 \uc124\uacc4\xb7\uac10\ub3c5\uc5d0 \uc885\uc0ac\ud558\ub294 \uc790\uc758 \uacf5\uc0ac\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c163\uc870 \uc81c3\ud638\uc5d0 \uc758\ud574 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4. \uc219\ubc15\ub8cc\xb7\ub3d9\uc0b0\uc0ac\uc6a9\ub8cc\xb7\ub178\uc5ed\uc778 \uc784\uae08\ucc44\uad8c \ub4f1\uc740 \uc81c164\uc870\uc5d0 \ub530\ub77c 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.",B.azC,B.WY,null)
B.ahg=s(["\uc0c1\ud589\uc704\ub85c \uc778\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc740 \ub2e4\ub978 \ubc95\ub839\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 5\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4.","\uc0c1\uc0ac\ucc44\uad8c\uc740 \ubbfc\ubc95\uc0c1 \uc77c\ubc18\ucc44\uad8c\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc5b8\uc81c\ub098 10\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4.","\uc0c1\uc778 \uc0ac\uc774\uc758 \ucc44\uad8c\uc740 \ubbfc\ubc95\uc0c1 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8 \uaddc\uc815\uc774 \uc6b0\uc120 \uc801\uc6a9\ub418\uc5b4 5\ub144\ubcf4\ub2e4 \uc9e7\uc544\uc9c8 \uc218 \uc5c6\ub2e4.","\uc0c1\uc0ac\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c\ub3c4 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4."],t.s)
