B.Rd=s(["\uc9c0\uc5ed\uad8c\uc740 \uc77c\uc815\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \ud0c0\uc778\uc758 \ud1a0\uc9c0\ub97c \uc790\uae30 \ud1a0\uc9c0\uc758 \ud3b8\uc775\uc5d0 \uc774\uc6a9\ud558\ub294 \ubb3c\uad8c\uc774\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uc790 \uac1c\uc778\ub9cc\uc744 \uc704\ud55c \uc778\uc801 \uad8c\ub9ac\uc774\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \ucc44\uad8c\uc774\ubbc0\ub85c \ub4f1\uae30\ud560 \uc218 \uc5c6\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \ubc18\ub4dc\uc2dc \uc720\uc0c1\uc73c\ub85c\ub9cc \uc124\uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aK6=s(["\uc77c\uc815\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \ud0c0\uc778\uc758 \ud1a0\uc9c0\ub97c \uc790\uae30 \ud1a0\uc9c0\uc758 \ud3b8\uc775\uc5d0 \uc774\uc6a9\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud55c\ub2e4"],t.s)
B.aYS=s(["\uc9c0\uc5ed\uad8c\uc758 \uc758\uc758","\ubbfc\ubc95 \uc81c291\uc870"],t.s)
B.bl3=new A.a("gen_cl_usufruct_13","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc5ed\uad8c\uc758 \uc758\uc758\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Rd,0,"\ubbfc\ubc95 \uc81c291\uc870\ub294 \uc9c0\uc5ed\uad8c\uc744 \uc77c\uc815\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \ud0c0\uc778\uc758 \ud1a0\uc9c0\ub97c \uc790\uae30 \ud1a0\uc9c0\uc758 \ud3b8\uc775\uc5d0 \uc774\uc6a9\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud55c\ub2e4. \uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0\uc758 \uc18c\uc720\uad8c\uc5d0 \uc885\ub41c \uad8c\ub9ac\ub85c\uc11c \uc694\uc5ed\uc9c0\uc640 \ubd84\ub9ac\ud558\uc5ec \uc591\ub3c4\ud558\uc9c0 \ubabb\ud55c\ub2e4(\uc81c292\uc870 \uc81c2\ud56d).",B.aK6,B.aYS,null)
B.aDD=s(["\ud1a0\uc9c0\uacf5\uc720\uc790\uc758 1\uc778\uc740 \uc9c0\ubd84\uc5d0 \uad00\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc704\ud55c \uc9c0\uc5ed\uad8c\uc744 \uc18c\uba78\ud558\uac8c \ud558\uc9c0 \ubabb\ud55c\ub2e4","\ud1a0\uc9c0\uc758 \ubd84\ud560\uc774\ub098 \ud1a0\uc9c0 \uc77c\ubd80\uc758 \uc591\ub3c4\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc9c0\uc5ed\uad8c\uc740 \uadf8 \ud1a0\uc9c0\uc758 \uac01\ubd80\ubd84\uc744 \uc704\ud558\uc5ec \ub610\ub294 \uadf8 \uac01\ubd80\ubd84\uc5d0 \uc874\uc18d\ud55c\ub2e4","\uacf5\uc720\uc790 \uc911 1\uc778\uc5d0 \ub300\ud55c \uc9c0\uc5ed\uad8c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \ub2e4\ub978 \uacf5\uc720\uc790\ub97c \uc704\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4","\uc694\uc5ed\uc9c0\uac00 \uc218\uc778\uc758 \uacf5\uc720\uc778 \uacbd\uc6b0 \uacf5\uc720\uc790 1\uc778\uc774 \ucde8\ub4dd\uc2dc\ud6a8 \uc911\ub2e8\ud589\uc704\ub97c \ud558\uba74 \ub2e4\ub978 \uacf5\uc720\uc790\uc5d0\uac8c\ub3c4 \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.a86=s(["\uacf5\uc720\uc790 1\uc778\uc5d0 \ub300\ud55c \uc9c0\uc5ed\uad8c \ucde8\ub4dd\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \ub2e4\ub978 \uacf5\uc720\uc790\ub97c \uc704\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
