B.bpa=new A.a("gen_cl_usufruct_17","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc758 \uc758\uc758\uc640 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aEj,3,"\ubbfc\ubc95 \uc81c303\uc870\ub294 \uc804\uc138\uad8c\uc744 \uc804\uc138\uae08\uc744 \uc9c0\uae09\ud558\uace0 \ud0c0\uc778\uc758 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud558\uc5ec \uadf8 \ubd80\ub3d9\uc0b0\uc758 \uc6a9\ub3c4\uc5d0 \uc887\uc544 \uc0ac\uc6a9\xb7\uc218\uc775\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud558\uace0, \uc81c312\uc870\ub294 \uc874\uc18d\uae30\uac04\uc744 10\ub144\uc744 \ub118\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\uba70 \uac74\ubb3c\uc804\uc138\uad8c\uc758 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc744 1\ub144\uc73c\ub85c \uc815\ud55c\ub2e4. \ub2f9\uc0ac\uc790\uac00 1\ub144\ubcf4\ub2e4 \ub2e8\ucd95\ud55c \uae30\uac04\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uc774\ub97c 1\ub144\uc73c\ub85c \ubcf8\ub2e4.",B.aq4,B.azO,null)
