B.bEz=new A.a("gen_cl_source_5","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc744 \uaddc\uc815\ud55c \ubbfc\ubc95 \uc81c2\uc870 \uc81c2\ud56d\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a4Y,0,'\ubbfc\ubc95 \uc81c2\uc870 \uc81c2\ud56d\uc740 "\uad8c\ub9ac\ub294 \ub0a8\uc6a9\ud558\uc9c0 \ubabb\ud55c\ub2e4"\uace0 \uaddc\uc815\ud55c\ub2e4. \uad8c\ub9ac\ub0a8\uc6a9\uc774 \uc778\uc815\ub418\uba74 \uadf8 \uad8c\ub9ac\ud589\uc0ac\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\ud589\uc0ac\ub85c\uc11c\uc758 \ud6a8\ub825\uc774 \ubd80\uc778\ub418\uba70, \uacbd\uc6b0\uc5d0 \ub530\ub77c \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc774 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\ub2e4.',B.b_R,B.aDx,null)
B.b28=s(["\uc678\ud615\uc0c1 \uad8c\ub9ac\ud589\uc0ac\ucc98\ub7fc \ubcf4\uc774\ub098 \uadf8 \uad8c\ub9ac\ud589\uc0ac\uac00 \uc815\ub2f9\ud55c \uc774\uc775 \uc5c6\uc774 \uc624\uc9c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uace0\ud1b5\uc744 \uc8fc\uace0 \uc190\ud574\ub97c \uc785\ud788\ub824\ub294 \ub370 \uc788\ub294 \ub4f1 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ub418\ub294 \uacbd\uc6b0","\uad8c\ub9ac\uc790\uac00 \uc790\uc2e0\uc758 \uc774\uc775\uc744 \uc870\uae08\uc774\ub77c\ub3c4 \uc5bb\uc73c\uba74 \ud56d\uc0c1 \uad8c\ub9ac\ub0a8\uc6a9\uc774 \ub41c\ub2e4","\uad8c\ub9ac\ud589\uc0ac\uc5d0 \uace0\uc758\ub098 \uacfc\uc2e4\uc774 \uc804\ud600 \uc5c6\uc5b4\uc57c\ub9cc \uad8c\ub9ac\ub0a8\uc6a9\uc774 \uc131\ub9bd\ud55c\ub2e4","\uad8c\ub9ac\ud589\uc0ac\uac00 \ubc95\ub960\uc5d0 \uba85\uc2dc\uc801\uc73c\ub85c \uae08\uc9c0\ub41c \uacbd\uc6b0\uc5d0\ub9cc \uad8c\ub9ac\ub0a8\uc6a9\uc774 \uc778\uc815\ub41c\ub2e4"],t.s)
