B.bzS=new A.a("gen_cl_source_6","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\ud310\ub840\uac00 \uc778\uc815\ud558\ub294 \uad8c\ub9ac\ub0a8\uc6a9\uc758 \uc131\ub9bd\uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b28,0,"\ud310\ub840\ub294 \uad8c\ub9ac\uc758 \ud589\uc0ac\uac00 \uc8fc\uad00\uc801\uc73c\ub85c \uc624\uc9c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uace0\ud1b5\uc744 \uc8fc\uace0 \uc190\ud574\ub97c \uc785\ud788\ub824\ub294 \ub370 \uc788\uc744 \ubfd0 \ud589\uc0ac\ud558\ub294 \uc790\uc5d0\uac8c \uc544\ubb34\ub7f0 \uc774\uc775\uc774 \uc5c6\ub294 \uacbd\uc6b0, \uadf8 \uad8c\ub9ac\ud589\uc0ac\uac00 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ub41c\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \uacbd\uc6b0 \uad8c\ub9ac\ub0a8\uc6a9\uc5d0 \ud574\ub2f9\ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uad8c\ub9ac\ub0a8\uc6a9\uc774 \uc778\uc815\ub418\uba74 \uadf8 \uad8c\ub9ac\ud589\uc0ac\uc758 \ud6a8\uacfc\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.a2i,B.ao3,null)
B.aef=s(["\uad8c\ub9ac\uc790\uac00 \uc7a5\uae30\uac04 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uc5ec \uc0c1\ub300\ubc29\uc774 \uc774\uc81c\ub294 \uad8c\ub9ac\ud589\uc0ac\ub97c \ud558\uc9c0 \uc54a\uc744 \uac83\uc73c\ub85c \uc815\ub2f9\ud558\uac8c \uc2e0\ub8b0\ud55c \uacbd\uc6b0, \uc0c8\uc0bc\uc2a4\ub7ec\uc6b4 \uad8c\ub9ac\ud589\uc0ac\uac00 \uc2e0\uc758\uce59\uc5d0 \ubc18\ud558\uc5ec \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc6d0\uce59","\uad8c\ub9ac\ub294 \ubc1c\uc0dd\uacfc \ub3d9\uc2dc\uc5d0 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc9c4\ud589\ub41c\ub2e4\ub294 \uc6d0\uce59","\ubaa8\ub4e0 \uad8c\ub9ac\ub294 10\ub144\uc774 \uc9c0\ub098\uba74 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ud55c\ub2e4\ub294 \uc6d0\uce59","\uad8c\ub9ac\uc790\uc758 \uc0c1\uc18d\uc778\ub9cc\uc774 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\ub294 \uc6d0\uce59"],t.s)
B.auD=s(["\uc758\ubb34\uc790\ub85c \ud558\uc5ec\uae08 \uc774\uc81c\ub294 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uc9c0 \uc54a\uc744 \uac83\uc73c\ub85c \uc2e0\ub8b0\ud560 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc0ac\uc720\ub97c \uac16\uac8c \ud55c \ub2e4\uc74c \uc0c8\uc0bc\uc2a4\ub7fd\uac8c \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ubc18\ud558\ub294 \uacbd\uc6b0"],t.s)
