B.Ul=s(["\ubc95\ub960\ud589\uc704 \uc131\ub9bd\uc758 \uae30\ucd08\uac00 \ub41c \uc0ac\uc815\uc774 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc744 \uacaa\uc5b4 \ub2f9\ucd08\uc758 \uacc4\uc57d \ub0b4\uc6a9\ub300\ub85c \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0 \uacc4\uc57d\uc758 \ub0b4\uc6a9\uc744 \uc218\uc815\ud558\uac70\ub098 \ud574\uc81c\xb7\ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\ub294 \uc6d0\uce59","\uacc4\uc57d\uc740 \uc5b4\ub5a0\ud55c \uc0ac\uc815\ubcc0\uacbd\uc774 \uc788\uc5b4\ub3c4 \uc808\ub300\uc801\uc73c\ub85c \uad6c\uc18d\ub825\uc744 \uac00\uc9c4\ub2e4\ub294 \uc6d0\uce59","\uc0ac\uc815\ubcc0\uacbd\uc774 \uc788\uc73c\uba74 \uacc4\uc57d\uc740 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4\ub294 \uc6d0\uce59","\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uce59\uacfc \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubc95\uc6d0\ub9ac\uc774\ub2e4"],t.s)
B.aD_=s(["\ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \uc0ac\uc815\ubcc0\uacbd\uc73c\ub85c \uc778\ud558\uc5ec \ub2f9\ucd08 \uc57d\uc815\ub41c \ub300\ub85c\uc758 \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc5d0\uac8c \uc2ec\ud788 \ubd80\ub2f9\ud55c \uacb0\uacfc\ub97c \ucd08\ub798\ud558\ub294 \uacbd\uc6b0"],t.s)
B.L1=s(["\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59","\uc2e0\uc758\uce59 \ud30c\uc0dd"],t.s)
B.bHE=new A.a("gen_cl_source_8","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Ul,0,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc5d0\uc11c \ud30c\uc0dd\ub41c \ubc95\ub9ac\ub85c, \uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \uc0ac\uc815\ubcc0\uacbd\uc73c\ub85c \uc778\ud558\uc5ec \ub2f9\ucd08 \uc57d\uc815\ub41c \ub300\ub85c\uc758 \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc5d0\uac8c \uc2ec\ud788 \ubd80\ub2f9\ud55c \uacb0\uacfc\ub97c \ucd08\ub798\ud558\ub294 \uacbd\uc6b0, \uadf8 \uacc4\uc57d\uc758 \ub0b4\uc6a9\uc744 \uc218\uc815\ud558\uac70\ub098 \ud574\uc81c\xb7\ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\ub294 \uc6d0\uce59\uc774\ub2e4.",B.aD_,B.L1,null)
B.aLk=s(["\uc0ac\ubb3c\uc758 \ubcf8\uc9c8\uc801 \uc131\uc9c8 \ub0b4\uc9c0 \ub3c4\ub9ac\ub85c\uc11c, \ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \uc5c6\ub294 \uacbd\uc6b0 \uc7ac\ud310\uc758 \ucd5c\ud6c4 \uae30\uc900\uc774 \ub418\ub294 \ubcf4\ucda9\uc801 \ubc95\uc6d0","\uad6d\ud68c\uac00 \uc81c\uc815\ud55c \uc131\ubb38\uc758 \ubc95\ub960\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc758 \uac1c\ubcc4\uc801 \ud569\uc758\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc678\uad6d\uc758 \ud310\ub840\ub97c \uadf8\ub300\ub85c \uc801\uc6a9\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.aJk=s(["\ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \ubc95\uad00\uc774 \uc7ac\ud310\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294 \ucd5c\ud6c4\xb7\ubcf4\ucda9\uc801 \ubc95\uc6d0"],t.s)
B.PB=s(["\uc870\ub9ac","\ubcf4\ucda9\uc801 \ubc95\uc6d0"],t.s)
B.bgl=new A.a("gen_cl_source_9","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,'\ubbfc\ubc95 \uc81c1\uc870\uc5d0\uc11c \ub9d0\ud558\ub294 "\uc870\ub9ac"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aLk,0,"\uc870\ub9ac\ub780 \uc0ac\ubb3c\uc758 \ubcf8\uc9c8\uc801 \ubc95\uce59 \ub0b4\uc9c0 \uc0ac\ubb3c\uc758 \ub3c4\ub9ac\ub97c \uc758\ubbf8\ud558\uba70, \ubbfc\ubc95 \uc81c1\uc870\uc5d0 \ub530\ub77c \ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \ubc95\uad00\uc774 \uc7ac\ud310\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294 \ucd5c\ud6c4\xb7\ubcf4\ucda9\uc801 \ubc95\uc6d0\uc774\ub2e4. \uc870\ub9ac\ub294 \ubc95\uad00\uc758 \uc790\uc758\uc801 \ud310\ub2e8\uc774 \uc544\ub2c8\ub77c \uc0ac\ud68c\ud1b5\ub150\uc5d0 \ubd80\ud569\ud558\ub294 \ud569\ub9ac\uc801 \uae30\uc900\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aJk,B.PB,null)
B.Vl=s(["\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uc5d0 \ub300\ud558\uc5ec \ubcf4\ucda9\uc801 \ud6a8\ub825\uc744 \uac00\uc9c8 \ubfd0\uc774\uace0, \ubc95\ub960\uc5d0 \uc800\ucd09\ub418\ub294 \uad00\uc2b5\ubc95\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\ubcf4\ub2e4 \ud56d\uc0c1 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uacfc \ub3d9\ub4f1\ud55c \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc2e0\ubc95\uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uc758 \uac1c\uc815\uc774 \uc788\uc5b4\ub3c4 \uadf8 \ud6a8\ub825\uc774 \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.JX=s(["\uad00\uc2b5\ubc95\uc740 \uc131\ubb38\uc758 \ubc95\ub960\uc774 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \uc774\ub97c \ubcf4\ucda9\ud558\ub294 \ud6a8\ub825\ub9cc\uc744 \uac00\uc9c0\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4(\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124)"],t.s)
B.aNe=s(["\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124","\uad00\uc2b5\ubc95\uacfc \ubc95\ub960"],t.s)
B.be6=new A.a("gen_cl_source_10","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad00\uc2b5\ubc95\uacfc \uc131\ubb38\ubc95(\ubc95\ub960)\uc758 \ud6a8\ub825\uad00\uacc4\uc5d0 \uad00\ud55c \ud1b5\uc124\uc801 \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Vl,0,"\ud1b5\uc124\uc740 \ubbfc\ubc95 \uc81c1\uc870\uc758 \ubc95\uc6d0 \uc21c\uc11c\uc5d0 \ub530\ub77c \uad00\uc2b5\ubc95\uc740 \uc131\ubb38\uc758 \ubc95\ub960\uc774 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \uc774\ub97c \ubcf4\ucda9\ud558\ub294 \ud6a8\ub825\ub9cc\uc744 \uac00\uc9c0\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4(\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124). \ub530\ub77c\uc11c \ubc95\ub960\uc5d0 \uba85\ubb38\uc758 \uaddc\uc815\uc774 \uc788\ub294 \uc0ac\ud56d\uc5d0 \uad00\ud558\uc5ec\ub294 \uadf8\uc640 \ubc30\uce58\ub418\ub294 \uad00\uc2b5\ubc95\uc774 \uc6b0\uc120 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4.",B.JX,B.aNe,null)
B.atY=s(["\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc774 \uad8c\ub9ac\ud589\uc0ac\uc758 \uad6d\uba74\uc5d0\uc11c \uad6c\uccb4\ud654\ub41c \ud558\ub098\uc758 \ud30c\uc0dd \uc6d0\uce59\uc774\ub2e4","\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uacfc \ubb34\uad00\ud55c \ub3c5\ub9bd\ub41c \ubcc4\uac1c\uc758 \ubc95\uc6d0(\u6cd5\u6e90)\uc774\ub2e4","\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \ucc44\uad8c\uad00\uacc4\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\ub294 \ubb3c\uad8c\uad00\uacc4\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc774 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\ubcf4\ub2e4 \uc0c1\uc704\uc758 \uc77c\ubc18\uc6d0\uce59\uc774\ub2e4"],t.s)
B.a5K=s(["\uad8c\ub9ac\ud589\uc0ac\uc758 \uad6d\uba74\uc5d0\uc11c \uc2e0\uc758\uce59\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ubc1c\ud604\ub41c \ud30c\uc0dd \uc6d0\uce59\uc73c\ub85c \uc774\ud574\ub41c\ub2e4"],t.s)
