B.bAr=new A.a("gen_cl_source_12","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad00\uc2b5\ubc95\uc758 \ud6a8\ub825\uc774 \uc0ac\ud6c4\uc5d0 \ubd80\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.aDg,0,"\ud310\ub840\ub294 \uad00\uc2b5\ubc95\uc774 \uc0ac\ud68c\uc758 \uac70\ub4ed\ub41c \uad00\ud589\uc5d0 \uc758\ud558\uc5ec \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \uc131\ub9bd\ud558\uc9c0\ub9cc, \uc0ac\ud68c \uad6c\uc131\uc6d0\ub4e4\uc758 \ubc95\uc801 \ud655\uc2e0\uc774 \uc0c1\uc2e4\ub418\uc5b4 \uc804\uccb4 \ubc95\uc9c8\uc11c\uc5d0 \ubd80\ud569\ud558\uc9c0 \uc54a\uac8c \ub418\uc5c8\ub2e4\uba74 \ubc95\uc6d0\uc73c\ub85c\uc11c\uc758 \ud6a8\ub825\uc744 \uac00\uc9c8 \uc218 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4. \uc774\ub294 \uad00\uc2b5\ubc95\uc774 \uc0ac\ud68c \ubcc0\ud654\uc5d0 \ub530\ub77c \ub3d9\ud0dc\uc801\uc73c\ub85c \uadf8 \ud6a8\ub825\uc744 \uc0c1\uc2e4\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc900\ub2e4.",B.aOB,B.b53,null)
B.aWA=s(["\uccad\uc57d\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc774\ubbc0\ub85c \uccad\uc57d\uc790\uac00 \uc774\ub97c \uc784\uc758\ub85c \ucca0\ud68c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uccad\uc57d\uc790\uac00 \uccad\uc57d\uc5d0 \uc2b9\ub099\uae30\uac04\uc744 \uc815\ud55c \uacbd\uc6b0 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc2b9\ub099\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud558\uba74 \uccad\uc57d\uc740 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\uc2b9\ub099\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \uacc4\uc57d\uc758 \uccad\uc57d\uc740 \uccad\uc57d\uc790\uac00 \uc0c1\ub2f9\ud55c \uae30\uac04 \ub0b4\uc5d0 \uc2b9\ub099\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud558\uc5ec\ub3c4 \ud6a8\ub825\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4","\uaca9\uc9c0\uc790 \uac04\uc758 \uacc4\uc57d\uc740 \uc2b9\ub099\uc758 \ud1b5\uc9c0\uac00 \uccad\uc57d\uc790\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\uc5d0 \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.aTS=s(["\uc2b9\ub099\uae30\uac04\uc744 \uc815\ud55c \uacc4\uc57d\uc758 \uccad\uc57d\uc740 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc2b9\ub099\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
