B.bdI=new A.a("gen_cl_contractgen_1","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uc758 \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aWA,1,"\ubbfc\ubc95 \uc81c528\uc870 \uc81c1\ud56d\uc740 \uc2b9\ub099\uae30\uac04\uc744 \uc815\ud55c \uacc4\uc57d\uc758 \uccad\uc57d\uc740 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \uc2b9\ub099\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc2b9\ub099\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \uc0c1\ub2f9\ud55c \uae30\uac04 \ub0b4\uc5d0 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud558\uba74 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4(\uc81c529\uc870). \uaca9\uc9c0\uc790 \uac04 \uacc4\uc57d\uc740 \ubc1c\uc2e0\uc8fc\uc758\uc5d0 \ub530\ub77c \uc2b9\ub099\uc758 \ud1b5\uc9c0\ub97c \ubc1c\uc1a1\ud55c \ub54c\uc5d0 \uc131\ub9bd\ud55c\ub2e4(\uc81c531\uc870).",B.aTS,B.b7v,null)
B.a1g=s(["\uccad\uc57d\uc790\uac00 \uc2b9\ub099\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc54a\uace0 \ub300\ud654\uc790 \uac04\uc5d0 \uccad\uc57d\uc744 \ud55c \uacbd\uc6b0 \ub300\ud654\uac00 \uacc4\uc18d\ub418\ub294 \ub3d9\uc548 \uc2b9\ub099\uae30\uac04\uc774 \uc720\uc9c0\ub41c\ub2e4\uace0 \ubd04\uc774 \uc0c1\ub2f9\ud558\ub2e4","\uc5f0\ucc29\ub41c \uc2b9\ub099\uc740 \uccad\uc57d\uc790\uac00 \uc774\ub97c \uc0c8\ub85c\uc6b4 \uccad\uc57d\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4","\uc2b9\ub099\uc790\uac00 \uccad\uc57d\uc5d0 \ub300\ud558\uc5ec \uc870\uac74\uc744 \ubd99\uc774\uac70\ub098 \ubcc0\uacbd\uc744 \uac00\ud558\uc5ec \uc2b9\ub099\ud55c \ub54c\uc5d0\ub294 \uadf8 \uccad\uc57d\uc744 \uac70\uc808\ud558\uace0 \uc0c8\ub85c \uccad\uc57d\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\uccad\uc57d\uc790\uac00 \ubbf8\ub9ac \uc2b9\ub099\uae30\uac04 \ub0b4\uc5d0 \uc774\uc758\ub97c \ud558\uc9c0 \uc54a\uc73c\uba74 \uc2b9\ub099\uc73c\ub85c \ubcf8\ub2e4\ub294 \ub73b\uc744 \ud45c\uc2dc\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc774 \uc544\ubb34\ub7f0 \ubc18\uc751\uc774 \uc5c6\uc5b4\ub3c4 \uc2b9\ub099\uc774 \uc758\uc81c\ub41c\ub2e4"],t.s)
B.K0=s(["\ubcc0\uacbd\uc744 \uac00\ud55c \uc2b9\ub099\uc740 \uccad\uc57d\uc758 \uac70\uc808\uacfc \ub3d9\uc2dc\uc5d0 \uc0c8\ub85c\uc6b4 \uccad\uc57d\uc744 \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.b_U=s(["\ubcc0\uacbd\uc744 \uac00\ud55c \uc2b9\ub099","\uc5f0\ucc29\ub41c \uc2b9\ub099"],t.s)
B.bC_=new A.a("gen_cl_contractgen_2","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uccad\uc57d\uacfc \uc2b9\ub099\uc5d0 \uc758\ud55c \uacc4\uc57d \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a1g,3,"\ubbfc\ubc95 \uc81c534\uc870\ub294 \ubcc0\uacbd\uc744 \uac00\ud55c \uc2b9\ub099\uc740 \uccad\uc57d\uc758 \uac70\uc808\uacfc \ub3d9\uc2dc\uc5d0 \uc0c8\ub85c\uc6b4 \uccad\uc57d\uc744 \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c528\uc870\ub294 \uc5f0\ucc29\ub41c \uc2b9\ub099\uc744 \uccad\uc57d\uc790\uac00 \uc0c8\ub85c\uc6b4 \uccad\uc57d\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uccad\uc57d\uc790\uac00 \uc77c\ubc29\uc801\uc73c\ub85c \uc774\uc758\ubd80\uc81c\uae30 \uc2dc \uc2b9\ub099 \uc758\uc81c\ub97c \uc815\ud558\ub294 \uac83\uc740 \uc0c1\ub300\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc \uc790\uc720\ub97c \uce68\ud574\ud558\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uc2b9\ub099\uc73c\ub85c \uc758\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.K0,B.b_U,null)
B.an9=s(["\ub2f9\uc0ac\uc790 \uac04\uc5d0 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \uac00\uc9c4 \uccad\uc57d\uc774 \uc11c\ub85c \uad50\ucc28\ub41c \uacbd\uc6b0 \uc591 \uccad\uc57d\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\uc5d0 \uacc4\uc57d\uc774 \uc131\ub9bd\ud55c\ub2e4","\uad50\ucc28\uccad\uc57d\uc758 \uacbd\uc6b0 \uacc4\uc57d\uc740 \uc131\ub9bd\ud558\uc9c0 \uc54a\uace0 \ubcc4\ub3c4\uc758 \uc2b9\ub099\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uad50\ucc28\uccad\uc57d\uc740 \uccad\uc57d\uc790\uc640 \uc2b9\ub099\uc790\uc758 \uad6c\ubcc4\uc774 \uac00\ub2a5\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc131\ub9bd\ud55c\ub2e4","\uad50\ucc28\uccad\uc57d\uc5d0 \uc758\ud55c \uacc4\uc57d \uc131\ub9bd\uc2dc\uae30\ub294 \ub098\uc911\uc5d0 \ubc1c\uc1a1\ub41c \uccad\uc57d\uc758 \ubc1c\uc2e0\uc2dc\uc774\ub2e4"],t.s)
B.a2e=s(["\uc591 \uccad\uc57d\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\uc5d0 \uacc4\uc57d\uc774 \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.aLe=s(["\uad50\ucc28\uccad\uc57d","\uc81c533\uc870"],t.s)
B.bF2=new A.a("gen_cl_contractgen_3","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uad50\ucc28\uccad\uc57d\uc5d0 \uc758\ud55c \uacc4\uc57d \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.an9,0,"\ubbfc\ubc95 \uc81c533\uc870\ub294 \ub2f9\uc0ac\uc790 \uac04\uc5d0 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \uac00\uc9c4 \uccad\uc57d\uc774 \uc0c1\ud638 \uad50\ucc28\ub41c \uacbd\uc6b0\uc5d0\ub294 \uc591 \uccad\uc57d\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\uc5d0 \uacc4\uc57d\uc774 \uc131\ub9bd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uad50\ucc28\uccad\uc57d\uc740 \uccad\uc57d\uacfc \uc2b9\ub099\uc758 \uad6c\ubcc4 \uc5c6\uc774 \ub450 \uac1c\uc758 \uccad\uc57d\ub9cc\uc73c\ub85c \uc131\ub9bd\ud558\ub294 \ud2b9\uc218\ud55c \uacc4\uc57d\uc131\ub9bd \ubc29\uc2dd\uc774\ub2e4.",B.a2e,B.aLe,null)
B.aU1=s(["\uc758\uc0ac\uc2e4\ud604\uc740 \uc2b9\ub099\uc758 \ud1b5\uc9c0\uac00 \ud544\uc694 \uc5c6\ub294 \uad00\uc2b5\uc774 \uc788\uac70\ub098 \uccad\uc57d\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \uc2b9\ub099\uc758 \ud1b5\uc9c0\uac00 \ud544\uc694\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0 \uc778\uc815\ub41c\ub2e4","\uc758\uc0ac\uc2e4\ud604\uc740 \ubc18\ub4dc\uc2dc \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \uc778\uc815\ub41c\ub2e4","\uc758\uc0ac\uc2e4\ud604\uc5d0 \uc758\ud55c \uacc4\uc57d\uc740 \uc2b9\ub099\uc790\uac00 \uc2b9\ub099\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ubc1c\uc1a1\ud55c \ub54c \uc131\ub9bd\ud55c\ub2e4","\uc758\uc0ac\uc2e4\ud604\uc740 \ub099\uc131\uacc4\uc57d\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\uace0 \uc694\ubb3c\uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
