B.bga=new A.a("gen_cl_contractgen_5","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\ubbfc\ubc95 \uc81c535\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Ma,2,"\ubbfc\ubc95 \uc81c535\uc870 \uc81c2\ud56d\uc740 \uc0c1\ub300\ubc29\uc774 \uadf8 \ubd88\ub2a5\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubc30\uc0c1\ucc45\uc784\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc6d0\uc2dc\uc801\xb7\uac1d\uad00\uc801 \ubd88\ub2a5\uc73c\ub85c \uacc4\uc57d\uc774 \ubb34\ud6a8\uac00 \ub418\ub294 \uacbd\uc6b0 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\ucc45\uc784\uc73c\ub85c, \ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ucd08\uacfc\ud560 \uc218 \uc5c6\ub2e4.",B.atz,B.aN0,null)
B.aVR=s(["\uc774\ud589\uc774\uc775\uc744 \ud55c\ub3c4\ub85c \uc2e0\ub8b0\uc774\uc775\uc744 \ubc30\uc0c1\ud55c\ub2e4","\uc2e0\ub8b0\uc774\uc775\uc744 \ud55c\ub3c4\ub85c \uc774\ud589\uc774\uc775\uc744 \ubc30\uc0c1\ud55c\ub2e4","\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc744 \ubaa8\ub450 \uc804\uc561 \ubc30\uc0c1\ud55c\ub2e4","\ubc30\uc0c1\ubc94\uc704\uc5d0\ub294 \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.aCh=s(["\ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.S1=s(["\ubc30\uc0c1\ubc94\uc704","\uc774\ud589\uc774\uc775 \ud55c\ub3c4"],t.s)
B.bh1=new A.a("gen_cl_contractgen_6","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ubbfc\ubc95 \uc81c535\uc870\uc758 \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784\uc5d0\uc11c \ubc30\uc0c1\ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aVR,0,"\ud310\ub840\uc640 \ud1b5\uc124\uc740 \ubbfc\ubc95 \uc81c535\uc870\uc5d0 \ub530\ub77c \uc2e0\ub8b0\uc774\uc775\uc744 \ubc30\uc0c1\ud558\ub418 \uadf8 \ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \uc774\ud589\uc774\uc775\uc774 \ubc30\uc0c1\uc561\uc758 \uc0c1\ud55c\uc774 \ub418\ub294 \uad6c\uc870\uc774\ub2e4. \uc774\ub294 \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc73c\ub85c \uacc4\uc57d\uc774 \uc560\ucd08\uc5d0 \ubb34\ud6a8\uc600\ub2e4\ub294 \uc810\uc744 \uace0\ub824\ud55c \uc81c\ud55c\uc774\ub2e4.",B.aCh,B.S1,null)
B.ar0=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc740 \uc0c1\ub300\ubc29\uc774 \uadf8 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud560 \ub54c\uae4c\uc9c0 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \ub54c\uc5d0\ub3c4 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \uace4\ub780\ud560 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\uc790\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b4w=s(["\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc2ec\ub9ac\xb7\ud310\ub2e8\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \ubcf8\ub2e4"],t.s)
B.aYG=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c","\uc9c1\uad8c\uc870\uc0ac"],t.s)
B.biF=new A.a("gen_cl_contractgen_7","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ar0,3,"\ud310\ub840\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \uc874\uc7ac \uc790\uccb4\ub294 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc2ec\ub9ac\xb7\ud310\ub2e8\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \ubcf8\ub2e4(\ub2e4\ub9cc \ud589\uc0ac \uc5ec\ubd80\ub294 \ubcc4\uac1c). \ubbfc\ubc95 \uc81c536\uc870 \uc81c1\ud56d\uc740 \uc30d\ubb34\uacc4\uc57d\uc0c1 \uacac\ub828\uad00\uacc4\uc5d0 \ub530\ub978 \uc774\ud589\uac70\uc808\uad8c\uc744 \uaddc\uc815\ud558\uace0, \ub3d9\uc870 \uc81c2\ud56d\uc740 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc744 \uaddc\uc815\ud55c\ub2e4. \ud56d\ubcc0\uad8c \uc788\ub294 \ucc44\ubb34\uc790\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.",B.b4w,B.aYG,null)
B.TI=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\ub294 \uc0c1\uacc4\ud560 \uc218 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\uc5d0\uac8c \uc774\ud589\uc744 \uccad\uad6c\ud558\ub294 \uc18c\uc1a1\uc5d0\uc11c \ubc95\uc6d0\uc740 \uc0c1\ud658\uae09\ubd80\ud310\uacb0\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \ucc44\uad8c \uc790\uccb4\uac00 \uc18c\uba78\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\ubb34\uc790\uac00 \uc6d0\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2f9\uc5f0\ud788 \uc774\ud589\uc9c0\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc808\ub300\uc801 \ud6a8\ub825\ub9cc \uc788\ub2e4"],t.s)
B.a05=s(["\uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
