B.bdF=new A.a("gen_cl_contractgen_8","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.TI,1,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\uc758 \uc774\ud589\uccad\uad6c \uc18c\uc1a1\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \ubc95\uc6d0\uc740 \ub2e8\uc21c\uccad\uad6c\uae30\uac01\uc774 \uc544\ub2c8\ub77c \uc6d0\uace0\uc758 \uc774\ud589\uacfc \uc0c1\ud658\uc73c\ub85c \uc774\ud589\ud560 \uac83\uc744 \uba85\ud558\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4. \ud56d\ubcc0\uad8c \uc788\ub294 \ucc44\uad8c\uc740 \uc0c1\uacc4\uac00 \uc81c\ud55c\ub418\uba70, \ud56d\ubcc0\uad8c\uc740 \uc6d0\uc6a9\uc774 \uc788\uc5b4\uc57c \uc18c\uc1a1\uc0c1 \uace0\ub824\ub41c\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574\uc774\ub2e4.",B.a05,B.arZ,null)
B.a7y=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34","\uc784\ub300\ucc28 \uc885\ub8cc \ud6c4 \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \uc5f0\uccb4\ucc28\uc784 \uacf5\uc81c \ud6c4 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub9cc \uc788\uace0 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uac00 \uc120\uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4","\ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc544\ub2c8\ub2e4","\uac00\uc555\ub958\ub4f1\uae30\uac00 \uc788\ub294 \ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\ub294 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uc640 \uacb0\ucf54 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.anV=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubbfc\ubc95 \uc81c549\uc870\uc5d0 \uc758\ud574 \uc900\uc6a9\ub418\ub294 \uc81c536\uc870\uc5d0 \ub530\ub77c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.axI=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34","\ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bqz=new A.a("gen_cl_contractgen_9","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.a7y,0,"\ud310\ub840\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubbfc\ubc95 \uc81c549\uc870\uc5d0 \uc758\ud574 \uc900\uc6a9\ub418\ub294 \uc81c536\uc870\uc5d0 \ub530\ub77c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub3c4 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc774\uba70, \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc774\ub2e4.",B.anV,B.axI,null)
B.atx=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\uac00 \uc801\uc6a9\ub41c\ub2e4","\uc704\ud5d8\ubd80\ub2f4 \uaddc\uc815\uc740 \uc784\uc758\uaddc\uc815\uc774 \uc544\ub2c8\ub77c \uac15\ud589\uaddc\uc815\uc774\ub2e4","\uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\uad8c\uc790\uac00 \ubc18\ub300\uae09\ubd80\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.alg=s(["\ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80, \uc989 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\ub97c \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aVe=s(["\ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758","\uc81c537\uc870"],t.s)
B.bjj=new A.a("gen_cl_contractgen_10","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc704\ud5d8\ubd80\ub2f4(\ubbfc\ubc95 \uc81c537\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.atx,0,"\ubbfc\ubc95 \uc81c537\uc870\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80, \uc989 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\ub97c \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \ub2f9\uc0ac\uc790 \uac04 \ud2b9\uc57d\uc73c\ub85c \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4.",B.alg,B.aVe,null)
B.aHM=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \ucc44\uad8c\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911\uc5d0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \ub54c\uc5d0\ub3c4 \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\ucc44\ubb34\uc790\uac00 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc774\uc775\uc744 \uc5bb\uc740 \ub54c\uc5d0\ub294 \uc774\ub97c \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucc44\uad8c\uc790\uadc0\ucc45\uc0ac\uc720\ub85c \uc778\ud55c \uc704\ud5d8\ubd80\ub2f4\uc758 \uacbd\uc6b0 \ucc44\ubb34\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\uc775\uc0c1\ud658\uc758\ubb34\ub97c \uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Vu=s(["\ucc44\ubb34\uc790\uac00 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc774\uc775\uc740 \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
