B.bvL=new A.a("gen_cl_contractgen_11","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ubbfc\ubc95 \uc81c538\uc870 \ucc44\uad8c\uc790\uadc0\ucc45\uc0ac\uc720\uc5d0 \uc758\ud55c \uc704\ud5d8\ubd80\ub2f4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aHM,3,"\ubbfc\ubc95 \uc81c538\uc870 \uc81c1\ud56d\uc740 \ucc44\uad8c\uc790\uc758 \uadc0\ucc45\uc0ac\uc720 \ub610\ub294 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29 \ubb34\ucc45\uc758 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub3d9\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucc44\ubb34\uc790\uac00 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc774\uc775\uc740 \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.Vu,B.agK,null)
B.aSj=s(["\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uae09\ubd80\uac00 \ubd88\ub2a5\uc774 \ub418\uc5b4\ub3c4 \ucc44\ubb34\uc790\ub294 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud55c\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uae09\ubd80\uac00 \ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\uccad\uad6c\uad8c\uc744 \uc0c1\uc2e4\ud558\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \uc704\ud5d8\ubd80\ub2f4\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911\uc5d0\ub294 \ucc44\ubb34\uc790\uc758 \uace0\uc758\xb7\uc911\uacfc\uc2e4\ub85c \uc778\ud55c \ubd88\ub2a5\uc774\ub77c\ub3c4 \ucc44\uad8c\uc790\uac00 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.aPl=s(["\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc774 \uacbd\uc6b0 \uc704\ud5d8\uc774 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ub428\uc744 \uc815\ud558\uace0 \uc788\ub2e4"],t.s)
B.a5t=s(["\ucc44\uad8c\uc790\uc9c0\uccb4","\uc704\ud5d8\uc774\uc804"],t.s)
B.bgR=new A.a("gen_cl_contractgen_12","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc704\ud5d8\ubd80\ub2f4\uacfc \uad00\ub828\ud558\uc5ec \uc30d\ubb34\uacc4\uc57d\uc0c1 \uc77c\ubc29\uc758 \uae09\ubd80\uac00 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ubc1c\uc0dd\ud55c \ubd88\ub2a5\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.aSj,1,"\ubbfc\ubc95 \uc81c538\uc870 \uc81c1\ud56d \ud6c4\ub2e8\uc740 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc774 \uacbd\uc6b0 \uc704\ud5d8\uc774 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ub428\uc744 \uc815\ud558\uace0 \uc788\ub2e4. \ub530\ub77c\uc11c \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\uccad\uad6c\uad8c\uc744 \uc0c1\uc2e4\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aPl,B.a5t,null)
B.ayU=s(["\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc740 \uc694\uc57d\uc790\uc640 \ub099\uc57d\uc790 \uc0ac\uc774\uc758 \uacc4\uc57d\uc73c\ub85c \uc131\ub9bd\ud558\uba70 \uc81c3\uc790\uc758 \ub3d9\uc758\ub294 \uacc4\uc57d\uc131\ub9bd \uc694\uac74\uc774 \uc544\ub2c8\ub2e4","\uc81c3\uc790\uc758 \uad8c\ub9ac\ub294 \uadf8 \uc81c3\uc790\uac00 \ub099\uc57d\uc790\uc5d0 \ub300\ud558\uc5ec \uacc4\uc57d\uc758 \uc774\uc775\uc744 \ubc1b\uc744 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \ub54c\uc5d0 \uc0dd\uae34\ub2e4","\uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uae30 \uc804\uc5d0\ub294 \ub099\uc57d\uc790\uc640 \uc694\uc57d\uc790\ub294 \uadf8 \uacc4\uc57d\uc744 \ubcc0\uacbd \ub610\ub294 \uc18c\uba78\uc2dc\ud0ac \uc218 \uc5c6\ub2e4","\ub099\uc57d\uc790\ub294 \uc694\uc57d\uc790\uc640\uc758 \uacc4\uc57d\uc5d0 \uae30\ud55c \ud56d\ubcc0\uc73c\ub85c \uadf8 \uacc4\uc57d\uc758 \uc774\uc775\uc744 \ubc1b\uc744 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aa5=s(["\uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc(\uc81c539\uc870 \uc81c2\ud56d)\ub97c \ud55c \ud6c4\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uacc4\uc57d\uc744 \ubcc0\uacbd\ud558\uac70\ub098 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.av3=s(["\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d","\uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc","\ubcc0\uacbd\uae08\uc9c0"],t.s)
B.bHt=new A.a("gen_cl_contractgen_13","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d(\ubbfc\ubc95 \uc81c539\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ayU,2,"\ubbfc\ubc95 \uc81c541\uc870\ub294 \uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc(\uc81c539\uc870 \uc81c2\ud56d)\ub97c \ud55c \ud6c4\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uacc4\uc57d\uc744 \ubcc0\uacbd\ud558\uac70\ub098 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubc18\ub300\ub85c \ud574\uc11d\ud558\uba74 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc \uc804\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uc790\uc720\ub86d\uac8c \uacc4\uc57d\uc744 \ubcc0\uacbd\xb7\uc18c\uba78\uc2dc\ud0ac \uc218 \uc788\ub2e4. \ub099\uc57d\uc790\ub294 \uc81c542\uc870\uc5d0 \ub530\ub77c \uc694\uc57d\uc790\uc5d0 \ub300\ud55c \ud56d\ubcc0\uc73c\ub85c \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4.",B.aa5,B.av3,null)
B.aab=s(["\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc788\uc73c\uba74 \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc774 \ud574\uc81c\ub41c \uacbd\uc6b0 \ub099\uc57d\uc790\ub294 \uc774\ubbf8 \uc81c3\uc790\uc5d0\uac8c \uae09\ubd80\ud55c \uac83\uc744 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \uc81c3\uc790\uc5d0\uac8c \ubc18\ud658\uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc5d0 \ub300\ud55c \uacc4\uc57d\uc0c1 \uad8c\ub9ac\ub97c \uc804\ud600 \uac16\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aUf=s(["\uc694\uc57d\uc790\ub294 \uacc4\uc57d\ub2f9\uc0ac\uc790\ub85c\uc11c \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aRe=s(["\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc758 \ud574\uc81c","\ud574\uc81c\uad8c\uc790"],t.s)
B.byn=new A.a("gen_cl_contractgen_14","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc5d0\uc11c \uc694\uc57d\uc790\uc758 \ub099\uc57d\uc790\uc5d0 \ub300\ud55c \uacc4\uc57d\ud574\uc81c\uad8c \ud589\uc0ac\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.aab,1,"\ud310\ub840\ub294 \uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790\uc778 \uc694\uc57d\uc790\ub294 \uacc4\uc57d\ub2f9\uc0ac\uc790\ub85c\uc11c \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \ub2e4\ub9cc \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc740 \uacc4\uc57d\ub2f9\uc0ac\uc790\uc778 \uc694\uc57d\uc790\uc640 \ub099\uc57d\uc790 \uc0ac\uc774\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\uace0, \ub099\uc57d\uc790\ub294 \uc774\ubbf8 \uae09\ubd80\ubc1b\uc740 \uc81c3\uc790\uc5d0\uac8c \uc9c1\uc811 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc774\ub2e4.",B.aUf,B.aRe,null)
B.aEE=s(["\uacc4\uc57d\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \uadf8 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\uacc4\uc57d\ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud558\ub824\uba74 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uacc4\uc57d\ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uad8c\uc740 \ucc44\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c\uc11c \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.axb=s(["\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba70"],t.s)
B.aSl=s(["\ud574\uc81c\uad8c\uc758 \ubc95\uc801\uc131\uc9c8","\ud615\uc131\uad8c"],t.s)
B.bhV=new A.a("gen_cl_contractgen_15","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uc758 \ud574\uc81c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c543\uc870\uc758 \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEE,0,"\ubbfc\ubc95 \uc81c543\uc870\ub294 \uacc4\uc57d \ub610\ub294 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ub2f9\uc0ac\uc790\uc758 \uc77c\ubc29\uc774 \ud574\uc81c\uad8c\uc744 \uac00\uc9c4 \uacbd\uc6b0 \uadf8 \ud574\uc81c\ub294 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba70, \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\uc81c111\uc870 \ub3c4\ub2ec\uc8fc\uc758).",B.axb,B.aSl,null)
B.azl=s(["\ub2f9\uc0ac\uc790\uc758 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0\uc5d0 \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \uc774\ub97c \ud560 \uc218 \uc788\ub2e4","\ub2f9\uc0ac\uc790\uac00 \uc218\uc778\uc778 \uacbd\uc6b0 \uac01\uc790\uac00 \uc790\uc2e0\uc758 \uc9c0\ubd84\uc5d0 \ub300\ud558\uc5ec\ub9cc \uac1c\ubcc4\uc801\uc73c\ub85c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \uc784\uc758\uaddc\uc815\uc774 \uc544\ub2c8\ub77c \ub2f9\uc0ac\uc790\uac00 \ubc30\uc81c\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815\uc774\ub2e4","\ud574\uc81c\uad8c\uc774 \ub2f9\uc0ac\uc790 1\uc778\uc5d0 \ub300\ud558\uc5ec \uc18c\uba78\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e4\ub978 \ub2f9\uc0ac\uc790\uc5d0 \ub300\ud55c \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aRY=s(["\uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc744 \uc815\ud558\uace0 \uc788\ub2e4"],t.s)
B.aje=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131","\uc81c547\uc870"],t.s)
B.bAn=new A.a("gen_cl_contractgen_16","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131(\ubbfc\ubc95 \uc81c547\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.azl,0,"\ubbfc\ubc95 \uc81c547\uc870 \uc81c1\ud56d\uc740 \ub2f9\uc0ac\uc790\uc758 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc744 \uc815\ud558\uace0 \uc788\ub2e4. \ub3d9\uc870 \uc81c2\ud56d\uc740 \ud574\uc81c\uad8c\uc774 \ub2f9\uc0ac\uc790 1\uc778\uc5d0 \ub300\ud558\uc5ec \uc18c\uba78\ud55c \ub54c\uc5d0\ub294 \ub2e4\ub978 \uc790\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aRY,B.aje,null)
B.aGj=s(["\uacc4\uc57d\uc774 \ud574\uc81c\ub41c \ub54c\uc5d0\ub294 \uac01 \ub2f9\uc0ac\uc790\ub294 \uadf8 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \uc6d0\uc0c1\ud68c\ubcf5\uc758 \uc758\ubb34\uac00 \uc788\uc73c\ub098 \uc81c3\uc790\uc758 \uad8c\ub9ac\ub97c \ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4","\uc5ec\uae30\uc11c \uc81c3\uc790\ub780 \ud574\uc81c\ub41c \uacc4\uc57d\uc73c\ub85c\ubd80\ud130 \uc0dd\uae34 \ubc95\ub960\ud6a8\uacfc\ub97c \uae30\ucd08\ub85c \ud558\uc5ec \ud574\uc81c \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \uc774\ud574\uad00\uacc4\ub97c \ucde8\ub4dd\ud55c \uc790\ub97c \ub9d0\ud55c\ub2e4","\ud574\uc81c \uc804 \uc81c3\uc790\ub294 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ubcf4\ud638\ub418\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4","\ud574\uc81c \ud6c4 \ub4f1\uae30\ub97c \ub9c8\uce58\uc9c0 \uc54a\uc740 \ucc44 \uc0c8\ub85c \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub294 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc758 \uc81c3\uc790\ub85c\uc11c \uc5b8\uc81c\ub098 \ubcf4\ud638\ub41c\ub2e4"],t.s)
B.aYv=s(["\ud310\ub840\ub294 \ud574\uc81c \uc804\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ucde8\ub4dd\ud55c \uc81c3\uc790\ub294 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ubcf4\ud638\ub41c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.afy=s(["\ud574\uc81c\uc758 \uc81c3\uc790 \ubcf4\ud638","\uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c"],t.s)
B.bkA=new A.a("gen_cl_contractgen_17","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\ud574\uc81c\uc758 \ud6a8\uacfc \uc911 \uc81c3\uc790 \ubcf4\ud638(\ubbfc\ubc95 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aGj,3,"\ubbfc\ubc95 \uc81c548\uc870 \uc81c1\ud56d\uc740 \ud574\uc81c\uc758 \uc18c\uae09\ud6a8\ub85c\ubd80\ud130 \uc81c3\uc790\uc758 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uba70, \ud310\ub840\ub294 \ud574\uc81c \uc804\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ucde8\ub4dd\ud55c \uc81c3\uc790\ub294 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ubcf4\ud638\ub41c\ub2e4\uace0 \ubcf8\ub2e4. \ub2e4\ub9cc \ud574\uc81c \ud6c4 \ub9d0\uc18c\ub4f1\uae30 \uc804\uc5d0 \uc0c8\ub85c \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \uc120\uc758\uc778 \uacbd\uc6b0\uc5d0\ub9cc \ubcf4\ud638\ub418\uace0, \uc5b8\uc81c\ub098 \ubcf4\ud638\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aYv,B.afy,null)
B.auj=s(["\ud574\uc81c\uc5d0 \uc758\ud558\uc5ec \uacc4\uc57d\uc740 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud558\uace0, \ubbf8\uc774\ud589\ucc44\ubb34\ub294 \uc18c\uba78\ud558\uba70 \uc774\ubbf8 \uc774\ud589\ub41c \uae09\ubd80\ub294 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\ub418\uc5b4\uc57c \ud558\ub098 \uc81c548\uc870\uc5d0 \ub530\ub77c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub85c \ucc98\ub9ac\ub41c\ub2e4","\ud574\uc81c\ub294 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud6a8\ub825\uc774 \uc788\uace0 \uacc4\uc57d\uad00\uacc4\ub294 \uccad\uc0b0\uad00\uacc4\ub85c \uc804\ud658\ub41c\ub2e4","\ud574\uc81c\ub294 \uacc4\uc57d\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\uc9c0 \uc54a\uace0 \uc0c8\ub85c\uc6b4 \ubc18\ud658\ucc44\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \uc77c\uc885\uc774\ub2e4","\ud574\uc81c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud558\uc5ec \ud310\ub840\ub294 \uccad\uc0b0\uad00\uacc4\uc124\uc744 \ucde8\ud558\uc5ec \uc18c\uae09\ud6a8\ub97c \ubd80\uc815\ud55c\ub2e4"],t.s)
B.aoU=s(["\ud310\ub840\uc640 \ub2e4\uc218\uc124\uc740 \ud574\uc81c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud558\uc5ec \uc9c1\uc811\ud6a8\uacfc\uc124\uc744 \ucde8\ud558\uc5ec, \ud574\uc81c\ub85c \uacc4\uc57d\uc740 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\ud558\uace0"],t.s)
