B.bDG=new A.a("gen_cl_contractgen_18","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\ud574\uc81c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \ud559\uc124 \uc911 \ud310\ub840\uac00 \ucde8\ud558\ub294 \uc9c1\uc811\ud6a8\uacfc\uc124\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.auj,0,"\ud310\ub840\uc640 \ub2e4\uc218\uc124\uc740 \ud574\uc81c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud558\uc5ec \uc9c1\uc811\ud6a8\uacfc\uc124\uc744 \ucde8\ud558\uc5ec, \ud574\uc81c\ub85c \uacc4\uc57d\uc740 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\ud558\uace0 \uc544\uc9c1 \uc774\ud589\ub418\uc9c0 \uc54a\uc740 \ucc44\ubb34\ub294 \uc774\ud589\ud560 \ud544\uc694\uac00 \uc5c6\uc73c\uba70 \uc774\ubbf8 \uc774\ud589\ud55c \uae09\ubd80\ub294 \ubbfc\ubc95 \uc81c548\uc870\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \ub530\ub77c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.aoU,B.atZ,null)
B.a6W=s(["\uae08\uc804\uc744 \ubc18\ud658\ud560 \ub54c\uc5d0\ub294 \uadf8 \ubc1b\uc740 \ub0a0\ub85c\ubd80\ud130 \uc774\uc790\ub97c \uac00\uc0b0\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ubbc0\ub85c \ud574\uc81c\uc640 \ub3d9\uc2dc\uc5d0 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc73c\ub85c \ubc18\ud658\ud560 \uae08\uc804\uc5d0\ub294 \uc774\uc790\ub97c \uac00\uc0b0\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uc758\ubb34\uc640 \uc804\ud600 \ub2e4\ub978 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ubbc0\ub85c \uc774\uc790 \uac00\uc0b0 \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
