B.bd7=new A.a("gen_cl_contractgen_21","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \uacc4\uc57d\ud574\uc81c(\ubbfc\ubc95 \uc81c544\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aCq,2,"\ubbfc\ubc95 \uc81c545\uc870\ub294 \uacc4\uc57d\uc758 \uc131\uc9c8 \ub610\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \uc77c\uc815\ud55c \uc2dc\uc77c \ub610\ub294 \uc77c\uc815\ud55c \uae30\uac04 \ub0b4\uc5d0 \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uc815\uae30\ud589\uc704\uc758 \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc740 \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c544\uc870\ub294 \uc774\ud589\uc9c0\uccb4 \uc2dc \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\ub97c \uc694\uad6c\ud558\ub418, \ubbf8\ub9ac \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \uacbd\uc6b0(\ub2e8\uc11c)\uc5d0\ub294 \ucd5c\uace0\uac00 \ubd88\ud544\uc694\ud558\ub2e4.",B.asr,B.OK,null)
B.aYx=s(["\ucc44\ubb34\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\uad8c\uc790\ub294 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc774\ud589\ubd88\ub2a5\uc73c\ub85c \uc778\ud55c \ud574\uc81c\ub294 \ucd5c\uace0 \uc5c6\uc774\ub294 \ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\ubd88\ub2a5\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ucd5c\uace0\ud55c \ud6c4\uc5d0\ub9cc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud55c \ud574\uc81c\ub294 \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
