B.bqW=new A.a("gen_cl_contractgen_22","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud55c \uacc4\uc57d\ud574\uc81c(\ubbfc\ubc95 \uc81c546\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aYx,0,"\ubbfc\ubc95 \uc81c546\uc870\ub294 \ucc44\ubb34\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\uad8c\uc790\ub294 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ud589\uc9c0\uccb4\uc640 \ub2ec\ub9ac \uc774\ud589\ubd88\ub2a5\uc758 \uacbd\uc6b0\uc5d0\ub294 \ucd5c\uace0\ub97c \uc694\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uace7\ubc14\ub85c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc774\ub2e4.",B.a53,B.b0W,null)
B.Og=s(["\ud574\uc81c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc740 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ud574\uc81c\uad8c\ud589\uc0ac \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ud574\uc81c\uad8c\uc790\uc5d0\uac8c \ucd5c\uace0\ud560 \uc218 \uc788\uace0, \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud574\uc81c\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ud574\uc81c\uad8c\uc740 \ud589\uc0ac\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc601\uad6c\ud788 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ud574\uc81c\uad8c\uc790\uac00 \uce68\ubb35\ud558\uba74 \ud574\uc81c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ud574\uc81c\uad8c\uc740 \ucd5c\uace0\uc640 \ubb34\uad00\ud558\uac8c \ubc1c\uc0dd\uc77c\ub85c\ubd80\ud130 10\ub144\uc774 \uacbd\uacfc\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\ub85c \uc18c\uba78\ud55c\ub2e4"],t.s)
B.Sz=s(["\uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud574\uc81c\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
