B.bEh=new A.a("gen_cl_contractgen_23","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c552\uc870(\ucd5c\uace0\uad8c)\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Og,0,"\ubbfc\ubc95 \uc81c552\uc870\ub294 \ud574\uc81c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0 \uc0c1\ub300\ubc29\uc740 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ud574\uc81c\uad8c \ud589\uc0ac \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ud574\uc81c\uad8c\uc790\uc5d0\uac8c \ucd5c\uace0\ud560 \uc218 \uc788\uace0, \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud574\uc81c\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc0c1\ub300\ubc29\uc744 \ubd88\ud655\uc815\ud55c \ubc95\ub960\uad00\uacc4\ub85c\ubd80\ud130 \ubc97\uc5b4\ub098\uac8c \ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4.",B.Sz,B.Pe,null)
B.aLl=s(["\ud574\uc81c\uad8c\uc758 \ud589\uc0ac\uc5d0 \uc788\uc5b4\uc11c \uc0c1\ub300\ubc29\uc73c\ub85c\ubd80\ud130 \ubc18\ud658\ubc1b\uc744 \ubb3c\uac74\uc774 \ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c \ub610\ub294 \uac00\uacf5\uc774\ub098 \uac1c\uc870\ub85c \uc778\ud558\uc5ec \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ubaa9\uc801\ubb3c\uc758 \ud6fc\uc190 \uc5ec\ubd80\ub294 \ud574\uc81c\uad8c \uc18c\uba78\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc790\uc758 \uacbd\uacfc\uc2e4\ub85c \ubaa9\uc801\ubb3c\uc774 \uba78\uc2e4\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c \uc18c\uba78\uc0ac\uc720\ub294 \uc624\uc9c1 \uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0 \uc758\ud55c \uacbd\uc6b0\ubfd0\uc774\ub2e4"],t.s)
B.axp=s(["\ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc774 \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub418\uac70\ub098 \uac00\uacf5\xb7\uac1c\uc870\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
