B.beR=new A.a("gen_cl_contractgen_24","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc0ac\uc720(\ubbfc\ubc95 \uc81c553\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aLl,0,"\ubbfc\ubc95 \uc81c553\uc870\ub294 \ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc774 \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub418\uac70\ub098 \uac00\uacf5\xb7\uac1c\uc870\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ud574\uc81c\uad8c\uc790\uac00 \uc6d0\uc0c1\ud68c\ubcf5\uc744 \uc2a4\uc2a4\ub85c \ubd88\uac00\ub2a5\ud558\uac8c \ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c \ud589\uc0ac\ub97c \uc81c\ud55c\ud558\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.axp,B.PE,null)
B.b1O=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\uacc4\uc57d\uc758 \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\ub97c \uac00\uc9c0\ubbc0\ub85c \uc774\ubbf8 \uc774\ud589\ub41c \uae09\ubd80\ub3c4 \ubaa8\ub450 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\uace0 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.RI=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
