B.brX=new A.a("gen_cl_contractgen_25","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uc758 \ud574\uc9c0(\ubbfc\ubc95 \uc81c550\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b1O,0,"\ubbfc\ubc95 \uc81c550\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9\xb7\uc704\uc784 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \uc778\uc815\ub418\ub294 \uac83\uc73c\ub85c, \ud574\uc81c\uc640 \ub2ec\ub9ac \uc18c\uae09\ud6a8\uac00 \uc5c6\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \uc544\ub2cc \uccad\uc0b0\uad00\uacc4\ub9cc \ubc1c\uc0dd\ud55c\ub2e4.",B.RI,B.aC4,null)
B.agE=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uacc4\uc57d\uc774 \ucc98\uc74c\ubd80\ud130 \uc5c6\uc5c8\ub358 \uac83\uacfc \uac19\uc740 \uc0c1\ud0dc\ub85c \ub418\ub098, \ud574\uc9c0\ub294 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ud574\uc81c\ub294 \uc77c\uc2dc\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c, \ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c \uc8fc\ub85c \ubb38\uc81c\ub41c\ub2e4","\ud574\uc81c\uc758 \uacbd\uc6b0 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub098, \ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub294 \uccad\uc0b0\uc758\ubb34\ub9cc \ubb38\uc81c\ub420 \ubfd0 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uc640 \ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.aiU=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \ubc18\uba74 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uccad\uc0b0\uad00\uacc4\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
