B.brs=new A.a("gen_cl_contractgen_26","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uc640 \ud574\uc9c0\uc758 \ucc28\uc774\uc810\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agE,3,"\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \ubc18\uba74 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uccad\uc0b0\uad00\uacc4\ub9cc \ubb38\uc81c\ub41c\ub2e4. \ub2e4\ub9cc \ubbfc\ubc95 \uc81c551\uc870\ub294 \ud574\uc81c\ubfd0 \uc544\ub2c8\ub77c \uc81c550\uc870\uac00 \uc900\uc6a9\ud558\ub294 \ubc14\uc5d0 \ub530\ub77c \ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc544 \uc774 \ubd80\ubd84\uc740 \ud574\uc81c\xb7\ud574\uc9c0\uac00 \uacf5\ud1b5\ub41c\ub2e4. \ub530\ub77c\uc11c \ud574\uc81c\uc640 \ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc11c\uc220 \uc790\uccb4\ub294 \uc633\uc73c\ub098, \ubb38\ud56d\uc740 \ucc28\uc774\uc810\uc744 \ubb3b\ub294 \uac83\uc774\ubbc0\ub85c \uc774\ub294 \ucc28\uc774\uc810\uc774 \uc544\ub2cc \uacf5\ud1b5\uc810\uc5d0 \ud574\ub2f9\ud558\uc5ec \uc624\ub2f5\uc774\ub2e4.",B.aiU,B.aGp,null)
B.ZZ=s(["\ud574\uc81c\uc870\uac74\uc740 \uc870\uac74\uc131\ucde8\ub85c \ub2f9\uc5f0\ud788 \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud558\ub294 \uac83\uc774\ub098, \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \ud574\uc81c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \ubaa8\ub450 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uc774 \uc131\ucde8\ub418\uc5b4\ub3c4 \ubcc4\ub3c4\ub85c \ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc5ec\uc57c \uacc4\uc57d\uc774 \uc18c\uba78\ud55c\ub2e4","\uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uc870\uac74\uc131\ucde8\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.aCF=s(["\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \ubbfc\ubc95 \uc81c147\uc870\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \uc131\ucde8\ub41c \ub54c\ub85c\ubd80\ud130 \ub2f9\uc5f0\ud788 \uadf8 \ud6a8\ub825\uc744 \uc783\ub294 \ubc18\uba74"],t.s)
