B.bmt=new A.a("gen_cl_capacity_6","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ud53c\ud2b9\uc815\ud6c4\uacac\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSB,2,"\ubbfc\ubc95 \uc81c14\uc870\uc7582\uc5d0 \ub530\ub77c \ud2b9\uc815\ud6c4\uacac\uc740 \uc77c\uc2dc\uc801 \ud6c4\uc6d0 \ub610\ub294 \ud2b9\uc815 \uc0ac\ubb34\uc5d0 \uad00\ud55c \ud6c4\uc6d0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0 \ub300\ud574 \uac1c\uc2dc\ub418\uba70 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \ud560 \uc218 \uc5c6\ub2e4. \ud2b9\uc815\ud6c4\uacac\uc740 \uc131\ub144\ud6c4\uacac\xb7\ud55c\uc815\ud6c4\uacac\uacfc \ub2ec\ub9ac \ubcf8\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \uc81c\ud55c\ud558\uc9c0 \uc54a\uace0, \uac00\uc815\ubc95\uc6d0\uc740 \ud2b9\uc815\ud6c4\uacac\uc758 \uae30\uac04 \ub610\ub294 \uc0ac\ubb34\uc758 \ubc94\uc704\ub97c \uc815\ud558\uc5ec\uc57c \ud55c\ub2e4(\uc81c14\uc870\uc7582 \uc81c3\ud56d).",B.b_J,B.Tb,null)
B.asd=s(["\uc0c1\ub300\ubc29\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub2a5\ub825\uc790\uac00 \ub41c \ud6c4 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc544\uc9c1 \ub2a5\ub825\uc790\uac00 \ub418\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4.","\ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uc740 \uc790\uac00 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud2b9\ubcc4\ud55c \uc808\ucc28\ub97c \uc694\ud558\ub294 \ud589\uc704\uc5d0 \ub300\ud574 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ubc1f\uc740 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4."],t.s)
