B.bCF=new A.a("gen_cl_capacity_19","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc0ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\ubcc0\uacbd \ubc0f \uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ZR,0,"\ubbfc\ubc95 \uc81c73\uc870 \uc81c1\ud56d\uc740 \uac01 \uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc740 \ud3c9\ub4f1\ud55c \uac83\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8\uc5d0 \ub530\ub97c \uc218 \uc788\ub2e4. \ub3d9\uc870 \uc81c2\ud56d\uc740 \uc0ac\uc6d0\uc740 \uc11c\uba74\uc774\ub098 \ub300\ub9ac\uc778\uc73c\ub85c \uacb0\uc758\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c75\uc870\ub294 \ucd1d\ud68c \uacb0\uc758\ub294 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uc0ac\uc6d0 \uacfc\ubc18\uc218\uc758 \ucd9c\uc11d\uacfc \ucd9c\uc11d\uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc758 \uacfc\ubc18\uc218\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.a8c,B.b2T,null)
