B.bkn=new A.a("gen_cl_realright_3","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubbfc\ubc95 \uc81c187\uc870\uc5d0 \ub530\ub77c \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ubb3c\uad8c\uc744 \ucde8\ub4dd\ud558\ub294 \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.axj,3,"\ubbfc\ubc95 \uc81c187\uc870\ub294 \uc0c1\uc18d, \uacf5\uc6a9\uc9d5\uc218, \ud310\uacb0, \uacbd\ub9e4 \uae30\ud0c0 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud55c \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ucde8\ub4dd\uc740 \ub4f1\uae30\ub97c \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc774\ub97c \ucc98\ubd84\ud558\ub824\uba74 \ub4f1\uae30\ud558\uc5ec\uc57c \ud55c\ub2e4. \ub9e4\ub9e4\uacc4\uc57d\uc740 \ubc95\ub960\ud589\uc704\uc774\ubbc0\ub85c \uc81c186\uc870\uc5d0 \ub530\ub77c \ub4f1\uae30\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4.",B.a9I,B.NP,null)
B.ank=s(["\uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\ud6a8\uc774\ub2e4.","\uc774\ubbf8 \uacbd\ub8cc\ub41c \uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\ub294 \uad00\uacc4 \ub2f9\uc0ac\uc790 \uc804\uc6d0\uc758 \ud569\uc758\uac00 \uc5c6\uc73c\uba74 \ud56d\uc0c1 \ubb34\ud6a8\ub85c \ucc98\ub9ac\ub41c\ub2e4.","\uc774\ubbf8 \uacbd\ub8cc\ub41c \uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\ub77c\ub3c4 \uc2e4\uccb4\uc801 \uad8c\ub9ac\uad00\uacc4\uc5d0 \ubd80\ud569\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ub4f1\uae30\ub97c \ubb34\ud6a8\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4.","\uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\ub294 \ubd80\ub3d9\uc0b0\ub4f1\uae30\ud2b9\ubcc4\uc870\uce58\ubc95\uc5d0 \uc758\ud574\uc11c\ub9cc \uc720\ud6a8\ud558\ub2e4."],t.s)
B.YO=s(["\uc2e4\uccb4\uc801 \uad8c\ub9ac\uad00\uacc4\uc5d0 \ubd80\ud569\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ub4f1\uae30\ub97c \ubb34\ud6a8\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a1E=s(["\uc911\uac04\uc0dd\ub7b5\ub4f1\uae30","\uc2e4\uccb4\uad00\uacc4 \ubd80\ud569"],t.s)
B.bDc=new A.a("gen_cl_realright_4","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.ank,2,"\ud310\ub840\ub294 \uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\uc758 \ud569\uc758\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc774\ubbf8 \uacbd\ub8cc\ub41c \uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\uac00 \uc2e4\uccb4\uc801 \uad8c\ub9ac\uad00\uacc4\uc5d0 \ubd80\ud569\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ub4f1\uae30\ub97c \ubb34\ud6a8\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4\ub294 \uc785\uc7a5\uc744 \ucde8\ud55c\ub2e4. \ub2e4\ub9cc \uc911\uac04\uc0dd\ub7b5\ub4f1\uae30\uccad\uad6c\uad8c \uc790\uccb4\uac00 \ub2f9\uc5f0\ud788 \uc778\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc5d0 \uc720\uc758\ud574\uc57c \ud55c\ub2e4.",B.YO,B.a1E,null)
B.aSA=s(["\ub4f1\uae30\ubd80\uc5d0 \uae30\uc7ac\ub41c \ub4f1\uae30\uba85\uc758\uc778\uc740 \uc801\ubc95\ud55c \uad8c\ub9ac\uc790\ub85c \ucd94\uc815\ub41c\ub2e4.","\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc740 \ubc95\ub960\uc0c1 \ucd94\uc815\uc73c\ub85c\uc11c \ubc18\uc99d\uc5d0 \uc758\ud574 \ubc88\ubcf5\ub420 \uc218 \uc788\ub2e4.","\uc804 \uc18c\uc720\uba85\uc758\uc778\uc774 \ub4f1\uae30\ubd80\uc0c1 \uc0ac\ub9dd\uc790\ub85c \uae30\uc7ac\ub41c \uacbd\uc6b0 \ucd94\uc815\ub825\uc774 \uae68\uc9c8 \uc218 \uc788\ub2e4.","\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc740 \uc808\ub300\uc801\uc774\uc5b4\uc11c \uc5b4\ub5a0\ud55c \ubc18\uc99d\uc73c\ub85c\ub3c4 \ubc88\ubcf5\ub420 \uc218 \uc5c6\ub2e4."],t.s)
