B.byg=new A.a("gen_cl_realright_5","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSA,3,"\ub4f1\uae30\uc758 \ucd94\uc815\ub825\uc740 \ub4f1\uae30\uba85\uc758\uc790\uac00 \uc801\ubc95\ud55c \ub4f1\uae30\uc6d0\uc778\uc5d0 \uc758\ud558\uc5ec \ubb3c\uad8c\uc744 \ucde8\ub4dd\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ub418\ub294 \ud6a8\ub825\uc744 \uc758\ubbf8\ud558\ub098, \uc774\ub294 \ubc95\ub960\uc0c1 \ucd94\uc815\uc5d0 \ubd88\uacfc\ud558\uc5ec \ubc18\uc99d\uc5d0 \uc758\ud574 \ubc88\ubcf5\ub420 \uc218 \uc788\ub2e4. \ub4f1\uae30\ubd80\uc0c1 \uc804 \uc18c\uc720\uba85\uc758\uc778\uc774 \uc0ac\ub9dd\uc790\ub85c \uae30\uc7ac\ub418\ub294 \ub4f1 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\uc73c\uba74 \ucd94\uc815\ub825\uc774 \uae68\uc9c4\ub2e4.",B.ask,B.b5S,null)
B.aJV=s(["\ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub9cc\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \ub4f1\uae30\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub3d9\uc0b0\ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uacf5\uc2dc\ucd5c\uace0\ub97c \uac70\uccd0\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.al7=s(["\uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.b7O=s(["\uc81c188\uc870","\uc778\ub3c4"],t.s)
B.bDC=new A.a("gen_cl_realright_6","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3d9\uc0b0\ubb3c\uad8c \uc591\ub3c4\uc758 \ud6a8\ub825\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJV,0,"\ubbfc\ubc95 \uc81c188\uc870 \uc81c1\ud56d\uc740 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubd80\ub3d9\uc0b0\uc774 \ub4f1\uae30\ub97c \uacf5\uc2dc\ubc29\ubc95\uc73c\ub85c \ud558\ub294 \uac83\uacfc \ub2ec\ub9ac \ub3d9\uc0b0\uc740 \uc778\ub3c4\uac00 \ubb3c\uad8c\ubcc0\ub3d9\uc758 \uc131\ub9bd\uc694\uac74\uc774 \ub41c\ub2e4.",B.al7,B.b7O,null)
B.Y1=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub97c \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ubcc0\ub3d9\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubc18\ub4dc\uc2dc \ud604\uc2e4\uc758 \uc778\ub3c4\ub97c \uc218\ubc18\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.asg=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.aS7=s(["\uac04\uc774\uc778\ub3c4","\uc81c188\uc870 \uc81c2\ud56d"],t.s)
B.bhz=new A.a("gen_cl_realright_7","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uac04\uc774\uc778\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Y1,0,"\ubbfc\ubc95 \uc81c188\uc870 \uc81c2\ud56d\uc740 \uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uac04\uc774\uc778\ub3c4\ub97c \uc778\uc815\ud55c\ub2e4. \uc774\ub294 \ud604\uc2e4\uc758 \uc778\ub3c4 \uc5c6\uc774\ub3c4 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \uad00\ub150\uc801 \uc778\ub3c4 \ubc29\uc2dd\uc774\ub2e4.",B.asg,B.aS7,null)
B.K7=s(["\ub2f9\uc0ac\uc790\uc758 \uacc4\uc57d\uc73c\ub85c \uc591\ub3c4\uc778\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \uacc4\uc18d\ud558\ub294 \uacbd\uc6b0 \uc591\uc218\uc778\uc774 \uc778\ub3c4\ubc1b\uc740 \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc778\ub3c4\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc774\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uc778\ub3c4\ubc29\uc2dd\uc774\ub2e4.","\uc810\uc720\uac1c\uc815\uc740 \ud604\uc2e4\uc758 \uc778\ub3c4\uc640 \ub3d9\uc77c\ud55c \uacf5\uc2dc\ud6a8\uacfc\ub97c \uac16\ub294\ub2e4."],t.s)
B.b3V=s(["\uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\ub9cc\uc73c\ub85c\ub294 \uc81c249\uc870\uc758 \uc778\ub3c4 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aRE=s(["\uc810\uc720\uac1c\uc815","\uc120\uc758\ucde8\ub4dd\uacfc\uc758 \uad00\uacc4"],t.s)
B.bvf=new A.a("gen_cl_realright_8","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uac1c\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.K7,1,"\ubbfc\ubc95 \uc81c189\uc870\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uad00\ud558\uc5ec \ub2f9\uc0ac\uc790\uc758 \uacc4\uc57d\uc73c\ub85c \uc591\ub3c4\uc778\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \uacc4\uc18d\ud558\ub294 \uacbd\uc6b0 \uc591\uc218\uc778\uc774 \uc778\ub3c4\ubc1b\uc740 \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ud310\ub840\ub294 \uc120\uc758\ucde8\ub4dd\uc5d0 \uc788\uc5b4\uc11c\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\ub9cc\uc73c\ub85c\ub294 \uc81c249\uc870\uc758 \uc778\ub3c4 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.b3V,B.aRE,null)
B.aDh=s(["\uc81c3\uc790\uac00 \uc810\uc720\ud558\uace0 \uc788\ub294 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc744 \uc591\ub3c4\ud558\ub294 \uacbd\uc6b0 \uc591\ub3c4\uc778\uc774 \uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ub4f1\uae30\ub97c \uac16\ucd94\uc5b4\uc57c \uc778\ub3c4\uc758 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4.","\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub294 \ubc18\ub4dc\uc2dc \uc81c3\uc790\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.PN=s(["\uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.acY=s(["\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4","\uc81c190\uc870"],t.s)
B.bBA=new A.a("gen_cl_realright_9","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\uc5d0 \uc758\ud55c \uc778\ub3c4(\ubbfc\ubc95 \uc81c190\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aDh,0,"\ubbfc\ubc95 \uc81c190\uc870\ub294 \uc81c3\uc790\uac00 \uc810\uc720\ud558\uace0 \uc788\ub294 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc744 \uc591\ub3c4\ud558\ub294 \uacbd\uc6b0\uc5d0 \uc591\ub3c4\uc778\uc774 \uadf8 \uc81c3\uc790\uc5d0 \ub300\ud55c \ubc18\ud658\uccad\uad6c\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c \uc591\ub3c4\ud568\uc73c\ub85c\uc368 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub97c \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4, \ub610\ub294 \uc9c0\uc2dc\uc5d0 \uc758\ud55c \uc778\ub3c4\ub77c\uace0 \ud55c\ub2e4.",B.PN,B.acY,null)
B.aJ2=s(["\ubaa9\uc801\ubb3c\uc774 \ub3d9\uc0b0\uc77c \uac83","\uc591\ub3c4\uc778\uc5d0\uac8c \ucc98\ubd84\uad8c\ud55c\uc774 \uc5c6\uc744 \uac83","\uc591\uc218\uc778\uc774 \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ub3d9\uc0b0\uc758 \uc810\uc720\ub97c \ucde8\ub4dd\ud560 \uac83","\uc591\uc218\uc778\uc774 \uc810\uc720\uac1c\uc815\uc758 \ubc29\ubc95\uc73c\ub85c \uc810\uc720\ub97c \ucde8\ub4dd\ud558\uc600\uc744 \uac83"],t.s)
B.Xg=s(["\uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc810\uc720\ucde8\ub4dd\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.amP=s(["\uc120\uc758\ucde8\ub4dd","\uc81c249\uc870"],t.s)
B.ben=new A.a("gen_cl_realright_10","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc120\uc758\ucde8\ub4dd\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c249\uc870\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aJ2,3,"\ubbfc\ubc95 \uc81c249\uc870\ub294 \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \ub3d9\uc0b0\uc744 \uc591\uc218\ud55c \uc790\ub294 \uc591\ub3c4\uc778\uc774 \uc815\ub2f9\ud55c \uc18c\uc720\uc790\uac00 \uc544\ub2cc \uacbd\uc6b0\uc5d0\ub3c4 \uc989\uc2dc \uadf8 \ub3d9\uc0b0\uc758 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\ub294 \uc810\uc720\uac1c\uc815\uc5d0 \uc758\ud55c \uc810\uc720\ucde8\ub4dd\uc740 \uc120\uc758\ucde8\ub4dd\uc758 \uc694\uac74\uc778 \uc810\uc720\ucde8\ub4dd\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4.",B.Xg,B.amP,null)
B.b_g=s(["\uc810\uc720\ubb3c\uc774 \ub3c4\ud488\uc774\ub098 \uc720\uc2e4\ubb3c\uc778 \uacbd\uc6b0 \ud53c\ud574\uc790 \ub610\ub294 \uc720\uc2e4\uc790\ub294 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc120\uc758\ucde8\ub4dd\uc790\ub294 \ubc18\ud658\uccad\uad6c\ub97c \uc804\ud600 \uac70\ubd80\ud560 \uc218 \uc5c6\ub2e4.","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c\uc5d0 \ub300\ud574\uc11c\ub294 \uc120\uc758\ucde8\ub4dd\uc774 \uc131\ub9bd\ud560 \uc5ec\uc9c0\uac00 \uc804\ud600 \uc5c6\ub2e4.","\ubc18\ud658\uccad\uad6c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\uc77c\ub85c\ubd80\ud130 10\ub144\uc774\ub2e4."],t.s)
B.axL=s(["\ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aot=s(["\uc81c250\uc870","\ub3c4\ud488\xb7\uc720\uc2e4\ubb3c \ud2b9\uce59"],t.s)
B.bp2=new A.a("gen_cl_realright_11","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3c4\ud488 \ubc0f \uc720\uc2e4\ubb3c\uc5d0 \uad00\ud55c \uc120\uc758\ucde8\ub4dd\uc758 \ud2b9\uce59(\ubbfc\ubc95 \uc81c250\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b_g,0,"\ubbfc\ubc95 \uc81c250\uc870\ub294 \uc810\uc720\ubb3c\uc774 \ub3c4\ud488\uc774\ub098 \uc720\uc2e4\ubb3c\uc778 \ub54c\uc5d0\ub294 \ud53c\ud574\uc790 \ub610\ub294 \uc720\uc2e4\uc790\ub294 \ub3c4\ub09c \ub610\ub294 \uc720\uc2e4\ud55c \ub0a0\ub85c\ubd80\ud130 2\ub144 \ub0b4\uc5d0 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc6d0\uc18c\uc720\uc790 \ubcf4\ud638\ub97c \uc704\ud574 \uc120\uc758\ucde8\ub4dd\uc758 \ud6a8\ub825\uc744 \uc77c\uc815 \uae30\uac04 \uc81c\ud55c\ud558\ub294 \ud2b9\uce59\uc774\ub2e4.",B.axL,B.aot,null)
B.a_2=s(["\uac00\uc0ac\uc0c1, \uc601\uc5c5\uc0c1 \uae30\ud0c0 \uc720\uc0ac\ud55c \uad00\uacc4\uc5d0 \uc758\ud558\uc5ec \ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub3c4 \ub3c5\ub9bd\ud558\uc5ec \uc810\uc720\uad8c\uc744 \uac00\uc9c0\uba70 \uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\ub9e4\uac1c\uad00\uacc4\uc758 \uc9c1\uc811\uc810\uc720\uc790\uc5d0 \ud574\ub2f9\ud55c\ub2e4.","\uc810\uc720\ubcf4\uc870\uc790\ub294 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ubb3c\uac74\uc744 \uc810\uc720\ud558\ub294 \uc790\ub97c \ub9d0\ud55c\ub2e4."],t.s)
B.a3S=s(["\ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790, \uc989 \uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub77c\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
