B.bgc=new A.a("gen_cl_realright_16","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc790\uc758 \uc0c1\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c203\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aSx,2,"\ubbfc\ubc95 \uc81c203\uc870\ub294 \uc810\uc720\uc790\uac00 \uc810\uc720\ubb3c\uc744 \ubc18\ud658\ud560 \ub54c \ud544\uc694\ube44\uc640 \uc720\uc775\ube44\uc758 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ub2e4\ub9cc \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc5d0\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub294 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ub294 \uc810\uc720\uc790\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacfc\uc2e4\ucde8\ub4dd \uc5ec\ubd80\uc5d0 \uc5f0\ub3d9\ub41c\ub2e4.",B.acF,B.ag4,null)
B.b8o=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc740 \uce68\ud0c8\uc790\uc758 \ud2b9\ubcc4\uc2b9\uacc4\uc778\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc740 \uc810\uc720\uc758 \uce68\ud0c8\uc774 \uc5c6\uc5b4\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0\ub294 \uc81c\ud55c\uc774 \uc5c6\ub2e4."],t.s)
B.aKE=s(["\uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aJC=s(["\uc81c204\uc870","\uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c"],t.s)
B.bHy=new A.a("gen_cl_realright_17","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c \uc911 \uc810\uc720\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b8o,0,"\ubbfc\ubc95 \uc81c204\uc870\ub294 \uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub54c\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc758 \ubc18\ud658 \ubc0f \uc190\ud574\uc758 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uce68\ud0c8\uc790\uc758 \ud2b9\ubcc4\uc2b9\uacc4\uc778\uc774 \uc545\uc758\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc790\uc5d0 \ub300\ud558\uc5ec\ub3c4 \ubc18\ud658\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \uc774 \uccad\uad6c\uad8c\uc740 \uce68\ud0c8\uc744 \ub2f9\ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.aKE,B.aJC,null)
B.a6k=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uadf8 \ubc29\ud574\uc758 \uc81c\uac70 \ubc0f \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\ubb3c\ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uc740 \uc810\uc720\uc758 \uce68\ud0c8\uc774 \uc788\uc5b4\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4.","\ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \ub2f4\ubcf4\ub97c \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4.","\uc810\uc720\ubb3c\ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uc740 \ubc29\ud574\uac00 \uc885\ub8cc\ub41c \ud6c4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.a8r=s(["\uc810\uc720\uc758 \ubc29\ud574\ub97c \ubc1b\uc740 \ub54c\uc5d0\ub294 \uadf8 \ubc29\ud574\uc758 \uc81c\uac70 \ubc0f \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
