B.bDE=new A.a("gen_ba_inventory_15","business_admin","\ud68c\uacc4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \ub9e4\ucd9c\uc6d0\uac00","\uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\ud560 \ud56d\ubaa9\uc778\uc9c0 \ud310\ub2e8\ud560 \ub54c, \ubbf8\ucc29\uc0c1\ud488(\uc6b4\uc1a1 \uc911\uc778 \uc0c1\ud488)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6H,0,"\uc120\uc801\uc9c0\uc778\ub3c4\uc870\uac74\uc5d0\uc11c\ub294 \uc0c1\ud488\uc774 \uc120\uc801\ub41c \uc2dc\uc810\uc5d0 \uc18c\uc720\uad8c\uc774 \ub9e4\uc785\uc790\uc5d0\uac8c \uc774\uc804\ub418\ubbc0\ub85c, \uc6b4\uc1a1 \uc911\uc774\ub354\ub77c\ub3c4 \ub9e4\uc785\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\uc2dc\ucf1c\uc57c \ud55c\ub2e4. \ub3c4\ucc29\uc9c0\uc778\ub3c4\uc870\uac74\uc5d0\uc11c\ub294 \ub3c4\ucc29 \uc2dc\uc810\uc5d0 \uc18c\uc720\uad8c\uc774 \uc774\uc804\ub418\ubbc0\ub85c \uadf8 \uc804\uae4c\uc9c0\ub294 \ud310\ub9e4\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc73c\ub85c \ub0a8\ub294\ub2e4.",B.afL,B.aOb,null)
B.b_h=s(["\uc218\ud0c1\uc790\uac00 \uc81c3\uc790\uc5d0\uac8c \ud310\ub9e4\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc704\ud0c1\uc790(\uc801\uc1a1\uc778)\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud3ec\ud568\ub41c\ub2e4","\uc704\ud0c1\uc790\uac00 \uc0c1\ud488\uc744 \uc218\ud0c1\uc790\uc5d0\uac8c \ubc1c\uc1a1\ud558\ub294 \uc989\uc2dc \uc218\ud0c1\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc73c\ub85c \uadc0\uc18d\ub41c\ub2e4","\uc801\uc1a1\ud488\uc740 \uc5b4\ub290 \ucabd\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0\ub3c4 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc218\ud0c1\uc790\ub294 \uc801\uc1a1\ud488 \ubcf4\uad00 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ub9e4\ucd9c\uc744 \uc778\uc2dd\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aL3=s(["\uc18c\uc720\uad8c\uc740 \uc218\ud0c1\uc790\uac00 \uc81c3\uc790\uc5d0\uac8c \uc2e4\uc81c\ub85c \ud310\ub9e4\ud558\uae30 \uc804\uae4c\uc9c0 \uc704\ud0c1\uc790(\uc801\uc1a1\uc778)\uc5d0\uac8c \ub0a8\uc544\uc788\uc73c\ubbc0\ub85c, \ud310\ub9e4 \uc804\uae4c\uc9c0\ub294 \uc704\ud0c1\uc790\uc758 \uc7ac\uace0\uc790\uc0b0\uc73c\ub85c \uacc4\uc0c1"],t.s)
