B.bzv=new A.a("gen_ba_inventory_17","business_admin","\ud68c\uacc4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \ub9e4\ucd9c\uc6d0\uac00","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \uad00\ub828\ud558\uc5ec \ubb3c\uac00\uac00 \uc9c0\uc18d\uc801\uc73c\ub85c \uc0c1\uc2b9\ud558\ub294 \uacbd\uc6b0, \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0 \uae08\uc561\uc758 \ud06c\uae30\ub97c \uc633\uac8c \ube44\uad50\ud55c \uac83\uc740?",B.pt,0,"\ubb3c\uac00\uc0c1\uc2b9 \uc2dc \uc120\uc785\uc120\ucd9c\ubc95\uc740 \uae30\ub9d0\uc7ac\uace0\ub97c \uc0c1\ub300\uc801\uc73c\ub85c \ucd5c\uadfc\uc758 \ub192\uc740 \ub2e8\uac00\ub85c \ud3c9\uac00\ud558\ubbc0\ub85c \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0 \uae08\uc561\uc774 \uac00\uc7a5 \ud06c\uac8c \ub098\ud0c0\ub09c\ub2e4. \ubc18\ub300\ub85c \ud6c4\uc785\uc120\ucd9c\ubc95\uc740 \uae30\ub9d0\uc7ac\uace0\uac00 \uc624\ub798\ub41c \ub0ae\uc740 \ub2e8\uac00\ub85c \ub0a8\uc544 \uae08\uc561\uc774 \uac00\uc7a5 \uc791\ub2e4.",B.LL,B.b6T,null)
B.Z3=s(["\uc2e4\uc0ac\ub97c \ud558\uc9c0 \uc54a\uace0\ub3c4 \uacfc\uac70\uc758 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\uc744 \uc774\uc6a9\ud574 \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0\uacfc \ub9e4\ucd9c\uc6d0\uac00\ub97c \ucd94\uc815\ud558\ub294 \ubc29\ubc95\uc774\ub2e4","\ubc18\ub4dc\uc2dc \uc2e4\uc9c0\uc7ac\uace0\uc870\uc0ac\ub97c \uac70\uccd0\uc57c\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc774\ub2e4","\uc7ac\uace0\uc790\uc0b0\uc758 \uc815\ud655\ud55c \ucde8\ub4dd\uc6d0\uac00\ub97c \uac1c\ubcc4\uc801\uc73c\ub85c \ud30c\uc545\ud558\ub294 \ubc29\ubc95\uc774\ub2e4","\uc7ac\ubb34\uc81c\ud45c \uac10\uc0ac \uc2dc \uac00\uc7a5 \uc815\ubc00\ud55c \uc7ac\uace0\ud3c9\uac00 \ubc29\ubc95\uc73c\ub85c \uc778\uc815\ub41c\ub2e4"],t.s)
B.M4=s(["\uacfc\uac70\uc758 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\uc744 \ub9e4\ucd9c\uc561\uc5d0 \uc801\uc6a9\ud558\uc5ec \ub9e4\ucd9c\uc6d0\uac00\uc640 \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0\uc744 \uac04\ud3b8\ud558\uac8c \ucd94\uc815\ud558\ub294 \ubc29\ubc95"],t.s)
B.aOq=s(["\ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\ubc95"],t.s)
B.beG=new A.a("gen_ba_inventory_18","business_admin","\ud68c\uacc4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \ub9e4\ucd9c\uc6d0\uac00","\ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\ubc95(gross profit method)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Z3,0,"\ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\ubc95\uc740 \ud654\uc7ac \ub4f1\uc73c\ub85c \uc2e4\uc0ac\uac00 \uc5b4\ub824\uc6b4 \uacbd\uc6b0, \uacfc\uac70\uc758 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\uc744 \ub9e4\ucd9c\uc561\uc5d0 \uc801\uc6a9\ud558\uc5ec \ub9e4\ucd9c\uc6d0\uac00\uc640 \uae30\ub9d0\uc7ac\uace0\uc790\uc0b0\uc744 \uac04\ud3b8\ud558\uac8c \ucd94\uc815\ud558\ub294 \ubc29\ubc95\uc73c\ub85c, \uc815\ud655\ud55c \uc2e4\uc0ac \uc5c6\uc774 \ub300\ub7b5\uc801\uc778 \uae08\uc561\uc744 \ud30c\uc545\ud560 \ub54c \uc0ac\uc6a9\ud55c\ub2e4.",B.M4,B.aOq,null)
B.axT=s(["\ud310\ub9e4\ub97c \uc704\ud574 \ubcf4\uc720 \uc911\uc778 \uc0c1\ud488","\uc0dd\uc0b0\uacfc\uc815\uc5d0 \uc788\ub294 \uc7ac\uacf5\ud488","\uc0dd\uc0b0\uc5d0 \ud22c\uc785\ub420 \uc6d0\uc7ac\ub8cc","\ubd80\ub3d9\uc0b0\ub9e4\ub9e4\uc5c5\uc790\uac00 \ud310\ub9e4\ubaa9\uc801\uc73c\ub85c \ubcf4\uc720\ud558\ub294 \ud1a0\uc9c0","\ubcf8\uc0ac \uc0ac\uc625\uc73c\ub85c \uc0ac\uc6a9 \uc911\uc778 \uac74\ubb3c"],t.s)
B.aD0=s(["\ubcf8\uc0ac \uc0ac\uc625\uc73c\ub85c \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \uac74\ubb3c\uc740 \ud310\ub9e4 \ubaa9\uc801\uc774 \uc544\ub2c8\ubbc0\ub85c \uc720\ud615\uc790\uc0b0\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4"],t.s)
B.Wf=s(["\uc5c5\uc885\uc5d0 \ub530\ub978 \uc7ac\uace0\uc790\uc0b0 \ubd84\ub958"],t.s)
B.bCU=new A.a("gen_ba_inventory_19","business_admin","\ud68c\uacc4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\uc640 \ub9e4\ucd9c\uc6d0\uac00","\uc7ac\uace0\uc790\uc0b0\uc73c\ub85c \ubd84\ub958\ub418\uc9c0 \uc54a\ub294 \uac83\uc740?",B.axT,4,"\uc7ac\uace0\uc790\uc0b0\uc740 \uc815\uc0c1\uc801\uc778 \uc601\uc5c5\uacfc\uc815\uc5d0\uc11c \ud310\ub9e4\ub97c \ubaa9\uc801\uc73c\ub85c \ubcf4\uc720\ud558\uac70\ub098 \uc0dd\uc0b0 \uc911\uc778 \uc790\uc0b0\uc744 \ub9d0\ud55c\ub2e4. \ubd80\ub3d9\uc0b0\ub9e4\ub9e4\uc5c5\uc790\uac00 \ud310\ub9e4 \ubaa9\uc801\uc73c\ub85c \ubcf4\uc720\ud558\ub294 \ud1a0\uc9c0\ub294 \uadf8 \uc5c5\uc885\uc758 \uc7ac\uace0\uc790\uc0b0\uc5d0 \ud574\ub2f9\ud558\uc9c0\ub9cc, \ubcf8\uc0ac \uc0ac\uc625\uc73c\ub85c \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \uac74\ubb3c\uc740 \ud310\ub9e4 \ubaa9\uc801\uc774 \uc544\ub2c8\ubbc0\ub85c \uc720\ud615\uc790\uc0b0\uc73c\ub85c \ubd84\ub958\ub41c\ub2e4.",B.aD0,B.Wf,null)
B.b3G=s(["\uc815\ub2f9\ud55c \uc0ac\uc720 \uc5c6\uc774 \ub9e4\uae30 \uc790\uc720\ub86d\uac8c \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4","\ud68c\uacc4\uc815\ucc45\uc758 \ubcc0\uacbd\uc5d0 \ud574\ub2f9\ud558\uba70, \uc815\ub2f9\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4","\uc7ac\uace0\uc790\uc0b0 \ud3c9\uac00\ubc29\ubc95\uc758 \ubcc0\uacbd\uc740 \ud68c\uacc4\uc0c1 \uc544\ubb34\ub7f0 \uc758\ubbf8\uac00 \uc5c6\ub294 \uc0ac\ud56d\uc774\ub2e4","\ud3c9\uac00\ubc29\ubc95\uc744 \ubcc0\uacbd\ud574\ub3c4 \ub9e4\ucd9c\uc6d0\uac00\ub098 \uae30\ub9d0\uc7ac\uace0 \uae08\uc561\uc5d0\ub294 \uc804\ud600 \uc601\ud5a5\uc774 \uc5c6\ub2e4"],t.s)
