B.bEQ=new A.a("gen_ba_ppe_18","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\uac74\uc124\uc911\uc778\uc790\uc0b0(construction in progress)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ami,0,"\uac74\uc124\uc911\uc778\uc790\uc0b0\uc740 \uc720\ud615\uc790\uc0b0\uc758 \uac74\uc124\uc744 \uc704\ud574 \uc9c0\ucd9c\ud55c \uae08\uc561\uc744 \uc644\uacf5 \uc804\uae4c\uc9c0 \uc9d1\uacc4\ud574\ub450\ub294 \uacc4\uc815\uc73c\ub85c, \uc544\uc9c1 \uc0ac\uc6a9 \uac00\ub2a5\ud55c \uc0c1\ud0dc\uc5d0 \uc774\ub974\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c \uac10\uac00\uc0c1\uac01\uc744 \uc2dc\uc791\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac74\uc124\uc774 \uc644\ub8cc\ub418\uc5b4 \uc0ac\uc6a9 \uac00\ub2a5\ud55c \uc0c1\ud0dc\uac00 \ub418\uba74 \ud574\ub2f9 \uc720\ud615\uc790\uc0b0 \uacc4\uc815\uc73c\ub85c \ub300\uccb4\ud558\uace0 \uadf8\ub54c\ubd80\ud130 \uac10\uac00\uc0c1\uac01\uc744 \uc2dc\uc791\ud55c\ub2e4.",B.XR,B.a_F,null)
B.aST=s(["\uc720\ud615\uc790\uc0b0\uc758 \uac10\uac00\uc0c1\uac01\uacfc \uc720\uc0ac\ud558\uac8c, \ucd94\uc815 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uccb4\uacc4\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \uc0c1\uac01\ud55c\ub2e4","\ubb34\ud615\uc790\uc0b0\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc0c1\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubb34\ud615\uc790\uc0b0 \uc0c1\uac01\uc740 \ubc18\ub4dc\uc2dc \uc815\ub960\ubc95\uc73c\ub85c\ub9cc \ud574\uc57c \ud55c\ub2e4","\ubb34\ud615\uc790\uc0b0\uc740 \uc0c1\uac01 \ub300\uc2e0 \ub9e4\uae30 \uc804\uc561\uc744 \uc989\uc2dc \ube44\uc6a9\ud654\ud574\uc57c \ud55c\ub2e4"],t.s)
B.akp=s(["\ub0b4\uc6a9\uc5f0\uc218\uac00 \uc720\ud55c\ud55c \ubb34\ud615\uc790\uc0b0\uc740 \uc720\ud615\uc790\uc0b0\uc758 \uac10\uac00\uc0c1\uac01\uacfc \uc720\uc0ac\ud558\uac8c, \ucd94\uc815 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uccb4\uacc4\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \uc0c1\uac01"],t.s)
