B.bzg=new A.a("gen_ba_ppe_20","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\uc5f0\uad6c\ub2e8\uacc4\uc640 \uac1c\ubc1c\ub2e8\uacc4\uc758 \uc9c0\ucd9c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMp,0,"\uc5f0\uad6c\ub2e8\uacc4\uc758 \uc9c0\ucd9c\uc740 \uc544\uc9c1 \ubbf8\ub798 \uacbd\uc81c\uc801\ud6a8\uc775\uc758 \ubc1c\uc0dd\uc744 \ud2b9\uc815\ud558\uae30 \uc5b4\ub824\uc6cc \ubc1c\uc0dd \uc2dc\uc810\uc5d0 \ube44\uc6a9(\uc5f0\uad6c\ube44)\uc73c\ub85c \ucc98\ub9ac\ud55c\ub2e4. \ubc18\uba74 \uac1c\ubc1c\ub2e8\uacc4\uc758 \uc9c0\ucd9c\uc740 \uc790\uc0b0 \uc778\uc2dd\uc694\uac74(\uae30\uc220\uc801 \uc2e4\ud604\uac00\ub2a5\uc131, \uc0ac\uc6a9\xb7\ud310\ub9e4 \uc758\ub3c4 \ub4f1)\uc744 \ucda9\uc871\ud558\uba74 \ubb34\ud615\uc790\uc0b0(\uac1c\ubc1c\ube44)\uc73c\ub85c \uc790\ubcf8\ud654\ud560 \uc218 \uc788\ub2e4.",B.aS_,B.akb,null)
B.Jw=s(["\uc790\uc0b0\uc758 \uc6d0\uac00\ub97c \uadf8 \uc790\uc0b0\uc774 \uacbd\uc81c\uc801\ud6a8\uc775\uc744 \uc81c\uacf5\ud558\ub294 \uae30\uac04(\ub0b4\uc6a9\uc5f0\uc218) \ub3d9\uc548 \uccb4\uacc4\uc801\uc73c\ub85c \ubc30\ubd84\ud558\uc5ec \ube44\uc6a9\ud654\ud558\ub294 \uac83\uc774\ub2e4","\uc790\uc0b0\uc758 \uc2dc\uac00\ub97c \ub9e4 \uae30\uac04 \uc815\ud655\ud558\uac8c \ud3c9\uac00\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc790\uc0b0\uc758 \uc2e4\uc81c \ucc98\ubd84\uac00\uce58\ub97c \ucd94\uc815\ud558\uae30 \uc704\ud55c \uc808\ucc28\uc774\ub2e4","\uc138\uae08\uc744 \uc904\uc774\uae30 \uc704\ud55c \ubaa9\uc801\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ub418\ub294 \uc784\uc758\uc801\uc778 \uc808\ucc28\uc774\ub2e4"],t.s)
B.aAV=s(["\uc720\ud615\uc790\uc0b0\uc758 \ucde8\ub4dd\uc6d0\uac00\ub97c \uadf8 \uc790\uc0b0\uc774 \uacbd\uc81c\uc801\ud6a8\uc775\uc744 \uc81c\uacf5\ud558\ub294 \uae30\uac04\uc778 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uccb4\uacc4\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \ube44\uc6a9\uc73c\ub85c \ubc30\ubd84\ud558\ub294 \uc6d0\uac00\ubc30\ubd84 \uc808\ucc28"],t.s)
B.aFy=s(["\uac10\uac00\uc0c1\uac01\uc758 \ubaa9\uc801(\uc6d0\uac00\ubc30\ubd84)"],t.s)
B.biB=new A.a("gen_ba_ppe_21","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\uc720\ud615\uc790\uc0b0 \uac10\uac00\uc0c1\uac01\uc758 \ubaa9\uc801\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Jw,0,"\uac10\uac00\uc0c1\uac01\uc740 \uc790\uc0b0\uc758 \uc2dc\uac00\ub97c \ud3c9\uac00\ud558\ub294 \uc808\ucc28\uac00 \uc544\ub2c8\ub77c, \uc720\ud615\uc790\uc0b0\uc758 \ucde8\ub4dd\uc6d0\uac00\ub97c \uadf8 \uc790\uc0b0\uc774 \uacbd\uc81c\uc801\ud6a8\uc775\uc744 \uc81c\uacf5\ud558\ub294 \uae30\uac04\uc778 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uccb4\uacc4\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \ube44\uc6a9\uc73c\ub85c \ubc30\ubd84\ud558\ub294 \uc6d0\uac00\ubc30\ubd84 \uc808\ucc28\uc774\ub2e4.",B.aAV,B.aFy,null)
B.aNb=s(["\uc77c\uad04 \ucde8\ub4dd\uac00\uc561\uc744 \ud1a0\uc9c0\uc640 \uac74\ubb3c \uac01\uac01\uc758 \uc0c1\ub300\uc801 \uacf5\uc815\uac00\uce58 \ube44\uc728\uc5d0 \ub530\ub77c \ubc30\ubd84\ud55c\ub2e4","\uc77c\uad04 \ucde8\ub4dd\uac00\uc561 \uc804\ubd80\ub97c \ud1a0\uc9c0\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c\ub9cc \uc778\uc2dd\ud55c\ub2e4","\uc77c\uad04 \ucde8\ub4dd\uac00\uc561 \uc804\ubd80\ub97c \uac74\ubb3c\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c\ub9cc \uc778\uc2dd\ud55c\ub2e4","\ud1a0\uc9c0\uc640 \uac74\ubb3c\uc744 \uc77c\uad04 \ucde8\ub4dd\ud55c \uacbd\uc6b0 \ud68c\uacc4\ucc98\ub9ac \ubc29\ubc95\uc5d0 \uad00\ud55c \ubcc4\ub3c4 \uaddc\uc815\uc740 \uc5c6\ub2e4"],t.s)
B.a9i=s(["\ucd1d \ucde8\ub4dd\uc6d0\uac00\ub97c \ucde8\ub4dd \uc2dc\uc810\uc758 \uac01 \uc790\uc0b0\uc758 \uc0c1\ub300\uc801 \uacf5\uc815\uac00\uce58 \ube44\uc728\uc5d0 \ub530\ub77c \uc548\ubd84\ud558\uc5ec \uac01\uac01\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c \ubc30\ubd84"],t.s)
B.apT=s(["\uc77c\uad04\ucde8\ub4dd \uc790\uc0b0\uc758 \uc6d0\uac00\ubc30\ubd84"],t.s)
B.bty=new A.a("gen_ba_ppe_22","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\ud1a0\uc9c0\uc640 \uac74\ubb3c\uc744 \uc77c\uad04 \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc758 \ud68c\uacc4\ucc98\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNb,0,"\ud1a0\uc9c0\uc640 \uac74\ubb3c\ucc98\ub7fc \uac10\uac00\uc0c1\uac01 \uc5ec\ubd80\uac00 \ub2e4\ub978 \uc790\uc0b0\uc744 \uc77c\uad04 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucd1d \ucde8\ub4dd\uc6d0\uac00\ub97c \ucde8\ub4dd \uc2dc\uc810\uc758 \uac01 \uc790\uc0b0\uc758 \uc0c1\ub300\uc801 \uacf5\uc815\uac00\uce58 \ube44\uc728\uc5d0 \ub530\ub77c \uc548\ubd84\ud558\uc5ec \uac01\uac01\uc758 \ucde8\ub4dd\uc6d0\uac00\ub85c \ubc30\ubd84\ud574\uc57c \ud55c\ub2e4.",B.a9i,B.apT,null)
