B.bzt=new A.a("gen_ba_mkt_stp_14","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\ubb34\ucc28\ubcc4\uc801 \ub9c8\ucf00\ud305\uacfc \ube44\uad50\ud560 \ub54c \ucc28\ubcc4\uc801 \ub9c8\ucf00\ud305\uc758 \ub2e8\uc810\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.axs,0,"\ucc28\ubcc4\uc801 \ub9c8\ucf00\ud305\uc740 \uc138\ubd84\uc2dc\uc7a5\ubcc4\ub85c \ubcc4\ub3c4\uc758 \uc81c\ud488 \uac1c\ubc1c, \uc0dd\uc0b0\ub77c\uc778 \uc870\uc815, \uad11\uace0\xb7\uc720\ud1b5 \uc804\ub7b5\uc744 \uc6b4\uc601\ud574\uc57c \ud558\ubbc0\ub85c \ubb34\ucc28\ubcc4\uc801 \ub9c8\ucf00\ud305\uc5d0 \ube44\ud574 \uc0dd\uc0b0\ube44\uc6a9\xb7\uc7ac\uace0\uad00\ub9ac\ube44\uc6a9\xb7\ub9c8\ucf00\ud305\uc870\uc0ac\ube44\uc6a9 \ub4f1\uc774 \ub298\uc5b4\ub09c\ub2e4\ub294 \ub2e8\uc810\uc774 \uc788\ub2e4.",B.afb,B.a5M,null)
B.a_a=s(["\uad6d\uac00, \uc9c0\uc5ed, \ub3c4\uc2dc \uaddc\ubaa8, \uae30\ud6c4 \ub4f1 \uc9c0\ub9ac\uc801 \ub2e8\uc704\ub97c \uae30\uc900\uc73c\ub85c \uc2dc\uc7a5\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uace0\uac1d\uc758 \uc18c\ub4dd \uc218\uc900\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \uc2dc\uc7a5\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uace0\uac1d\uc758 \ub77c\uc774\ud504\uc2a4\ud0c0\uc77c\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \uc2dc\uc7a5\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uace0\uac1d\uc758 \ube0c\ub79c\ub4dc \uc778\uc9c0\ub3c4\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \uc2dc\uc7a5\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4"],t.s)
