B.bB8=new A.a("gen_ba_mkt_stp_15","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\uc9c0\ub9ac\uc801 \uc138\ubd84\ud654(geographic segmentation)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_a,0,"\uc9c0\ub9ac\uc801 \uc138\ubd84\ud654\ub294 \uad6d\uac00, \uc9c0\uc5ed, \ub3c4\uc2dc \uaddc\ubaa8, \uc778\uad6c\ubc00\ub3c4, \uae30\ud6c4 \ub4f1 \uc9c0\ub9ac\uc801 \ub2e8\uc704\ub85c \uc2dc\uc7a5\uc744 \ub098\ub204\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc9c0\uc5ed\ubcc4 \uae30\ud6c4\ub098 \ubb38\ud654 \ucc28\uc774\uac00 \ud070 \uc81c\ud488(\uc758\ub958, \uc2dd\ud488 \ub4f1)\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud558\uac8c \ud65c\uc6a9\ub41c\ub2e4.",B.acj,B.aMd,null)
