B.bC0=new A.a("gen_ba_mkt_stp_16","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\uc18d\uc131 \ud3ec\uc9c0\uc154\ub2dd(attribute positioning)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aZZ,0,"\uc18d\uc131 \ud3ec\uc9c0\uc154\ub2dd\uc740 \uc5f0\ube44, \uc548\uc804\uc131, \ub0b4\uad6c\uc131\uacfc \uac19\uc740 \uc81c\ud488\uc758 \ud2b9\uc815 \uc18d\uc131\uc774\ub098 \ud2b9\uc9d5\uc744 \ubd80\uac01\uc2dc\ucf1c \uc18c\ube44\uc790\uc758 \ub9c8\uc74c\uc18d\uc5d0 \uc790\ub9ac\ub9e4\uae40\ud558\ub294 \ud3ec\uc9c0\uc154\ub2dd \ubc29\uc2dd\uc73c\ub85c, \uc0ac\uc6a9\uc0c1\ud669\xb7\uc0ac\uc6a9\uc790\xb7\uacbd\uc7c1\uc81c\ud488 \ub300\ube44 \ud3ec\uc9c0\uc154\ub2dd \ub4f1 \ub2e4\ub978 \ubc29\uc2dd\uacfc \ud568\uaed8 \ud65c\uc6a9\ub418\ub294 \ub300\ud45c\uc801\uc778 \uc720\ud615 \uc911 \ud558\ub098\uc774\ub2e4.",B.aRh,B.aYt,null)
B.aLo=s(["\uc790\uc0ac \uc81c\ud488\uc744 \ud2b9\uc815 \uacbd\uc7c1\uc81c\ud488\uacfc \uba85\uc2dc\uc801\uc73c\ub85c \ube44\uad50\ud574 \uc0c1\ub300\uc801 \uc6b0\uc704\ub97c \ubd80\uac01\uc2dc\ud0a4\ub294 \ubc29\uc2dd\uc774\ub2e4","\uacbd\uc7c1\uc0ac\uc758 \uc874\uc7ac\ub97c \ucca0\uc800\ud788 \ubb34\uc2dc\ud558\ub294 \ud3ec\uc9c0\uc154\ub2dd \ubc29\uc2dd\uc774\ub2e4","\uc624\uc9c1 \uac00\uaca9\uc5d0 \ub300\ud574\uc11c\ub9cc \uacbd\uc7c1\uc0ac\uc640 \ube44\uad50\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uacbd\uc7c1\uc81c\ud488\uacfc \uc808\ub300 \ube44\uad50\uad11\uace0\ub97c \ud560 \uc218 \uc5c6\ub2e4\ub294 \uc6d0\uce59\uc5d0 \uae30\ubc18\ud55c \ubc29\uc2dd\uc774\ub2e4"],t.s)
