B.Ks=s(["\uacbd\uc7c1\uc81c\ud488\uc5d0 \uc758\ud55c \ud3ec\uc9c0\uc154\ub2dd"],t.s)
B.bE5=new A.a("gen_ba_mkt_stp_17","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\ud3ec\uc9c0\uc154\ub2dd \uc804\ub7b5 \uc911 \uacbd\uc7c1\uc81c\ud488\uc5d0 \uc758\ud55c \ud3ec\uc9c0\uc154\ub2dd(positioning by competitor)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aLo,0,"\uacbd\uc7c1\uc81c\ud488\uc5d0 \uc758\ud55c \ud3ec\uc9c0\uc154\ub2dd\uc740 \ud2b9\uc815 \uacbd\uc7c1\uc0ac(\ub300\ud45c\uc801\uc73c\ub85c \uc2dc\uc7a5 \uc120\ub3c4 \ube0c\ub79c\ub4dc)\ub97c \uae30\uc900\uc810\uc73c\ub85c \uc0bc\uc544, \uc790\uc0ac \uc81c\ud488\uc774 \uadf8\uc640 \ube44\uad50\ud574 \uc5b4\ub5a4 \uc810\uc5d0\uc11c \uc6b0\uc704\uc5d0 \uc788\ub294\uc9c0\ub97c \uba85\uc2dc\uc801\uc73c\ub85c \ubd80\uac01\uc2dc\ud0a4\ub294 \ud3ec\uc9c0\uc154\ub2dd \ubc29\uc2dd\uc774\ub2e4.",B.QP,B.Ks,null)
B.a3k=s(["\uc138\ubd84\uc2dc\uc7a5\uc758 \uaddc\ubaa8, \uad6c\ub9e4\ub825 \ub4f1\uc744 \uc5b4\ub290 \uc815\ub3c4 \uce21\uc815\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4","\uc138\ubd84\uc2dc\uc7a5\uc758 \uc18c\ube44\uc790 \uc218\ub294 \ubc18\ub4dc\uc2dc \uc9dd\uc218\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4","\uc138\ubd84\uc2dc\uc7a5\uc5d0 \ub3c4\ub2ec\ud560 \uc218 \uc788\ub294 \uc720\ud1b5\xb7\ucd09\uc9c4 \uc218\ub2e8\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4","\uc138\ubd84\uc2dc\uc7a5 \uaddc\ubaa8\uac00 \uc774\uc775\uc744 \ub0bc \uc218 \uc788\uc744 \ub9cc\ud07c \ucda9\ubd84\ud788 \ucee4\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4"],t.s)
B.b4v=s(["\uce21\uc815\uac00\ub2a5\uc131\uc740 \uc138\ubd84\uc2dc\uc7a5\uc758 \uaddc\ubaa8, \uad6c\ub9e4\ub825, \ud2b9\uc131 \ub4f1\uc744 \uc5b4\ub290 \uc815\ub3c4 \uc218\uce58\ub85c \uce21\uc815\ud558\uac70\ub098 \ud30c\uc545\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc694\uac74"],t.s)
B.aXR=s(["\ud6a8\uacfc\uc801 \uc2dc\uc7a5\uc138\ubd84\ud654 \uc694\uac74 \u2014 \uce21\uc815\uac00\ub2a5\uc131"],t.s)
B.bfj=new A.a("gen_ba_mkt_stp_18","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd",'\ud6a8\uacfc\uc801\uc778 \uc2dc\uc7a5\uc138\ubd84\ud654\uac00 \uac16\ucd94\uc5b4\uc57c \ud560 \uc694\uac74 \uc911 "\uce21\uc815\uac00\ub2a5\uc131(measurability)"\uc774 \uc758\ubbf8\ud558\ub294 \ubc14\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a3k,0,"\uce21\uc815\uac00\ub2a5\uc131\uc740 \uc138\ubd84\uc2dc\uc7a5\uc758 \uaddc\ubaa8, \uad6c\ub9e4\ub825, \ud2b9\uc131 \ub4f1\uc744 \uc5b4\ub290 \uc815\ub3c4 \uc218\uce58\ub85c \uce21\uc815\ud558\uac70\ub098 \ud30c\uc545\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc694\uac74\uc774\ub2e4. \uc720\ud1b5\xb7\ucd09\uc9c4 \uc218\ub2e8\uc73c\ub85c \ub3c4\ub2ec \uac00\ub2a5\ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uc740 \uc811\uadfc\uac00\ub2a5\uc131, \uc774\uc775\uc744 \ub0bc \ub9cc\ud07c \ucee4\uc57c \ud55c\ub2e4\ub294 \uac83\uc740 \uc2e4\uc9c8\uc801 \uaddc\ubaa8(\ucda9\ubd84\ud55c \uaddc\ubaa8)\uc758 \uc694\uac74\uc774\ub2e4.",B.b4v,B.aXR,null)
B.MF=s(["\uc790\uc6d0\uc774 \uc81c\ud55c\uc801\uc778 \uc911\uc18c\uae30\uc5c5\uc774 \ud2b9\uc815 \ud2c8\uc0c8\uc2dc\uc7a5\uc5d0\uc11c \uc804\ubb38\uc131\uc744 \uc313\uace0\uc790 \ud560 \ub54c","\uc774\ubbf8 \uc2dc\uc7a5\uc744 \uc9c0\ubc30\ud558\uace0 \uc788\ub294 \ucd08\ub300\ud615 \uae30\uc5c5\uc774 \uc2dc\uc7a5 \uc804\uccb4\ub97c \uacf5\ub7b5\ud558\uace0\uc790 \ud560 \ub54c","\ubaa8\ub4e0 \uc138\ubd84\uc2dc\uc7a5\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \ub192\uc740 \uc810\uc720\uc728\uc744 \uc6d0\ud560 \ub54c","\uc138\ubd84\uc2dc\uc7a5 \uac04 \uc704\ud5d8\uc744 \ucd5c\ub300\ud55c \ubd84\uc0b0\uc2dc\ud0a4\uace0\uc790 \ud560 \ub54c"],t.s)
B.a16=s(["\uc9d1\uc911\uc801 \ub9c8\ucf00\ud305\uc740 \ud55c\uc815\ub41c \uc790\uc6d0\uc744 \ud558\ub098 \ub610\ub294 \uc18c\uc218\uc758 \uc138\ubd84\uc2dc\uc7a5\uc5d0 \uc9d1\uc911\ud574 \uc804\ubb38\uc131\uacfc \uac15\ub825\ud55c \uc2dc\uc7a5\uc9c0\uc704\ub97c \uc313\uace0\uc790 \ud558\ub294 \uc911\uc18c\uae30\uc5c5\uc774\ub098 \uc2e0\uc0dd\uae30\uc5c5\uc5d0 \ud2b9\ud788 \uc801\ud569"],t.s)
