B.bjf=new A.a("gen_ba_mkt_stp_27","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","STP \uc804\ub7b5\uc5d0\uc11c \uc138\ubd84\ud654(Segmentation) \ub2e8\uacc4\uac00 \uc120\ud589\ub418\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.alH,0,"\uc2dc\uc7a5\uc138\ubd84\ud654\ub294 \uc774\uc9c8\uc801\uc778 \uc804\uccb4 \uc2dc\uc7a5 \uc548\uc5d0 \uc874\uc7ac\ud558\ub294, \uc11c\ub85c \ub2e4\ub978 \uc695\uad6c\ub97c \uac00\uc9c4 \ub3d9\uc9c8\uc801\uc778 \uc18c\ube44\uc790 \uc9d1\ub2e8\ub4e4\uc744 \uba3c\uc800 \ud30c\uc545\ud558\ub294 \uacfc\uc815\uc774\ub2e4. \uc774\ub807\uac8c \ud30c\uc545\ub41c \uc138\ubd84\uc2dc\uc7a5\uc774 \uc788\uc5b4\uc57c \uadf8\uc911 \uacf5\ub7b5\ud560 \ud45c\uc801\uc2dc\uc7a5\uc744 \uc120\uc815\ud558\uace0, \uadf8 \uc2dc\uc7a5\uc5d0 \ub9de\ub294 \ud3ec\uc9c0\uc154\ub2dd\uc744 \uc124\uacc4\ud560 \uc218 \uc788\ub2e4.",B.asY,B.Rb,null)
B.b5q=s(["\uc138\ubd84\uc2dc\uc7a5\uc758 \uaddc\ubaa8\uc640 \uad6c\ub9e4\ub825\uc744 \uc218\uce58\ub85c \ud30c\uc545\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0","\uc138\ubd84\uc2dc\uc7a5\uc5d0 \ub3c4\ub2ec\ud560 \uc218 \uc788\ub294 \uad11\uace0\ub9e4\uccb4\ub098 \uc720\ud1b5\uacbd\ub85c\uac00 \ub9c8\ub545\uce58 \uc54a\uc740 \uacbd\uc6b0","\uc138\ubd84\uc2dc\uc7a5\uc774 \ub2e4\ub978 \uc138\ubd84\uc2dc\uc7a5\uacfc \ub69c\ub837\uc774 \uad6c\ubd84\ub418\ub294 \uacbd\uc6b0","\uc138\ubd84\uc2dc\uc7a5\uc758 \uaddc\ubaa8\uac00 \ucda9\ubd84\ud788 \ucee4\uc11c \uc218\uc775\uc131\uc774 \uc788\ub294 \uacbd\uc6b0"],t.s)
B.Kc=s(["\ud574\ub2f9 \uc138\ubd84\uc2dc\uc7a5\uc5d0 \ud6a8\uacfc\uc801\uc73c\ub85c \ub3c4\ub2ec\ud558\uc5ec \ub9c8\ucf00\ud305\ud65c\ub3d9\uc744 \uc804\uac1c\ud560 \uc218 \uc788\ub294 \uc720\ud1b5\uacbd\ub85c\ub098 \uad11\uace0\ub9e4\uccb4\uac00 \uc874\uc7ac\ud574\uc57c \ud55c\ub2e4\ub294 \uc694\uac74"],t.s)
