B.b4d=s(["\uad00\uc5ec\ub3c4\uc758 \uac1c\ub150"],t.s)
B.bed=new A.a("gen_ba_mkt_consumer_2","business_admin","\ub9c8\ucf00\ud305","\uc18c\ube44\uc790 \uad6c\ub9e4\uc758\uc0ac\uacb0\uc815\uacfc\uc815","\uc18c\ube44\uc790\uc758 \uad00\uc5ec\ub3c4(involvement)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ZS,3,'\uad00\uc5ec\ub3c4\ub294 \uc81c\ud488\uc758 \ud2b9\uc131(\uac00\uaca9, \uc704\ud5d8 \uc815\ub3c4 \ub4f1)\ubfd0 \uc544\ub2c8\ub77c \uac1c\uc778\uc758 \uad00\uc2ec\uc0ac\xb7\uc0c1\ud669\uc5d0 \ub530\ub77c\uc11c\ub3c4 \ub2ec\ub77c\uc9c0\ub294 \uc0c1\ub300\uc801 \uac1c\ub150\uc774\ub2e4. "\ubaa8\ub4e0 \uc18c\ube44\uc790\uc5d0\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud558\ub2e4"\ub294 \uc124\uba85\uc740 \uad00\uc5ec\ub3c4\uc758 \uac1c\uc778\ucc28\xb7\uc0c1\ud669\ucc28\ub97c \ubb34\uc2dc\ud55c \uac83\uc73c\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.a8a,B.b4d,null)
