B.bAm=new A.a("gen_ba_mkt_consumer_4","business_admin","\ub9c8\ucf00\ud305","\uc18c\ube44\uc790 \uad6c\ub9e4\uc758\uc0ac\uacb0\uc815\uacfc\uc815","\uc778\uc9c0\ubd80\uc870\ud654(cognitive dissonance)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aqf,1,'\uc778\uc9c0\ubd80\uc870\ud654\ub294 \uad6c\ub9e4 "\uc774\ud6c4"\uc5d0 \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \ub300\uc548\uc758 \uc7a5\uc810\uc774\ub098 \uc120\ud0dd\ud55c \ub300\uc548\uc758 \ub2e8\uc810\uc774 \ub5a0\uc624\ub974\uba74\uc11c \ub290\ub07c\ub294 \uc2ec\ub9ac\uc801 \ubd88\ud3b8\ud568\uc744 \ub9d0\ud55c\ub2e4. \ub418\ub3cc\ub9ac\uae30 \uc5b4\ub835\uace0 \uad00\uc5ec\ub3c4\uac00 \ub192\uc740 \uace0\uac00\uc758 \ub0b4\uad6c\uc7ac \uad6c\ub9e4 \ud6c4\uc5d0 \ub354 \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.',B.aU9,B.ajm,null)
B.aeT=s(["\uac1c\uc778\uc758 \ud0dc\ub3c4\uc640 \ud589\ub3d9 \ud615\uc131\uc5d0 \uc9c1\uac04\uc811\uc801\uc73c\ub85c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc9d1\ub2e8\uc774\ub2e4","\uac00\uc871, \uce5c\uad6c\uc640 \uac19\uc740 1\ucc28 \uc900\uac70\uc9d1\ub2e8\uc740 \ub300\uccb4\ub85c \uc601\ud5a5\ub825\uc774 \ud06c\ub2e4","\ud76c\uad6c\uc9d1\ub2e8(aspirational group)\uc740 \uac1c\uc778\uc774 \uc18d\ud558\uace0 \uc2f6\uc5b4\ud558\ub294 \uc9d1\ub2e8\uc744 \ub9d0\ud55c\ub2e4","\uc900\uac70\uc9d1\ub2e8\uc758 \uc601\ud5a5\ub825\uc740 \uc81c\ud488\uc774 \uacf5\uac1c\uc801\uc73c\ub85c \uc18c\ube44\ub418\ub294\uc9c0 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.b4D=s(["\uc81c\ud488\uc774 \ub2e4\ub978 \uc0ac\ub78c \ub208\uc5d0 \ub744\ub294 \ubc29\uc2dd\uc73c\ub85c \uc18c\ube44\ub418\ub294 \uacf5\uac1c\uc801 \uc18c\ube44\uc7ac\uc77c\uc218\ub85d \ud06c\uac8c \ub098\ud0c0\ub098\uace0, \uc0ac\uc801\uc73c\ub85c \uc18c\ube44\ub418\ub294 \uc81c\ud488\uc77c\uc218\ub85d \uc791\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5"],t.s)
