B.brH=new A.a("gen_ba_mkt_consumer_5","business_admin","\ub9c8\ucf00\ud305","\uc18c\ube44\uc790 \uad6c\ub9e4\uc758\uc0ac\uacb0\uc815\uacfc\uc815","\uc18c\ube44\uc790\ud589\ub3d9\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc778 \uc911 \uc900\uac70\uc9d1\ub2e8(reference group)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aeT,3,'\uc900\uac70\uc9d1\ub2e8\uc758 \uc601\ud5a5\ub825\uc740 \uc81c\ud488\uc774 \ub2e4\ub978 \uc0ac\ub78c \ub208\uc5d0 \ub744\ub294 \ubc29\uc2dd\uc73c\ub85c \uc18c\ube44\ub418\ub294 \uacf5\uac1c\uc801 \uc18c\ube44\uc7ac(\uc0ac\uce58\ud488 \ub4f1)\uc77c\uc218\ub85d \ud06c\uac8c \ub098\ud0c0\ub098\uace0, \uc0ac\uc801\uc73c\ub85c \uc18c\ube44\ub418\ub294 \uc81c\ud488\uc77c\uc218\ub85d \uc791\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. "\ud56d\uc0c1 \ub3d9\uc77c\ud558\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.b4D,B.NM,null)
B.b6W=s(["\uc790\uc2e0\uc5d0\uac8c \ud544\uc694\ud55c \uc815\ubcf4\uc5d0\ub9cc \uc8fc\uc758\ub97c \uae30\uc6b8\uc774\uace0 \ub098\uba38\uc9c0\ub294 \ubb34\uc2dc\ud558\ub294 \uac83","\uc790\uc2e0\uc774 \uc774\ubbf8 \uac00\uc9c0\uace0 \uc788\ub294 \uc2e0\ub150\uc5d0 \ub9de\uac8c \uc815\ubcf4\ub97c \ud574\uc11d\ud558\ub294 \uac83","\uc811\ud55c \uc815\ubcf4\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74\uc11c \uc78a\uc5b4\ubc84\ub9ac\ub294 \uac83","\uc544\uc608 \uc815\ubcf4\ub97c \uc811\ud560 \uae30\ud68c \uc790\uccb4\uac00 \uc5c6\ub294 \uac83"],t.s)
