B.bov=new A.a("gen_ba_mkt_price_2","business_admin","\ub9c8\ucf00\ud305","\uac00\uaca9\uad00\ub9ac","\uc2ec\ub9ac\uc801 \uac00\uaca9\uc804\ub7b5\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.al1,3,"\ub2e8\uc218\uac00\uaca9, \uba85\uc131\uac00\uaca9, \uc900\uac70\uac00\uaca9\uc740 \ubaa8\ub450 \uc18c\ube44\uc790\uc758 \uc2ec\ub9ac\uc801 \uc9c0\uac01\uc744 \uc774\uc6a9\ud55c \uc2ec\ub9ac\uc801 \uac00\uaca9\uc804\ub7b5\uc774\ub2e4. \uc6d0\uac00\uac00\uc0b0\uac00\uaca9\uc740 \uc6d0\uac00\uc5d0 \uc77c\uc815 \ub9c8\uc9c4\uc744 \ub354\ud574 \uac00\uaca9\uc744 \uc815\ud558\ub294 \uc6d0\uac00\uc911\uc2ec \uac00\uaca9\uacb0\uc815\ubc29\ubc95\uc73c\ub85c, \uc18c\ube44\uc790 \uc2ec\ub9ac\uac00 \uc544\ub2cc \uae30\uc5c5\uc758 \ube44\uc6a9\uad6c\uc870\ub97c \uae30\uc900\uc73c\ub85c \ud55c\ub2e4.",B.VE,B.aq3,null)
