B.boz=new A.a("gen_ba_mkt_channel_5","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc18c\ube44\uc790 \ud310\ucd09\uc218\ub2e8\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.a08,3,"\ucfe0\ud3f0, \uc0d8\ud50c, \ub9ac\ubca0\uc774\ud2b8\ub294 \ucd5c\uc885\uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc18c\ube44\uc790 \ud310\ucd09\uc218\ub2e8\uc774\ub2e4. \uc911\uac04\uc0c1 \uacf5\uc81c\ub294 \uc81c\uc870\uc5c5\uc790\uac00 \uc720\ud1b5\uc5c5\uc790(\uc911\uac04\uc0c1)\uc758 \ud310\ub9e4\xb7\uc9c4\uc5f4 \ud611\uc870\uc5d0 \ub300\ud55c \ub300\uac00\ub85c \uc81c\uacf5\ud558\ub294 \uc720\ud1b5\uc5c5\uc790(\uc911\uac04\uc0c1) \ud310\ucd09\uc218\ub2e8\uc73c\ub85c \uad6c\ubd84\ub41c\ub2e4.",B.b2K,B.J3,null)
B.O7=s(["\uac00\ub9f9\ubcf8\ubd80(franchisor)\uac00 \uac00\ub9f9\uc810(franchisee)\uc5d0\uac8c \uc0c1\ud45c\xb7\ub178\ud558\uc6b0 \uc0ac\uc6a9\uad8c\uc744 \ubd80\uc5ec\ud558\uace0 \uadf8 \ub300\uac00\ub85c \ub85c\uc5f4\ud2f0\ub97c \ubc1b\ub294 \uacc4\uc57d\ud615 \uc720\ud1b5\uc2dc\uc2a4\ud15c\uc774\ub2e4","\uac00\ub9f9\uc810\uc8fc\ub294 \ubcf8\ubd80\uc758 \ud1b5\uc77c\ub41c \uc6b4\uc601 \ub9e4\ub274\uc5bc\uacfc \ud488\uc9c8\uae30\uc900\uc744 \ub530\ub77c\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4","\uac00\ub9f9\uc810\uc8fc\ub294 \ub3c5\ub9bd\ub41c \uc0ac\uc5c5\uc790\uc774\uc9c0\ub9cc \ubcf8\ubd80\uc640\uc758 \uacc4\uc57d\uc744 \ud1b5\ud574 \ube0c\ub79c\ub4dc \ud1b5\uc77c\uc131\uc744 \uc720\uc9c0\ud55c\ub2e4","\ud504\ub79c\ucc28\uc774\uc988 \uc2dc\uc2a4\ud15c\uc740 \uacc4\uc57d\uad00\uacc4\uac00 \uc804\ud600 \uc5c6\ub294 \uc804\ud1b5\uc801 \uc720\ud1b5\uacbd\ub85c\uc758 \ub300\ud45c\uc801 \uc0ac\ub840\uc774\ub2e4"],t.s)
B.acm=s(["\ud504\ub79c\ucc28\uc774\uc988 \uc2dc\uc2a4\ud15c\uc740 \uac00\ub9f9\ubcf8\ubd80\uc640 \uac00\ub9f9\uc810\uc774\ub77c\ub294 \ub3c5\ub9bd\ub41c \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacc4\uc57d\uc744 \ud1b5\ud574 \ud1b5\ud569\uc801\uc73c\ub85c \uc6b4\uc601\ub418\ub294 \ub300\ud45c\uc801\uc778 \uacc4\uc57d\ud615 \uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c(VMS)"],t.s)
