B.bwR=new A.a("gen_ba_ops_scm_5","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\ud601\uc2e0\uc801\uc778 \uc81c\ud488\uc744 \ucde8\uae09\ud558\ub294 \uae30\uc5c5\uc5d0 \uc801\ud569\ud55c \uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.QU,0,"\uc218\uc694 \ubcc0\ub3d9\uc131\uc774 \ud06c\uace0 \uc218\uba85\uc8fc\uae30\uac00 \uc9e7\uc740 \ud601\uc2e0\uc801 \uc81c\ud488\uc740 \ud488\uc808\ub85c \uc778\ud55c \uae30\ud68c\uc190\uc2e4\uc774 \ud06c\ubbc0\ub85c, \ub2e4\uc18c \ube44\uc6a9\uc774 \ub4e4\ub354\ub77c\ub3c4 \uc2dc\uc7a5 \ubcc0\ud654\uc5d0 \ube60\ub974\uac8c \ub300\uc751\ud560 \uc218 \uc788\ub294 \ubc18\uc751\uc801(responsive) \uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc774 \uc801\ud569\ud558\ub2e4. \ubc18\ub300\ub85c \uc218\uc694\uac00 \uc548\uc815\uc801\uc778 \uae30\ub2a5\uc801 \uc81c\ud488\uc5d0\ub294 \ube44\uc6a9 \ucd5c\uc18c\ud654\ub97c \ucd94\uad6c\ud558\ub294 \ud6a8\uc728\uc801(efficient) \uacf5\uae09\uc0ac\uc2ac\uc774 \uc801\ud569\ud558\ub2e4.",B.aMc,B.b4I,null)
B.aOF=s(["\uae30\uc5c5\uc774 \ubb3c\ub958 \uc804 \uacfc\uc815\uc744 \ubc18\ub4dc\uc2dc \uc9c1\uc811 \uc218\ud589\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc678\ubd80 \uc804\ubb38 \ubb3c\ub958\uc5c5\uccb4\uc5d0 \uc6b4\uc1a1\xb7\ubcf4\uad00\xb7\ud3ec\uc7a5 \ub4f1 \ubb3c\ub958\uc5c5\ubb34 \uc804\ubc18\uc744 \uc704\ud0c1\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uc81c\uc870\uc5c5\uccb4\uc640 \ucd5c\uc885\uc18c\ube44\uc790\ub97c \uc9c1\uc811 \uc5f0\uacb0\ud574 \ubb3c\ub958 \ub2e8\uacc4\ub97c \uc544\uc608 \uc5c6\uc560\ub294 \ubc29\uc2dd\uc774\ub2e4","\uc815\ubd80\uac00 \uc9c1\uc811 \uc6b4\uc601\ud558\ub294 \uacf5\uacf5 \ubb3c\ub958 \uc11c\ube44\uc2a4\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
