B.bAj=new A.a("gen_ba_mis_sec_4","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc815\ubcf4\ubcf4\uc548","\ubc29\ud654\ubcbd(firewall)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aA6,0,"\ubc29\ud654\ubcbd\uc740 \ubbf8\ub9ac \uc124\uc815\ub41c \ubcf4\uc548 \uaddc\uce59\uc5d0 \ub530\ub77c \ub0b4\ubd80 \ub124\ud2b8\uc6cc\ud06c\ub85c \ub4e4\uc5b4\uc624\uac70\ub098 \ub098\uac00\ub294 \ud2b8\ub798\ud53d\uc744 \uac10\uc2dc\ud558\uace0 \ud5c8\uc6a9\xb7\ucc28\ub2e8\uc744 \uacb0\uc815\ud558\ub294 \ub124\ud2b8\uc6cc\ud06c \ubcf4\uc548 \uc2dc\uc2a4\ud15c\uc73c\ub85c, \uc8fc\ub85c \uc678\ubd80\ub85c\ubd80\ud130\uc758 \ube44\uc778\uac00 \uc811\uadfc\uc744 \ud1b5\uc81c\ud558\ub294 \ub370 \uc0ac\uc6a9\ub41c\ub2e4. \ub0b4\ubd80\uc790\uc5d0 \uc758\ud55c \uc720\ucd9c\uae4c\uc9c0 \ubaa8\ub450 \ub9c9\uc544\uc8fc\ub294 \ub9cc\ub2a5 \uc7a5\uce58\ub294 \uc544\ub2c8\ub2e4.",B.Ow,B.ack,null)
B.ab9=s(["\uc778\uac00\ub41c \uc0ac\uc6a9\uc790\ub9cc \uc2dc\uc2a4\ud15c \uc790\uc6d0\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub3c4\ub85d \uc81c\ud55c\ud558\ub294 \ubcf4\uc548 \ud65c\ub3d9\uc774\ub2e4","\uc0ac\uc6a9\uc790 \uc778\uc99d, \uad8c\ud55c \ubd80\uc5ec, \uc811\uadfc \uae30\ub85d(\ub85c\uadf8) \uad00\ub9ac \ub4f1\uc774 \ud3ec\ud568\ub41c\ub2e4","\ucd5c\uc18c\uad8c\ud55c\uc758 \uc6d0\uce59\uc740 \uc5c5\ubb34 \uc218\ud589\uc5d0 \ud544\uc694\ud55c \ucd5c\uc18c\ud55c\uc758 \uad8c\ud55c\ub9cc\uc744 \ubd80\uc5ec\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\ud55c\ubc88 \ubd80\uc5ec\ub41c \uc811\uadfc\uad8c\ud55c\uc740 \uc870\uc9c1 \ub0b4 \uc9c1\ubb34\uac00 \ubcc0\uacbd\ub418\uc5b4\ub3c4 \uacc4\uc18d \uc720\uc9c0\ub418\uc5b4\uc57c \ud55c\ub2e4"],t.s)
