B.b_t=s(["IaaS\xb7PaaS\xb7SaaS\uc758 \uad6c\ubd84"],t.s)
B.bzh=new A.a("gen_ba_mis_trend_1","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\ud074\ub77c\uc6b0\ub4dc\ucef4\ud4e8\ud305 \uc11c\ube44\uc2a4 \ubaa8\ub378 \uc911 SaaS(Software as a Service)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aAd,2,"SaaS\ub294 \uc774\uba54\uc77c, \uadf8\ub8f9\uc6e8\uc5b4\uc640 \uac19\uc740 \uc644\uc131\ub41c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \uc0ac\uc6a9\uc790\uac00 \uc9c1\uc811 \uc124\uce58\ud558\uc9c0 \uc54a\uace0 \uc778\ud130\ub137\uc744 \ud1b5\ud574 \uad6c\ub3c5 \ud615\ud0dc\ub85c \uc774\uc6a9\ud558\ub294 \ud074\ub77c\uc6b0\ub4dc \uc11c\ube44\uc2a4 \ubaa8\ub378\uc774\ub2e4. \uc778\ud504\ub77c(\uc11c\ubc84\xb7\uc2a4\ud1a0\ub9ac\uc9c0)\ub9cc\uc744 \uc81c\uacf5\ud558\ub294 \uac83\uc740 IaaS, \uac1c\ubc1c \ud50c\ub7ab\ud3fc\uc744 \uc81c\uacf5\ud558\ub294 \uac83\uc740 PaaS\uc774\ub2e4.",B.aqk,B.b_t,null)
B.aK8=s(["\ub2e4\uc591\ud55c \uc0ac\ubb3c\uc5d0 \uc13c\uc11c\uc640 \ud1b5\uc2e0\uae30\ub2a5\uc744 \ud0d1\uc7ac\ud574 \uc778\ud130\ub137\uc744 \ud1b5\ud574 \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\ub3c4\ub85d \ud558\ub294 \uae30\uc220\uc774\ub2e4","\uc0ac\ub78c\uc758 \uac1c\uc785 \uc5c6\uc774\ub3c4 \uae30\uae30 \uac04 \ub370\uc774\ud130\ub97c \uc790\ub3d9\uc73c\ub85c \uc218\uc9d1\xb7\uc804\uc1a1\ud560 \uc218 \uc788\ub2e4","\uc2a4\ub9c8\ud2b8\ud329\ud1a0\ub9ac, \uc2a4\ub9c8\ud2b8\ud648 \ub4f1 \uc5ec\ub7ec \uc0b0\uc5c5 \ubd84\uc57c\uc5d0 \uc751\uc6a9\ub418\uace0 \uc788\ub2e4","\uc0ac\ubb3c \uac04 \ud1b5\uc2e0\uc744 \uc804\ud600 \ud3ec\ud568\ud558\uc9c0 \uc54a\uace0 \uc0ac\ub78c\uacfc \uc0ac\ub78c \uac04\uc758 \ud1b5\uc2e0\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.afk=s(['\ub2e4\uc591\ud55c "\uc0ac\ubb3c"\uc5d0 \uc13c\uc11c\uc640 \ud1b5\uc2e0 \uae30\ub2a5\uc744 \ud0d1\uc7ac\ud558\uc5ec \uc0ac\ubb3c \uac04\uc5d0 \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\ub3c4\ub85d \ud558\ub294 \uae30\uc220'],t.s)
