B.btX=new A.a("gen_trap_ba_6","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"STP \uc804\ub7b5\uacfc 4P \uc804\ub7b5\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.akq,0,'STP \uc804\ub7b5\uc740 "\ub204\uad6c\ub97c, \uc5b4\ub5a4 \uc704\uce58\ub85c" \uacf5\ub7b5\ud560\uc9c0\ub97c \uc815\ud558\ub294 \uc804\ub7b5\uc801 \ubc29\ud5a5 \uc124\uc815 \ub2e8\uacc4\uc774\uace0, 4P\ub294 \uadf8 \ubc29\ud5a5\uc744 \uc2e4\ud589\uc5d0 \uc62e\uae30\ub294 \uad6c\uccb4\uc801 \uc2e4\ud589 \uc218\ub2e8\uc774\ubbc0\ub85c, \ud1b5\uc0c1 STP\ub97c \uba3c\uc800 \uc218\ub9bd\ud55c \ud6c4 \uc774\uc5d0 \ub9de\ucdb0 4P \ubbf9\uc2a4\ub97c \uc124\uacc4\ud558\ub294 \uc21c\uc11c\ub85c \uc9c4\ud589\ub41c\ub2e4.',B.Te,B.aEY,null)
B.WN=s([u.dX,"\uc790\uc0b0\uacfc \ube44\uc6a9 \ubaa8\ub450 \uacfc\ub300\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\ubcf8\uc801 \uc9c0\ucd9c\uc744 \uc218\uc775\uc801 \uc9c0\ucd9c\ub85c \ucc98\ub9ac\ud574\ub3c4 \uc7ac\ubb34\uc81c\ud45c\uc5d0\ub294 \uc544\ubb34 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\uc0b0\uc774 \uacfc\ub300\uacc4\uc0c1\ub418\uace0 \ube44\uc6a9\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc774 \uacfc\ub300\uacc4\uc0c1\ub41c\ub2e4"],t.s)
