B.aNW=s(["\uc790\ubcf8\uc801 \uc9c0\ucd9c\xb7\uc218\uc775\uc801 \uc9c0\ucd9c \uc624\ubd84\ub958\uc758 \uc7ac\ubb34\uc81c\ud45c \uc601\ud5a5"],t.s)
B.bEa=new A.a("gen_trap_ba_7","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc720\ud615\uc790\uc0b0 \ucde8\ub4dd \ud6c4 \ubc1c\uc0dd\ud55c \uc9c0\ucd9c\uc744 \uc790\ubcf8\uc801 \uc9c0\ucd9c\ub85c \ucc98\ub9ac\ud574\uc57c \ud568\uc5d0\ub3c4 \uc218\uc775\uc801 \uc9c0\ucd9c\ub85c \uc798\ubabb \ucc98\ub9ac\ud55c \uacbd\uc6b0, \uc7ac\ubb34\uc81c\ud45c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.WN,0,"\uc6d0\ub798 \uc790\uc0b0\uc73c\ub85c \ucc98\ub9ac(\uc790\ubcf8\uc801 \uc9c0\ucd9c)\ud574\uc57c \ud560 \uc9c0\ucd9c\uc744 \ub2f9\uae30 \ube44\uc6a9(\uc218\uc775\uc801 \uc9c0\ucd9c)\uc73c\ub85c \uc798\ubabb \ucc98\ub9ac\ud558\uba74, \uadf8\ub9cc\ud07c \uc790\uc0b0\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\uace0 \ub2f9\uae30 \ube44\uc6a9\uc774 \uacfc\ub300\uacc4\uc0c1\ub418\uc5b4 \uacb0\uacfc\uc801\uc73c\ub85c \ub2f9\uae30\uc21c\uc774\uc775\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\ub294 \uc624\ub958\ub85c \uc774\uc5b4\uc9c4\ub2e4.",B.ahK,B.aNW,null)
B.OA=s(["\ud504\ub79c\ucc28\uc774\uc988\ub294 \uacc4\uc57d\uc73c\ub85c \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\ub85c, \uc804\uc18d\uc801 \uc720\ud1b5 \uad6c\uc870\ub97c \ucde8\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \ubcf8\uc0ac\uac00 \uc720\ud1b5\ub9dd\uc744 \uc9c1\uc811 \uc18c\uc720\ud558\ub294 \uae30\uc5c5\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\uc774\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \uc720\ud1b5\uacbd\ub85c \uad6c\uc131\uc6d0 \uac04 \ud798\uc758 \uc6b0\uc704\ub85c \ube44\uacf5\uc2dd \uc870\uc815\ub418\ub294 \uad00\ub9ac\ud615 VMS\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\ud504\ub79c\ucc28\uc774\uc988\ub294 \uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc774 \uc544\ub2c8\ub77c \uc218\ud3c9\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc758 \ub300\ud45c \uc0ac\ub840\uc774\ub2e4"],t.s)
B.a8B=s(["\ud504\ub79c\ucc28\uc774\uc988\ub294 \uacc4\uc57d\uc73c\ub85c \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840"],t.s)
B.VC=s(["\ud504\ub79c\ucc28\uc774\uc988\uc640 \uacc4\uc57d\ud615 VMS"],t.s)
B.bAF=new A.a("gen_trap_ba_8","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"\ud504\ub79c\ucc28\uc774\uc988(\uac00\ub9f9\uc0ac\uc5c5)\ub97c \uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c(VMS)\uc758 \uad00\uc810\uc5d0\uc11c \ubd84\ub958\ud558\uace0, \uadf8 \ud2b9\uc9d5\uc744 \uc124\uba85\ud55c \uac83\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.OA,0,"\uc218\uc9c1\uc801 \ub9c8\ucf00\ud305\uc2dc\uc2a4\ud15c\uc740 \uae30\uc5c5\ud615(\ubcf8\uc0ac \uc9c1\uc811 \uc18c\uc720)\xb7\uacc4\uc57d\ud615(\uacc4\uc57d\uc73c\ub85c \uacb0\ud569, \ud504\ub79c\ucc28\uc774\uc988 \ub300\ud45c)\xb7\uad00\ub9ac\ud615(\ube44\uacf5\uc2dd\uc801 \ud798\uc758 \uc6b0\uc704)\uc73c\ub85c \uad6c\ubd84\ub418\ub294\ub370, \ud504\ub79c\ucc28\uc774\uc988\ub294 \uac00\ub9f9\uacc4\uc57d\uc774\ub77c\ub294 \uacc4\uc57d\uc73c\ub85c \ubcf8\uc0ac\uc640 \uac00\ub9f9\uc810\uc774 \uacb0\ud569\ub418\ub294 \uacc4\uc57d\ud615 VMS\uc758 \ub300\ud45c \uc0ac\ub840\uc774\uba70, \ud1b5\uc0c1 \uc804\uc18d\uc801 \uc720\ud1b5 \uad6c\uc870\ub97c \ucde8\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.a8B,B.VC,null)
B.a0O=s(["ERP\ub294 \uc7ac\ubb34\xb7\uc0dd\uc0b0\xb7\uc778\uc0ac \ub4f1 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\xb7\ud504\ub85c\uc138\uc2a4\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub450\uace0, SCM\uc740 \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \uace0\uac1d\uae4c\uc9c0 \uc870\uc9c1 \uc678\ubd80\ub97c \uc544\uc6b0\ub974\ub294 \ubb3c\ub958\xb7\uc815\ubcf4 \ud750\ub984\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4","ERP\uc640 SCM\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ubc94\uc704\ub97c \ub2e4\ub8e8\ub294 \uc2dc\uc2a4\ud15c\uc774\ub77c \ud558\ub098\ub9cc \ub3c4\uc785\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4","SCM\uc740 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\uad00\ub9ac\uc5d0, ERP\ub294 \uacf5\uae09\uc5c5\uccb4\uc640\uc758 \uad00\uacc4\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4","ERP\ub294 \uace0\uac1d\uad00\uacc4\uad00\ub9ac(CRM)\uc758 \ud558\uc704 \uc2dc\uc2a4\ud15c\uc774\ub2e4"],t.s)
B.ajy=s(["ERP\ub294 \uc7ac\ubb34\xb7\uc0dd\uc0b0\xb7\uc778\uc0ac \ub4f1 \uc870\uc9c1 \ub0b4\ubd80 \uc790\uc6d0\xb7\ud504\ub85c\uc138\uc2a4\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub450\uace0, SCM\uc740 \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \uace0\uac1d\uae4c\uc9c0 \uc870\uc9c1 \uc678\ubd80\ub97c \uc544\uc6b0\ub974\ub294 \ubb3c\ub958\xb7\uc815\ubcf4 \ud750\ub984\uc758 \ud1b5\ud569\uad00\ub9ac\uc5d0 \ucd08\uc810"],t.s)
