B.beQ=new A.a("gen_trap_ba_9","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"ERP\uc640 SCM\uc744 \ud568\uaed8 \ub3c4\uc785\ud558\ub824\ub294 \uae30\uc5c5\uc774 \uc788\ub2e4\uba74, \ub450 \uc2dc\uc2a4\ud15c\uc758 \uc5ed\ud560 \ucc28\uc774\ub97c \uc633\uac8c \uc124\uba85\ud55c \uac83\uc740?",B.a0O,0,'ERP\ub294 \uc7ac\ubb34\xb7\uc0dd\uc0b0\xb7\uc778\uc0ac \ub4f1 \ud55c \uc870\uc9c1 "\ub0b4\ubd80"\uc758 \uc790\uc6d0\uacfc \ud504\ub85c\uc138\uc2a4\ub97c \ud558\ub098\ub85c \ud1b5\ud569 \uad00\ub9ac\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub450\ub294 \ubc18\uba74, SCM\uc740 \uc6d0\uc790\uc7ac \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \ucd5c\uc885 \uace0\uac1d\uae4c\uc9c0 \uc870\uc9c1\uc758 \uacbd\uacc4\ub97c \ub118\ub098\ub4dc\ub294 "\uc678\ubd80" \ubb3c\ub958\xb7\uc815\ubcf4 \ud750\ub984\uc744 \ud1b5\ud569 \uad00\ub9ac\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub454\ub2e4\ub294 \uc810\uc5d0\uc11c \ubc94\uc704\uc640 \uad00\uc810\uc774 \ub2e4\ub974\ub2e4.',B.ajy,B.axF,null)
B.aDm=s(["NPV\ubc95\uc740 \ud654\ud3d0\uc758 \uc2dc\uac04\uac00\uce58\ub97c \ubc18\uc601\ud558\uace0 \uac00\uce58\uac00\uc0b0\uc758 \uc6d0\uce59\uc774 \uc131\ub9bd\ud558\ub294 \ubc18\uba74, \ud68c\uc218\uae30\uac04\ubc95\uc740 \ud68c\uc218 \uc774\ud6c4\uc758 \ud604\uae08\ud750\ub984\uacfc \ud654\ud3d0\uc758 \uc2dc\uac04\uac00\uce58\ub97c \ucda9\ubd84\ud788 \uace0\ub824\ud558\uc9c0 \ubabb\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ud68c\uc218\uae30\uac04\ubc95\uc740 \ud654\ud3d0\uc758 \uc2dc\uac04\uac00\uce58\ub97c \ubc18\uc601\ud558\uc9c0\ub9cc NPV\ubc95\uc740 \ubc18\uc601\ud558\uc9c0 \ubabb\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","NPV\ubc95\uc740 \uacc4\uc0b0\uc774 \ub354 \uac04\ub2e8\ud574\uc11c \uc2e4\ubb34\uc790\ub4e4\uc774 \uc120\ud638\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ud68c\uc218\uae30\uac04\ubc95\uc740 \ud56d\uc0c1 NPV\ubc95\ubcf4\ub2e4 \ub354 \ubcf4\uc218\uc801\uc778 \ud22c\uc790 \uacb0\uc815\uc744 \ub0b4\ub9ac\uac8c \ud558\ubbc0\ub85c \uc774\ub860\uc801\uc73c\ub85c \uc6b0\uc218\ud558\ub2e4"],t.s)
