B.bdS=new A.a("gen_trap_kh_3","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,"\ud1b5\uc77c \uc2e0\ub77c\uc640 \ubc1c\ud574\uc758 \uc9c0\ubc29 \ud589\uc815 \uc81c\ub3c4\ub97c \uc11c\ub85c \ubc14\uafd4 \ud5f7\uac08\ub9ac\uae30 \uc26c\uc6b4\ub370, \ud1b5\uc77c \uc2e0\ub77c\uc758 \uc9c0\ubc29 \uc81c\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.apJ,0,'\ud1b5\uc77c \uc2e0\ub77c\ub294 \uc804\uad6d\uc744 9\uc8fc\ub85c \ub098\ub204\uace0, \uc218\ub3c4 \uacbd\uc8fc\uac00 \uad6d\ud1a0 \ub3d9\ub0a8\ucabd\uc5d0 \uce58\uc6b0\uce5c \uac83\uc744 \ubcf4\uc644\ud558\uae30 \uc704\ud574 \uc9c0\ubc29 \uc694\uc9c0\uc5d0 5\uc18c\uacbd\uc744 \ub450\uc5c8\ub2e4(9\uc8fc 5\uc18c\uacbd). "5\uacbd 15\ubd80 62\uc8fc"\ub294 \ubc1c\ud574\uc758 \uc9c0\ubc29 \uc81c\ub3c4\ub85c, \uc22b\uc790 \uad6c\uc131\uc774 \ube44\uc2b7\ud574 \uc790\uc8fc \ud5f7\uac08\ub9ac\ubbc0\ub85c "9\uc8fc 5\uc18c\uacbd=\uc2e0\ub77c", "5\uacbd 15\ubd80 62\uc8fc=\ubc1c\ud574"\ub85c \uba85\ud655\ud788 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. 5\ub3c4\xb7\uc591\uacc4\ub294 \uace0\ub824, 8\ub3c4 \uccb4\uc81c\ub294 \uc870\uc120\uc758 \uc81c\ub3c4\uc774\ub2e4.',B.b5J,B.aNO,null)
B.b19=s([u.ka,"\ub300\ud1b5\ub839 \uc9c1\uc120\uc81c\uc640 \uad6d\ud68c \uc591\uc6d0\uc81c\ub97c \uace8\uc790\ub85c \ud558\uba70, 6\xb725 \uc804\uc7c1 \uc911 \ubd80\uc0b0\uc5d0\uc11c \uacc4\uc5c4 \uc544\ub798 \ud1b5\uacfc\ub418\uc5c8\ub2e4","\ub300\ud1b5\ub839 \uc9c1\uc120\uc81c \uac1c\ud5cc\uc73c\ub85c, 6\uc6d4 \ubbfc\uc8fc \ud56d\uc7c1\uc758 \uacb0\uacfc\ub85c \uc774\ub8e8\uc5b4\uc84c\ub2e4","\ub0b4\uac01 \ucc45\uc784\uc81c \uac1c\ud5cc\uc73c\ub85c, 4\xb719 \ud601\uba85 \uc9c1\ud6c4 \ud5c8\uc815 \uacfc\ub3c4 \uc815\ubd80 \uc2dc\uae30\uc5d0 \uc774\ub8e8\uc5b4\uc84c\ub2e4"],t.s)
